local config = {
  ui_story_5004_50040101_1_dialog_content = "¡PlayerName!",
  ui_story_5004_50040101_2_dialog_content = "¡Retrocede, PlayerName!",
  ui_story_5004_50040101_3_dialog_content = "(Las olas enormes casi me derriban.)",
  ui_story_5004_50040101_4_dialog_content = "(Rayos de color púrpura y rojo parpadean contra el cielo oscuro y nublado. El rugido del trueno resuena en mis oídos.)",
  ui_story_5004_50040101_5_dialog_content = "(Observé los innumerables meteoritos que caían sobre nosotros desde arriba.)",
  ui_story_5004_50040101_6_dialog_content = "(El siniestro castillo negro se eleva lentamente desde las profundidades del océano, trayendo una sensación de melancolía.)",
  ui_story_5004_50040101_7_dialog_content = "(Vice y Carleen están al frente, tratando de protegerme en vano...)",
  ui_story_5004_50040101_8_dialog_content = "(Es muy tarde.)",
  ui_story_5004_50040101_9_dialog_content = "(Nunca pensé que yo sería responsable de la ruina y la destrucción que están por venir...)",
  ui_story_5004_50040101_10_dialog_content = "Entonces la dejaré a tu cuidado. Adiós.",
  ui_story_5004_50040101_11_dialog_content = "¡Espera, no puedes aparecer de repente con una chica y esperar que me ocupe de ella sin avisar!",
  ui_story_5004_50040101_12_dialog_content = "¡Ni siquiera sé su nombre!",
  ui_story_5004_50040101_13_dialog_content = "...",
  ui_story_5004_50040101_14_dialog_content = "Hola...",
  ui_story_5004_50040101_15_dialog_content = "Me llamo...",
  ui_story_5004_50040101_16_dialog_content = "Su nombre es <color=#FFB400>Beryl</color>. Ahora que estás familiarizado, me iré.",
  ui_story_5004_50040101_17_dialog_content = "¡Espera un poco! ¡Eso no es información suficiente!",
  ui_story_5004_50040101_18_dialog_content = "Bueno si insistes, PlayerName, Estaré feliz de iluminarte con La Verdad...",
  ui_story_5004_50040101_19_dialog_content = "¡No cambies de tema! Antes, ¿no dijiste que ella?...",
  ui_story_5004_50040101_20_dialog_content = "...",
  ui_story_5004_50040101_21_dialog_content = "Me refiero a Beryl, ¿está <color=#FFB400>enferma</color>? ¿Qué enfermedad?",
  ui_story_5004_50040101_22_dialog_content = "No estoy seguro.",
  ui_story_5004_50040101_23_dialog_content = "¿Qué?",
  ui_story_5004_50040101_24_dialog_content = "La dejo a tu cuidado porque no lo sé.",
  ui_story_5004_50040101_25_dialog_content = "Eres un Celestita con habilidades psíquicas, rodeado de Aurorians muy versados en sanación lumínica.",
  ui_story_5004_50040101_26_dialog_content = "Srta. Victoria y yo estuvimos de acuerdo en que sería mejor que la cuidaras.",
  ui_story_5004_50040101_27_dialog_content = "¿Desde cuándo True Order es una organización benéfica?",
  ui_story_5004_50040101_28_dialog_content = "...",
  ui_story_5004_50040101_29_dialog_content = "Espera, Faust, intentemos otra manera.",
  ui_story_5004_50040101_30_dialog_content = "Es decir...",
  ui_story_5004_50040101_31_dialog_content = "Es ella...",
  ui_story_5004_50040101_32_option_content = "¿La hija de Srta. Victoria?",
  ui_story_5004_50040101_33_dialog_content = "No. Srta. Victoria se dedica exclusivamente a la búsqueda de La Verdad. Ella no tiene deseos tan mundanos.",
  ui_story_5004_50040101_34_option_content = "¡¿Ofreces a Beryl como sacrificio por uno de tus espeluznantes rituales?!",
  ui_story_5004_50040101_35_dialog_content = "Claro que no. Por favor, no difames nuestra búsqueda de la Verdad.",
  ui_story_5004_50040101_36_dialog_content = "Además, Beryl es un miembro importante de True Order.",
  ui_story_5004_50040101_37_dialog_content = "Hmm...",
  ui_story_5004_50040101_38_dialog_content = "Ok, siempre y cuando no suceda nada sospechoso...",
  ui_story_5004_50040101_39_dialog_content = "Todavía no entiendo por qué Srta. Victoria me eligió.",
  ui_story_5004_50040101_40_dialog_content = "No es necesario tratar de comprender sus decisiones.",
  ui_story_5004_50040101_41_dialog_content = "Nos acercamos a La Verdad siguiendo y cumpliendo sus órdenes.",
  ui_story_5004_50040101_42_dialog_content = "(Eso solo me hace sospechar aún más...)",
  ui_story_5004_50040101_43_dialog_content = "Bueno, dado que Raphaela está en el Colossus en este momento, bien podría hacerle una visita.",
  ui_story_5004_50040101_44_dialog_content = "<color=#e8d9bb>Unos minutos después...</color>",
  ui_story_5004_50040101_45_dialog_content = "Mmm...",
  ui_story_5004_50040101_46_dialog_content = "Hmm... Uh-huh...",
  ui_story_5004_50040101_47_dialog_content = "¿Cómo va todo?",
  ui_story_5004_50040101_48_dialog_content = "Después de intentarlo todo, todavía no puedo decir qué le pasa.",
  ui_story_5004_50040101_49_dialog_content = "Tu nombre es Beryl, ¿verdad?",
  ui_story_5004_50040101_50_dialog_content = "Si.",
  ui_story_5004_50040101_51_dialog_content = "Y, Beryl, ¿sientes dolor en alguna parte?",
  ui_story_5004_50040101_52_dialog_content = "¿Beryl...?",
  ui_story_5004_50040101_53_dialog_content = "Lo siento, soy lenta para comprender cómo se siente mi cuerpo.",
  ui_story_5004_50040101_54_dialog_content = "Últimamente he estado muy cansada y tengo problemas para controlar mi Lumina...",
  ui_story_5004_50040101_55_dialog_content = "A veces sentía un dolor tremendo en todo el cuerpo, como si me comieran vivo millones de insectos.",
  ui_story_5004_50040101_56_dialog_content = "Ya veo.",
  ui_story_5004_50040101_57_dialog_content = "Es la primera vez que veo a un paciente con tus síntomas.",
  ui_story_5004_50040101_58_dialog_content = "¿Qué opinas, PlayerName?",
  ui_story_5004_50040101_59_dialog_content = "(Beryl frunce el ceño como si tuviera algo en mente.)",
  ui_story_5004_50040101_60_option_content = "¿Quizás no está contenta por algo?",
  ui_story_5004_50040101_61_dialog_content = "¡Eso es posible!",
  ui_story_5004_50040101_62_dialog_content = "Carleen ponía esa cara cada vez que discutía con el señor de la ciudad.",
  ui_story_5004_50040101_63_dialog_content = "Como Beryl ahora.",
  ui_story_5004_50040101_64_option_content = "Tal vez usando mi habilidad psíquica...",
  ui_story_5004_50040101_65_dialog_content = "¡No! ¡Eso es muy invasivo para una niña!",
  ui_story_5004_50040101_66_dialog_content = "¡Es como abrirla para encontrar la causa!",
  ui_story_5004_50040101_67_dialog_content = "¡De todas formas!",
  ui_story_5004_50040101_68_dialog_content = "Ya sea que el problema sea físico o mental, ¡yo puedo!",
  ui_story_5004_50040101_69_dialog_content = "No te preocupes, Beryl. Como tu médica de cabecera, ¡estaré a tu lado!",
  ui_story_5004_50040101_70_dialog_content = "¡Encontraré la causa y te regresaré a la normalidad en poco tiempo!",
  ui_story_5004_50040101_71_dialog_content = "En poco tiempo... Mejor no significar que no le quede mucho tiempo...",
  ui_story_5004_50040101_72_dialog_content = "¡PlayerName!",
  ui_story_5004_50040101_X72_dialog_content = "¡No hagas una broma así delante del paciente!",
  ui_story_5004_50040101_73_dialog_content = "Gracias.",
  ui_story_5004_50040101_74_dialog_content = "¿Qué pasa?",
  ui_story_5004_50040101_75_dialog_content = "Hola, PlayerName. Ah, hola Raphaela. Veo que también estás aquí.",
  ui_story_5004_50040101_76_dialog_content = "¡Carleen! ¿Qué estás haciendo acá?",
  ui_story_5004_50040101_77_dialog_content = "Estoy aquí representando a Lumopolis en una visita oficial regular y charlando con Vice mientras lo hago.",
  ui_story_5004_50040101_78_dialog_content = "¿Y estos dos son...?",
  ui_story_5004_50040101_79_dialog_content = "Este es Faust.",
  ui_story_5004_50040101_80_dialog_content = "Buen día señora.",
  ui_story_5004_50040101_81_dialog_content = "¿Estás con <color=#FFB400>True Order</color>?",
  ui_story_5004_50040101_82_dialog_content = "No esperaba que supieras acerca de True Order.",
  ui_story_5004_50040101_83_dialog_content = "¿También eres una buscadora de la verdad?",
  ui_story_5004_50040101_84_dialog_content = "No me interesa la tal Verdad. Tengo mis creencias.",
  ui_story_5004_50040101_85_dialog_content = "Qué pena.",
  ui_story_5004_50040101_86_dialog_content = "Sin embargo, mientras consideres La Verdad, estás un paso más cerca de La Verdad.",
  ui_story_5004_50040101_87_dialog_content = "Quizás nos encontremos al final.",
  ui_story_5004_50040101_88_dialog_content = "Qué indiferente... ¿Quién es la chica, PlayerName?",
  ui_story_5004_50040101_89_dialog_content = "Su nombre es Beryl. Faust la trajo, parece ser una amiga.",
  ui_story_5004_50040101_90_dialog_content = "Beryl está bajo mi cuidado, Carleen.",
  ui_story_5004_50040101_91_dialog_content = "Ya veo. Muy bien, Raphaela.",
  ui_story_5004_50040101_92_dialog_content = "Cuida mucho al paciente en nombre de White Night.",
  ui_story_5004_50040101_93_dialog_content = "¡Heehee, claro!",
  ui_story_5004_50040101_94_dialog_content = "Pero todavía no sabemos qué le preocupa a Beryl.",
  ui_story_5004_50040101_X94_dialog_content = "Creemos que es mental o relacionado con el estrés.",
  ui_story_5004_50040101_95_dialog_content = "¿Puedes tratar enfermedades mentales? ¡Supongo eres más que un ángel de combate que dispara misiles!",
  ui_story_5004_50040101_96_dialog_content = "¡No subestimes a los Ángeles de Lumopolis, Vice!",
  ui_story_5004_50040101_97_dialog_content = "(¡Bien, parece que Raphaela se lleva bien con Vice!)",
  ui_story_5004_50040101_98_dialog_content = "¿Y esa estúpida sonrisa, PlayerName? Oh, traje algo asombroso.",
  ui_story_5004_50040101_99_dialog_content = "Quizás te resulte útil.",
  ui_story_5004_50040101_100_dialog_content = "Aquí tienes la carta.",
  ui_story_5004_50040101_101_dialog_content = "¿Una carta para mí?",
  ui_story_5004_50040101_102_dialog_content = "Eho me lo entregó antes de salir corriendo. El sobre dice: <color=#FFB400>Tir' Hotel</color>.",
  ui_story_5004_50040101_103_dialog_content = "Pero, no aparece remitente.",
  ui_story_5004_50040101_104_dialog_content = "¿Vas a abrirlo?",
  ui_story_5004_50040101_105_option_content = "Es muy sospechoso. ¿Mas tarde?",
  ui_story_5004_50040101_106_dialog_content = "No seas tan tímido. ¡Estará bien!",
  ui_story_5004_50040101_107_dialog_content = "¡Déjame abrirlo por ti!",
  ui_story_5004_50040101_108_dialog_content = "¡Cuidado, podría explotar!",
  ui_story_5004_50040101_109_dialog_content = "Es solo un papel por dentro, y uno fino, en mate.",
  ui_story_5004_50040101_110_dialog_content = "Uf, no pasó nada, gracias a Dios.",
  ui_story_5004_50040101_111_option_content = "Debería estar bien. Abrámoslo.",
  ui_story_5004_50040101_112_dialog_content = "Ábrelo. También quiero saber qué hay dentro.",
  ui_story_5004_50040101_113_dialog_content = "Hmm, es solo una hoja de papel.",
  ui_story_5004_50040101_114_dialog_content = "¿Eso es todo?",
  ui_story_5004_50040101_115_dialog_content = "¿Qué dice, PlayerName?",
  ui_story_5004_50040101_116_dialog_content = "Bien...",
  ui_story_5004_50040101_117_dialog_content = "Estimado PlayerName,",
  ui_story_5004_50040101_118_dialog_content = "Te invitamos cordialmente a visitar el Tir’ Hotel durante tus vacaciones.",
  ui_story_5004_50040101_X118_dialog_content = "Únete al emocionante evento <color=#FFB400>Soberano del Océano</color>.",
  ui_story_5004_50040101_119_dialog_content = "Se adjunta una invitación válida para hasta seis amigos más en tu grupo.",
  ui_story_5004_50040101_120_dialog_content = "¡Disfruta la suite de lujo gratis y demás comodidades!",
  ui_story_5004_50040101_121_dialog_content = "¡Maravilloso! ¡Me moría de ganas de ir a la playa!",
  ui_story_5004_50040101_122_dialog_content = "¡El festival debería hacer mucho bien a Beryl!",
  ui_story_5004_50040101_123_dialog_content = "Si su condición está relacionada con el estrés, ¡un viaje divertido podría ayudar!",
  ui_story_5004_50040101_124_dialog_content = "Vamos a la playa con Beryl, PlayerName, ¿por favor?",
  ui_story_5004_50040101_125_dialog_content = "Espera, todavía estoy procesando esto. Ni siquiera he oído hablar del lugar...",
  ui_story_5004_50040101_126_dialog_content = "No te preocupes, PlayerName, el complejo es bastante famoso.",
  ui_story_5004_50040101_127_dialog_content = "Es cierto, el Tir' Hotel se ha hecho un nombre en el círculo noble de Lumo. Incluso escuché sobre eso.",
  ui_story_5004_50040101_128_dialog_content = "Supuestamente, el propietario tiene un excelente negocio.",
  ui_story_5004_50040101_129_dialog_content = "La invitación y el tal Soberano del Océano probablemente sean solo una exageración de publicidad.",
  ui_story_5004_50040101_130_dialog_content = "Pero, ¿por qué me invitarían?",
  ui_story_5004_50040101_131_dialog_content = "Podría ser una especie de truco publicitario.",
  ui_story_5004_50040101_132_dialog_content = "Los Aurorians sienten mucha curiosidad por los Celestitas.",
  ui_story_5004_50040101_133_dialog_content = "La instalación, habitación o incluso una mesa en la que un Celestita se quedara o comiera podría ser un plan para promocionar el complejo.",
  ui_story_5004_50040101_134_dialog_content = "Eso me hace sonar como una especie de animal exótico...",
  ui_story_5004_50040101_135_dialog_content = "...",
  ui_story_5004_50040101_136_dialog_content = ".",
  ui_story_5004_50040101_137_dialog_content = "¿Ni siquiera vas a refutar eso?",
  ui_story_5004_50040101_138_dialog_content = "Dado que es un lugar de ocio para los nobles y nos beneficia a ellos como a nosotros...",
  ui_story_5004_50040101_139_dialog_content = "Debería ser muy seguro, ¿verdad?",
  ui_story_5004_50040101_140_dialog_content = "Parece que hay consenso.",
  ui_story_5004_50040101_141_dialog_content = "¿Sigues aquí?",
  ui_story_5004_50040101_142_dialog_content = "Te dejaré a Beryl. Disfruten el viaje. Adiós.",
  ui_story_5004_50040101_143_dialog_content = "Faust va y viene como el viento como siempre.",
  ui_story_5004_50040101_144_dialog_content = "¡Excelente! ¡Cumpliré con mi deber médico y te cuidaré bien, Beryl!",
  ui_story_5004_50040101_145_dialog_content = "Simplemente no creo que todo sea tan simple como parece...",
  ui_story_5004_50040101_146_dialog_content = "¡Mira allí! ¡Ahí está el mar!",
  ui_story_5004_50040101_147_dialog_content = "Esta es la primera vez que veo el océano, PlayerName.",
  ui_story_5004_50040101_148_dialog_content = "¿Tú también, Vice?",
  ui_story_5004_50040101_149_dialog_content = "Pensé que era el único...",
  ui_story_5004_50040101_150_dialog_content = "¡Por supuesto que no eres el único! Después de todo, es difícil llegar tan lejos sin un Colossus.",
  ui_story_5004_50040101_151_dialog_content = "La brisa del mar es agradable. El azul seductor realmente ayuda a relajar la mente.",
  ui_story_5004_50040101_152_dialog_content = "¡Esto hará maravillas con Beryl!",
  ui_story_5004_50040101_153_dialog_content = "Sigues diciendo que es para Beryl, pero en realidad querías divertirte en la playa, ¿eh?",
  ui_story_5004_50040101_154_dialog_content = "Sí, esa es una razón.",
  ui_story_5004_50040101_155_dialog_content = "Porque para la mayoría de los Aurorians, ir a la playa es raro.",
  ui_story_5004_50040101_156_dialog_content = "Probablemente no lo entiendas, habiendo vivido tanto tiempo en el Colossus.",
  ui_story_5004_50040101_157_dialog_content = "¡Para los Aurorians, las vacaciones en la playa son ahora un <color=#FFB400>rito de iniciación</color>!",
  ui_story_5004_50040101_158_dialog_content = "¿Por qué dirías eso?",
  ui_story_5004_50040101_159_dialog_content = "Piénsalo, muchos Eclipsites ahora se encuentran a lo largo de la costa.",
  ui_story_5004_50040101_160_dialog_content = "Debes estar preparado para sus ataques mientras disfrutas del sol y las olas.",
  ui_story_5004_50040101_161_dialog_content = "¿No es desafiante la combinación de peligro y relajación?",
  ui_story_5004_50040101_162_dialog_content = "¿Desafiante? ¡Eso suena increíblemente peligroso!",
  ui_story_5004_50040101_163_dialog_content = "Digamos que estoy enterrado en la arena y aparecen los Eclipsites.",
  ui_story_5004_50040101_164_dialog_content = "No me vas a abandonar y huir, ¿verdad, Vice?",
  ui_story_5004_50040101_165_dialog_content = "¿No somos amigos? ¡Nunca haría eso!",
  ui_story_5004_50040101_166_dialog_content = "Igualmente, el sol más el agua de mar fresca es bueno para la mente.",
  ui_story_5004_50040101_167_dialog_content = "Beryl puede y se relajará con seguridad.",
  ui_story_5004_50040101_168_dialog_content = "El agua de mar es para nadar, ¿sí? Pero no empacamos <color=#FFB400>traje de baño</color>.",
  ui_story_5004_50040101_169_dialog_content = "No tienes que preocuparte por eso ni un poco.",
  ui_story_5004_50040101_170_dialog_content = "Sé que el resort vende su propia marca de trajes de baño.",
  ui_story_5004_50040101_171_dialog_content = "Sus clientelas son los nobles de Lumopolis.",
  ui_story_5004_50040101_172_dialog_content = "¿Venden trajes de baño? Eso cubre todas las bases.",
  ui_story_5004_50040101_173_dialog_content = "Por supuesto. El traje de baño es como una armadura para el campo de batalla.",
  ui_story_5004_50040101_174_dialog_content = "Ya sea un soldado de Illumina o un noble de Lumopolis, el traje de baño es imprescindible en la playa.",
  ui_story_5004_50040101_175_dialog_content = "¡Es simple etiqueta de playa!",
  ui_story_5004_50040101_176_dialog_content = "Ok...",
  ui_story_5004_50040101_177_dialog_content = "(¿En qué se diferencia de lo que me dijo Soroz? ¿Para eso es el traje de baño?)",
  ui_story_5004_50040101_178_dialog_content = "¿Cómo sabes tanto sobre hoteles y trajes de baño, Carleen?",
  ui_story_5004_50040101_179_dialog_content = "¿Es extraño? Al final, soy la Capitana de los Guardianes de Lumopolis.",
  ui_story_5004_50040101_180_dialog_content = "Es mi trabajo estar al día con las tendencias entre los nobles.",
  ui_story_5004_50040101_181_dialog_content = "De todos modos, espero mi traje de baño, PlayerName.",
  ui_story_5004_50040101_182_dialog_content = "(¿Carleen en traje de baño?)",
  ui_story_5004_50040101_183_dialog_content = "Uh, claro.",
  ui_story_5004_50040101_184_dialog_content = "¿Por qué sigues mirándome así, PlayerName?",
  ui_story_5004_50040101_185_dialog_content = "¿Me veo rara?",
  ui_story_5004_50040101_186_dialog_content = "¡No, para nada! Oh, ¿qué más sabes sobre este complejo hotelero?",
  ui_story_5004_50040101_187_dialog_content = "Sé que solía pertenecer a un noble de Lumopolis.",
  ui_story_5004_50040101_188_dialog_content = "Hasta que se vendió a una parte desconocida en Umbraton por un negocio fallido.",
  ui_story_5004_50040101_189_dialog_content = "Umbraton ya es un lugar confuso, por lo que es difícil validar esa información.",
  ui_story_5004_50040101_190_dialog_content = "Por no hablar de un desconocido que hace todo lo posible para esconderse.",
  ui_story_5004_50040101_191_dialog_content = "Los forasteros ni siquiera lo olerían sin una fuente local competente.",
  ui_story_5004_50040101_192_dialog_content = "Ya veo. Umbraton es inescrutable.",
  ui_story_5004_50040101_193_dialog_content = "Si. Debe toda la estabilidad y armonía presentes a...",
  ui_story_5004_50040101_194_dialog_content = "¡Espera, detente con los temas serios!",
  ui_story_5004_50040101_195_dialog_content = "¡Nuestro objetivo es ayudar a Beryl a relajarse y recuperarse!",
  ui_story_5004_50040101_196_dialog_content = "Estoy bien.",
  ui_story_5004_50040101_197_dialog_content = "!!!",
  ui_story_5004_50040101_198_dialog_content = "¡¿PlayerName?!",
  ui_story_5004_50040101_199_dialog_content = "¡Soroz!",
  ui_story_5004_50040101_200_dialog_content = "Fuerte interferencia con el sistema de pilotaje detectada en la dirección del destino, PlayerName.",
  ui_story_5004_50040101_201_dialog_content = "Si continuamos, podríamos perder el control.",
  ui_story_5004_50040101_202_dialog_content = "¡Ugh...!",
  ui_story_5004_50040101_203_dialog_content = "¿Beryl?",
  ui_story_5004_50040101_204_dialog_content = "¿Qué ocurre?",
  ui_story_5004_50040101_205_dialog_content = "¡Aléjate del destino, Soroz, y encuentra un lugar para aterrizar de inmediato!",
  ui_story_5004_50040101_206_dialog_content = "Entendido.",
  ui_story_5004_50040101_207_dialog_content = "¿Estás bien, Beryl?",
  ui_story_5004_50040101_208_dialog_content = "Dónde...",
  ui_story_5004_50040101_209_dialog_content = "¿Dónde estoy?",
  ui_story_5004_50040101_210_dialog_content = "El calor de las llamas, el olor a humo y los gritos de muchos Aurorians...",
  ui_story_5004_50040101_211_dialog_content = "Pero no puedo ver nada...",
  ui_story_5004_50040101_212_dialog_content = "¿Dónde estoy?",
  ui_story_5004_50040101_213_dialog_content = "¡PlayerName!",
  ui_story_5004_50040101_214_dialog_content = "¡¡PlayerName!!",
  ui_story_5004_50040101_215_dialog_content = "¿Vice?",
  ui_story_5004_50040101_216_dialog_content = "¿Estás bien, PlayerName?",
  ui_story_5004_50040101_217_dialog_content = "¿Qué paso?",
  ui_story_5004_50040101_218_dialog_content = "Te congelaste al tropezar con Beryl.",
  ui_story_5004_50040101_219_dialog_content = "¿Sentiste algo?",
  ui_story_5004_50040101_220_dialog_content = "Sí, pero estaba borroso... No importa. ¿Cuál es nuestra situación actual?",
  ui_story_5004_50040101_221_dialog_content = "Estamos fuera del rango de interferencia, ahora busco un lugar para aterrizar.",
  ui_story_5004_50040101_222_dialog_content = "¿Estás bien, Beryl?",
  ui_story_5004_50040101_223_dialog_content = "Sí...",
  ui_story_5004_50040101_224_dialog_content = "¿Qué fue eso?",
  ui_story_5004_50040201_1_dialog_content = "¿Qué... por qué tengo que llevarlos? ¡No fui yo quien causó que el Colossus aterrizara!",
  ui_story_5004_50040201_2_dialog_content = "Estaba pensando en jugar en el bar.",
  ui_story_5004_50040201_3_dialog_content = "¿Ese complejo de como lo llames realmente tiene un sistema estéreo de súper lujo?",
  ui_story_5004_50040201_4_dialog_content = "Si te atreves a mentirme... ¡Te asaré con el poder del sol abrasador!",
  ui_story_5004_50040201_5_dialog_content = "¡Deja de golpear el techo antes de que me caiga!",
  ui_story_5004_50040201_6_dialog_content = "Deberían tenerlo...",
  ui_story_5004_50040201_7_dialog_content = "Si no...",
  ui_story_5004_50040201_8_dialog_content = "¡Reemplazaré el estéreo del Colossus con ese sistema Boom que querías!",
  ui_story_5004_50040201_9_dialog_content = "Concéntrate en conducir. ¡Sigo en el techo! Gracias.",
  ui_story_5004_50040201_10_dialog_content = "Lo siento, PlayerName tuvo que quedarse en el techo del auto.",
  ui_story_5004_50040201_11_dialog_content = "Está bien. Estoy bien.",
  ui_story_5004_50040201_12_dialog_content = "No sería apropiado para las chicas.",
  ui_story_5004_50040201_13_dialog_content = "No esperaba que fueras tan considerado, PlayerName.",
  ui_story_5004_50040201_14_dialog_content = "¡Mantén tus ojos en la carretera! ¡Y tus manos, en el volante, por favor!",
  ui_story_5004_50040201_15_dialog_content = "No te preocupes. ¡Cada miembro de Rediesel Wrench nació para conducir!",
  ui_story_5004_50040201_16_dialog_content = "Y si aparece un Eclipsite de alto nivel, lo atropellaré de inmediato.",
  ui_story_5004_50040201_17_dialog_content = "Tienes mucha suerte de tener el <color=#FFB400>coche</color> de <color=#FFB400>Brock</color> en el garaje aquí, o estarías caminando...",
  ui_story_5004_50040201_18_dialog_content = "¡Cuidado!",
  ui_story_5004_50040201_19_dialog_content = "¡Eclipsites, Regina!",
  ui_story_5004_50040201_20_dialog_content = "¿Ah?",
  ui_story_5004_50040201_21_dialog_content = "¡Ay! ¡Malditos Eclipsites aparecen de la nada! Primera vez conduciendo en veinte años...",
  ui_story_5004_50040201_22_dialog_content = "¡Gahhhhhh!",
  ui_story_5004_50040201_23_dialog_content = "Uf, qué mareo... ¿El impacto arrojó al Eclipsite a volar?",
  ui_story_5004_50040201_24_dialog_content = "¿Están todos bien?",
  ui_story_5004_50040201_25_dialog_content = "Sí, solo un rasguño.",
  ui_story_5004_50040201_26_dialog_content = "¡Wooga!",
  ui_story_5004_50040201_27_dialog_content = "¿De dónde vinieron todos estos Eclipsites? ¡Prepárense para luchar!",
  ui_story_5004_50040201_28_dialog_content = "¡Apúrate! ¡Las armas están en el maletero!",
  ui_story_5004_50040201_29_dialog_content = "¡Pronto estaremos rodeados!",
  ui_story_5004_50040201_30_dialog_content = "¡Beryl, despierta, Beryl!",
  ui_story_5004_50040201_31_dialog_content = "Oh...",
  ui_story_5004_50040201_32_dialog_content = "Raphaela...",
  ui_story_5004_50040201_33_dialog_content = "¡Cuidado!",
  ui_story_5004_50040201_34_dialog_content = "¡...!",
  ui_story_5004_50040201_35_dialog_content = "Cristal...",
  ui_story_5004_50040201_36_dialog_content = "Gah...",
  ui_story_5004_50040201_37_dialog_content = "¡¡Gah!! ¡¡¡Gah!!!",
  ui_story_5004_50040201_38_dialog_content = "¡Están embistiendo el coche para volcarlo!",
  ui_story_5004_50040201_39_dialog_content = "¡Florece!",
  ui_story_5004_50040201_40_dialog_content = "Grr...",
  ui_story_5004_50040201_41_dialog_content = "¡Vaya, eso fue rápido!",
  ui_story_5004_50040201_42_dialog_content = "No esperaba que fueras tan poderosa... Supongo que no se puede subestimar a True Order.",
  ui_story_5004_50040201_43_dialog_content = "La cantidad de cristales liberados y los Eclipsites derrotados en un abrir y cerrar de ojos, rivalizan en poder con los Ángeles de Lumopolis.",
  ui_story_5004_50040201_44_dialog_content = "Así es.",
  ui_story_5004_50040201_45_dialog_content = "Eso fue asombroso... ¡Oh, gracias Beryl!",
  ui_story_5004_50040201_46_dialog_content = "Huff, huff...",
  ui_story_5004_50040201_47_dialog_content = "¿Estás bien, Beryl?",
  ui_story_5004_50040201_48_dialog_content = "¿Terminaron de hablar, chicas? ¡Cogen tus armas, vienen más Eclipsites!",
  ui_story_5004_50040301_1_dialog_content = "Vaya, casi ahí. No quiero conducir nunca más.",
  ui_story_5004_50040301_2_dialog_content = "Gracias por entregarnos en una sola pieza.",
  ui_story_5004_50040301_3_dialog_content = "No seas sarcástico y encuentra donde estacionar.",
  ui_story_5004_50040301_4_dialog_content = "Hey, ¿qué hacen ustedes aquí?",
  ui_story_5004_50040301_5_dialog_content = "Hey... ¿Por qué está abollado el capó de mi auto?",
  ui_story_5004_50040301_6_dialog_content = "Aun si somos amigos, PlayerName, ¡debes contarme lo que pasó!",
  ui_story_5004_50040301_7_option_content = "Bueno, en realidad, Regina quería sacar el auto a dar una vuelta...",
  ui_story_5004_50040301_8_dialog_content = "Buen intento. Ella no conduciría incluso si quisiera dar una vuelta.",
  ui_story_5004_50040301_9_dialog_content = "¿Qué tienes sobre ella?",
  ui_story_5004_50040301_10_dialog_content = "¡Hey! ¿Parezco alguien que tiene algo que esconder?",
  ui_story_5004_50040301_11_dialog_content = "¿Entonces PlayerName acordó mejorar el sistema estéreo por ti?",
  ui_story_5004_50040301_12_dialog_content = "No puedo creerlo Brock, ¡lo adivinaste!",
  ui_story_5004_50040301_13_dialog_content = "¿Por qué no? ¡No soy estúpido! ¡Vi a través de inmediato!",
  ui_story_5004_50040301_14_option_content = "¡Arreglé el auto y decidí atropellarlo específicamente para ti!",
  ui_story_5004_50040301_15_dialog_content = "¿En serio? ¿Te dije que estaría aquí?",
  ui_story_5004_50040301_16_dialog_content = "Usé habilidades psíquicas. Sí, psíquico.",
  ui_story_5004_50040301_17_dialog_content = "¿Tan lejos? ¡Increíble!",
  ui_story_5004_50040301_18_dialog_content = "El golpe en el capó se forma como una Eclipsite...",
  ui_story_5004_50040301_19_dialog_content = "¿Lo notas?",
  ui_story_5004_50040301_20_dialog_content = "No me subestimes. Choco contra más de varios cientos de Eclipsites al año.",
  ui_story_5004_50040301_21_dialog_content = "¡Me sé la forma de memoria! ¿Chocaste con un Rompelineas?",
  ui_story_5004_50040301_22_dialog_content = "¿Incluso conoces el tipo? Vaya, lo siento, lo repararé más tarde.",
  ui_story_5004_50040301_23_dialog_content = "No te preocupes mucho, acabas de agregar otro al recuento de muertes de mi bebé.",
  ui_story_5004_50040301_24_dialog_content = "Le pediré a mi amigo que es <color=#FFB400>mecánico</color> que lo arregle.",
  ui_story_5004_50040301_25_dialog_content = "Y, ¿para qué viniste aquí, unas vacaciones?",
  ui_story_5004_50040301_26_dialog_content = "¡Sí! PlayerName recibió una invitación del Tir' Hotel, ¡todos los gastos pagados!",
  ui_story_5004_50040301_27_dialog_content = "¿Qué? Eso es inusual. No sabía que el dueño del hotel fuera tan generoso.",
  ui_story_5004_50040301_28_dialog_content = "Tal vez el propietario se esté aprovechando del estado Celestita de PlayerName para fines de promoción.",
  ui_story_5004_50040301_29_dialog_content = "Hmm, eso es más probable.",
  ui_story_5004_50040301_X29_dialog_content = "¡Eres tú!",
  ui_story_5004_50040301_30_dialog_content = "Eres el forajido de Rediesel Wrench que escapó de la cárcel...",
  ui_story_5004_50040301_31_dialog_content = "¡Espera! ¡Estamos en un viaje por Beryl, no deteniendo criminales!",
  ui_story_5004_50040301_32_dialog_content = "Y no estamos en Lumopolis, ¡no hay necesidad de alboroto!",
  ui_story_5004_50040301_33_dialog_content = "Está bien.",
  ui_story_5004_50040301_34_dialog_content = "Pero si te atreves a hacer algo perjudicial para Lumopolis mientras tanto,",
  ui_story_5004_50040301_35_dialog_content = "Te arrestaré y te llevaré a juicio.",
  ui_story_5004_50040301_36_dialog_content = "Y, ¿por qué estás aquí, Brock? También pareces cercano al dueño.",
  ui_story_5004_50040301_37_dialog_content = "Acerca de eso... Estoy aquí para ayudar a un viejo amigo, el compañero mecánico que mencioné.",
  ui_story_5004_50040301_38_dialog_content = "Cómo te explico... Me cuidó a mí y a mi auto muchas veces. ¡Es la forma Rediesel Wrench de pagar deudas!",
  ui_story_5004_50040301_39_dialog_content = "Si vas al Tir' Hotel, probablemente lo encontrarás allí.",
  ui_story_5004_50040301_40_dialog_content = "Se destaca como un pulgar dolorido, en todos los sentidos.",
  ui_story_5004_50040301_41_dialog_content = "Oh, otra cosa.",
  ui_story_5004_50040301_42_dialog_content = "Soroz encontró una interferencia que se acercaba. ¿Sabes por qué?",
  ui_story_5004_50040301_43_dialog_content = "Nop. Nunca había pilotado un Colossus.",
  ui_story_5004_50040301_44_dialog_content = "Actúas como si todos tuvieran uno de esos.",
  ui_story_5004_50040301_45_dialog_content = "Pero los Colossi son una combinación de criatura y máquina, ¿no es así?",
  ui_story_5004_50040301_46_dialog_content = "Entonces, tal vez Soroz se resfrió o algo así.",
  ui_story_5004_50040301_47_dialog_content = "<size=30>PlayerName, ¿es aquí donde me río de su broma?</size>",
  ui_story_5004_50040301_48_dialog_content = "<size=30>No estoy seguro. No sé si está bromeando o en serio.</size>",
  ui_story_5004_50040301_49_dialog_content = "Deja de susurrar delante de mí.",
  ui_story_5004_50040301_50_dialog_content = "Me llevo mi auto. Sigue esta carretera y llegarás al hotel.",
  ui_story_5004_50040301_51_dialog_content = "(La vista de las olas azules rompiendo en la playa dorada es muy bonita.)",
  ui_story_5004_50040301_52_dialog_content = "(Esos árboles verdes y frondosos cuyo nombre no sé se mecen con la brisa del mar.)",
  ui_story_5004_50040301_53_dialog_content = "(Hay gente jugando en la arena.)",
  ui_story_5004_50040301_54_dialog_content = "(Estoy perdido en el paisaje, y todo aquí bajo el sol, todos son tan vibrantes.)",
  ui_story_5004_50040301_55_dialog_content = "...",
  ui_story_5004_50040301_56_dialog_content = "Este lugar ... es mucho mejor de lo que imaginé.",
  ui_story_5004_50040301_57_dialog_content = "¿Esta es la playa, PlayerName?",
  ui_story_5004_50040301_58_dialog_content = "No sabía que existía un lugar tan relajante dada la crisis actual.",
  ui_story_5004_50040301_59_dialog_content = "El mar es tan hermoso...",
  ui_story_5004_50040301_60_dialog_content = "¡Ese vendedor tiene una larga cola, Beryl! ¡Vamos a ver qué tienen allí!",
  ui_story_5004_50040301_61_dialog_content = "Parece que todos ustedes encuentran <color=#FFB400>Costa Celestial</color> muy agradable, ¿no?",
  ui_story_5004_50040301_62_dialog_content = "¡¿?!",
  ui_story_5004_50040301_63_dialog_content = "¡Bienvenidos, soy representante del resort y la anfitriona del Soberano del Océano, <color=#FFB400>Bonacie</color>!",
  ui_story_5004_50040301_64_dialog_content = "Hola, Bonacie.",
  ui_story_5004_50040301_65_dialog_content = "¡Tú también, Beryl! Ese hombre molesto con lentes no está contigo, ¿no?",
  ui_story_5004_50040301_66_dialog_content = "¿El Sr. Faust? Tiene trabajo que hacer y me dejó con PlayerName.",
  ui_story_5004_50040301_67_dialog_content = "Espléndido. ¿Debe ser PlayerName, supongo?",
  ui_story_5004_50040301_68_dialog_content = "Lindo, un patito suertudo rodeado de hermosas damas, ¿no?",
  ui_story_5004_50040301_69_dialog_content = "Sólo somos amigos.",
  ui_story_5004_50040301_70_dialog_content = "Por supuesto, solo amigos, jeje.",
  ui_story_5004_50040301_71_dialog_content = "Pero mirando a PlayerName, no veo nada peculiar, el tercer ojo o un cuerno para Celestita...",
  ui_story_5004_50040301_72_option_content = "¿Debería disculparme por eso?",
  ui_story_5004_50040301_73_dialog_content = "Tienes un gran sentido del humor, ¿no?",
  ui_story_5004_50040301_74_option_content = "Los Celestitas y los Aurorians son muy parecidos en apariencia.",
  ui_story_5004_50040301_75_dialog_content = "Es gracioso cuando respondes tan en serio.",
  ui_story_5004_50040301_76_dialog_content = "Solo hacía una broma. No te lo tomes en serio.",
  ui_story_5004_50040301_77_dialog_content = "Ustedes son VIP del hotel e invitados de honor del Soberano del Océano.",
  ui_story_5004_50040301_78_dialog_content = "Permítan que yo, Bonacie, les muestre la deslumbrante playa exótica de verano y los servicios apasionados y llamativos...",
  ui_story_5004_50040301_79_dialog_content = "Muchas gracias, pero estamos bien...",
  ui_story_5004_50040301_80_dialog_content = "Pero, tengo una pregunta. ¿Qué es el Soberano del Océano?",
  ui_story_5004_50040301_81_dialog_content = "Es una ceremonia mantenida por los Aurorians que solían vivir en esta playa.",
  ui_story_5004_50040301_82_dialog_content = "\"El mar es el origen de todas las vidas, abrazando y nutriendo a todos en su seno.\"",
  ui_story_5004_50040301_83_dialog_content = "\"La diosa del mar baila con todos los campeones desafiantes aquí.\"",
  ui_story_5004_50040301_84_dialog_content = "Por el Soberano del Océano, los participantes emprenderán las legendarias pruebas.",
  ui_story_5004_50040301_85_dialog_content = "Un vencedor definitivo emergerá después de concursos de <color=#FFB400>fuerza</color>, <color=#FFB400>conocimiento</color>, y <color=#FFB400>coraje</color>.",
  ui_story_5004_50040301_86_dialog_content = "Los dioses otorgarán recompensas al ganador y mostrarán bendiciones a esta hermosa tierra.",
  ui_story_5004_50040301_87_dialog_content = "El ganador también recibirá el título de <color=#FFB400>Guerrero de la playa</color>,",
  ui_story_5004_50040301_88_dialog_content = "¡y un gran premio misterioso!",
  ui_story_5004_50040301_89_dialog_content = "Disfruta del sol y la diversión al competir con chicas en los concursos.",
  ui_story_5004_50040301_90_dialog_content = "No lo rechazarás, PlayerName, ¿verdad?",
  ui_story_5004_50040301_91_dialog_content = "Guerrero... de la playa...",
  ui_story_5004_50040301_92_dialog_content = "Todavía tengo que hablarlo con todos.",
  ui_story_5004_50040301_93_dialog_content = "Está bien. Déjame llevar a todos al hotel y registrarlos.",
  ui_story_5004_50040301_94_dialog_content = "El festival comienza pasado mañana. Diviértete y relájate como quieras, ¿no?",
  ui_story_5004_50040301_95_dialog_content = "¡Esto es muy lujoso!",
  ui_story_5004_50040301_96_dialog_content = "Un estilo de construcción diferente al de Lumopolis e Illumina.",
  ui_story_5004_50040301_97_dialog_content = "Probablemente sea de una antigua civilización.",
  ui_story_5004_50040301_98_dialog_content = "Aquí está el lobby. ¡Te entregaré al administrador del lobby, <color=#FFB400>Fleur</color>!",
  ui_story_5004_50040301_99_dialog_content = "Mm, ¿Fleur? Puedes moverte un poco más rápido, ¿no?",
  ui_story_5004_50040301_100_dialog_content = "Tengo otros asuntos que atender, pero volveré enseguida.",
  ui_story_5004_50040301_101_dialog_content = "¿Fleur?",
  ui_story_5004_50040301_102_dialog_content = "¡Lo siento!",
  ui_story_5004_50040301_103_dialog_content = "¡Estaré ahí en un segundo!",
  ui_story_5004_50040301_104_dialog_content = "¡Fleur!",
  ui_story_5004_50040301_105_dialog_content = "¡Sr. Fleur!",
  ui_story_5004_50040301_106_dialog_content = "¿Estás libre esta noche, Sr. Fleur?",
  ui_story_5004_50040301_107_dialog_content = "¡Llévame al gimnasio, Fleury, y te mostraré mis abdominales!",
  ui_story_5004_50040301_108_dialog_content = "Recién horneé esto. Ábrelo y pruébalo...",
  ui_story_5004_50040301_109_dialog_content = "¿Qué está pasando? Una multitud extraña, incluido ese tipo Fleur.",
  ui_story_5004_50040301_110_dialog_content = "Me da una extraña vibra ese tipo.",
  ui_story_5004_50040301_111_dialog_content = "Parece que Fleur es incluso más popular que tú, PlayerName.",
  ui_story_5004_50040301_112_dialog_content = "Deja de burlarte de mi...",
  ui_story_5004_50040301_113_dialog_content = "Perdóname. Soy Fleur. Deben ser el grupo del Colossus.",
  ui_story_5004_50040301_114_dialog_content = "Y PlayerName, Brock te mencionó bastante a menudo.",
  ui_story_5004_50040301_115_dialog_content = "¿Conoces a Brock?",
  ui_story_5004_50040301_116_dialog_content = "Si. De hecho, soy mecánico de Rediesel Wrench y lo conozco desde hace mucho tiempo.",
  ui_story_5004_50040301_117_dialog_content = "¡Eres el mecánico del que habló Brock! (Y muy llamativo también.)",
  ui_story_5004_50040301_118_dialog_content = "Sí, le pedí ayuda.",
  ui_story_5004_50040301_119_dialog_content = "¡Recuerdo que Fleur es una leyenda en la Academia Mecánica de Illumina!",
  ui_story_5004_50040301_120_dialog_content = "Escuché a estudiantes de último año en Illumina hablar de ti.",
  ui_story_5004_50040301_121_dialog_content = "Dijeron que eres tan bueno con las máquinas como eres amable, <size=40>aunque hay algunas </size><size=35>historias muy raras,</size> <size=30><color=#FFB400>no tan buenas,</color> también...</size>",
  ui_story_5004_50040301_122_dialog_content = "Sí, por eso salió disparado hacia Rediesel Wrench.",
  ui_story_5004_50040301_123_dialog_content = "Y ayudó a Sinsa a curar a Lepidoz. Muy impresionante.",
  ui_story_5004_50040301_124_dialog_content = "¿No tuviste tiempo libre de Sinsa para unas vacaciones de verano?",
  ui_story_5004_50040301_125_dialog_content = "Y aquí estás, un administrador de lobby... pero no pareces realmente combinar con el cargo.",
  ui_story_5004_50040301_126_dialog_content = "¿No deberías al menos llevar una corbata como esos nobles lujuriosos?",
  ui_story_5004_50040301_127_dialog_content = "...",
  ui_story_5004_50040301_128_dialog_content = "(¡Oye, tenemos una noble de Lumo con nosotros!)",
  ui_story_5004_50040301_129_dialog_content = "Estoy aquí por solicitud de Bonacie, así como por otras razones.",
  ui_story_5004_50040301_130_dialog_content = "Creo que te han tomado a lo grande, pero eso te queda bien.",
  ui_story_5004_50040301_131_dialog_content = "Mi trabajo como guía y chofer está hecho. Es hora de que compruebe los sistemas estéreo del bar.",
  ui_story_5004_50040301_132_dialog_content = "No me busques a menos que suceda algo.",
  ui_story_5004_50040301_133_dialog_content = "Tómalo con calma, Regina.",
  ui_story_5004_50040301_134_dialog_content = "Todos, por aquí. Los registraré.",
  ui_story_5004_50040301_135_dialog_content = "¿Cómo les gustaría organizar sus habitaciones?",
  ui_story_5004_50040301_136_dialog_content = "Yo quiero...",
  ui_story_5004_50040301_137_dialog_content = "¡Yo, yo! ¡Quiero compartir habitación con Beryl!",
  ui_story_5004_50040301_138_dialog_content = "Soy su médica de cabecera, ¡así que no puedo perderla de mi vista!",
  ui_story_5004_50040301_139_dialog_content = "Está bien, ¿verdad? ¿Verdad?",
  ui_story_5004_50040301_140_dialog_content = "O-okey. No tengo problema con eso.",
  ui_story_5004_50040301_141_dialog_content = "Vice y yo tendremos una habitación separada.",
  ui_story_5004_50040301_142_option_content = "Significa que...",
  ui_story_5004_50040301_143_dialog_content = "Dormirás solo, por supuesto. Estoy seguro de que no le temes a la oscuridad, después de más de una década en el Soroz.",
  ui_story_5004_50040301_144_dialog_content = "¡Por supuesto!",
  ui_story_5004_50040301_145_option_content = "¿Y Regina?",
  ui_story_5004_50040301_146_dialog_content = "¿Regina? Estará ocupada con sistemas estéreo durante días.",
  ui_story_5004_50040301_147_dialog_content = "Puedo registrarla y darle la llave más tarde.",
  ui_story_5004_50040301_148_dialog_content = "Cinco habitaciones en total.",
  ui_story_5004_50040301_149_dialog_content = "Uh, consejos...",
  ui_story_5004_50040301_150_dialog_content = "Estos invitados son VIP, no podemos pedirles propinas. Recuerda eso, ¿ok?",
  ui_story_5004_50040301_151_dialog_content = "Ah, oh.",
  ui_story_5004_50040301_152_dialog_content = "Aquí están las llaves de tu habitación.",
  ui_story_5004_50040301_153_dialog_content = "Ese asistente, se ve un poco raro...",
  ui_story_5004_50040301_154_dialog_content = "Jaja, es un poco inapropiado decir eso, PlayerName.",
  ui_story_5004_50040301_155_dialog_content = "También tengo cuernos en la cabeza.",
  ui_story_5004_50040301_156_dialog_content = "Espero que todos puedan llevarse bien.",
  ui_story_5004_50040301_157_dialog_content = "(Un tipo de persona realmente buena...)",
  ui_story_5004_50040301_158_dialog_content = "Siendo honesto, pueden ser muy extraños...",
  ui_story_5004_50040301_159_dialog_content = "El propietario los fijó por sus demandas salariales bajas y horas extras gratuitas.",
  ui_story_5004_50040301_160_dialog_content = "Así que muchos fueron contratados con esa base.",
  ui_story_5004_50040301_161_dialog_content = "¿Creo que Brock dijo que el propietario no es un tipo de negocios?",
  ui_story_5004_50040301_162_dialog_content = "Aparentemente es un líder de una pandilla de Umbraton,",
  ui_story_5004_50040301_163_dialog_content = "que tiene perspicacia para los negocios y ama el dinero. Dicen que el propietario está involucrado en negocios turbios mientras dirige el hotel.",
  ui_story_5004_50040301_164_dialog_content = "No puedo soportarlo por completo, pero tengo un trato con Bonacie, y estoy atrapado aquí al menos por el momento.",
  ui_story_5004_50040301_165_dialog_content = "Oh, un recordatorio. Hay algunas trampas para turistas absurdas en el hotel y en la playa. Resultan costosas.",
  ui_story_5004_50040301_166_dialog_content = "¿Los vendedores estafadores? Sí, tendremos cuidado.",
  ui_story_5004_50040301_167_dialog_content = "Les mostraré sus habitaciones. Por aquí por favor.",
  ui_story_5004_50040401_168_dialog_content = "Adelante, PlayerName.",
  ui_story_5004_50040401_169_dialog_content = "¿Es mi habitación?",
  ui_story_5004_50040401_170_dialog_content = "Espero que sea de tu agrado.",
  ui_story_5004_50040401_171_dialog_content = "Me gustaría hablar contigo, propietario de un Colossus, sobre las máquinas.",
  ui_story_5004_50040401_172_dialog_content = "Debes estar agotado, así que la próxima vez, si lo deseas.",
  ui_story_5004_50040401_173_dialog_content = "Cualquier pregunta o problema, no duden en llamar a la recepción con el <color=#FFB400>comunicador</color> que se encuentra allí.",
  ui_story_5004_50040401_174_dialog_content = "Está bien. Gracias.",
  ui_story_5004_50040401_175_dialog_content = "...",
  ui_story_5004_50040401_176_dialog_content = "La habitación está ordenada y parece una cama suave. Puedo ver la playa por la noche desde la ventana.",
  ui_story_5004_50040401_177_dialog_content = "Es diferente de la ordenada Illumina o de la sofisticada Lumopolis, pero es animado y enérgico.",
  ui_story_5004_50040401_178_dialog_content = "Phew...",
  ui_story_5004_50040401_179_dialog_content = "La cama rebota.",
  ui_story_5004_50040401_180_dialog_content = "Una invitación inesperada, estoy en la playa, acostado en una cama tan cómoda, pero todo esto aún no se ha asimilado...",
  ui_story_5004_50040401_181_dialog_content = "Luego está el Soberano del Océano... Es extraño. ¿Debería ser parte de ella?",
  ui_story_5004_50040401_182_dialog_content = "¿Me pregunto qué hacen todos en este momento?",
  ui_story_5004_50040401_183_dialog_content = "<color=#e8d9bb>¡Bip, bip, bip!</color>",
  ui_story_5004_50040401_184_dialog_content = "¿Qué es eso? ¿Es el comunicador que mencionó Fleur?",
  ui_story_5004_50040401_185_dialog_content = "¿Hola?",
  ui_story_5004_50040401_186_dialog_content = "¡Hola! ¡Hey!",
  ui_story_5004_50040401_187_dialog_content = "Tu folleto dice: \"Descubre todo tu potencial para ser más fuerte en siete días.\" ¡¿Es cierto?!",
  ui_story_5004_50040401_188_dialog_content = "¿Brock? ¿De qué estás divagando?",
  ui_story_5004_50040401_189_dialog_content = "¿PlayerName? Debo tener el número equivocado.",
  ui_story_5004_50040401_190_dialog_content = "¡Te atraparé la próxima vez!",
  ui_story_5004_50040401_191_dialog_content = "<color=#e8d9bb>Bip... bip...</color>",
  ui_story_5004_50040401_192_dialog_content = "Colgó. Ojalá no se deje engañar por alguna estafa.",
  ui_story_5004_50040401_193_dialog_content = "Debería poder hacer llamadas de habitación a habitación marcando el número de habitación, ¿verdad?",
  ui_story_5004_50040401_194_dialog_content = "Intentemos...",
  ui_story_5004_50040401_195_option_content = "Llama a Vice",
  ui_story_5004_50040401_196_dialog_content = "¿Ese es PlayerName?",
  ui_story_5004_50040401_197_dialog_content = "¡No sabía que el hotel tendría comunicadores tan convenientes!",
  ui_story_5004_50040401_198_dialog_content = "No interrumpí nada, ¿verdad? Solo tengo curiosidad por saber qué haces.",
  ui_story_5004_50040401_199_dialog_content = "No, nada en particular, solo acostada en la cama... ¡Es muy cómoda!",
  ui_story_5004_50040401_200_dialog_content = "¿Crees que deberíamos participar en el Soberano del Océano?",
  ui_story_5004_50040401_201_dialog_content = "¡Seguro! Escuchaste lo que dijo Fleur, ¿no?",
  ui_story_5004_50040401_202_dialog_content = "Nos quedamos en el resort gratis, pero tenemos que pagar por todo lo demás: comida, trajes de baño, todas las actividades.",
  ui_story_5004_50040401_203_dialog_content = "Si solo gastamos el dinero sin ganar nada, entonces...",
  ui_story_5004_50040401_204_dialog_content = "Yo, no tengo mucha confianza en el atletismo...",
  ui_story_5004_50040401_205_dialog_content = "No te preocupes, nos tienes a todos. Trabajaremos en equipo.",
  ui_story_5004_50040401_206_dialog_content = "¡No lo olvides, nadie tiene ventaja sobre ti cuando se trata de mandar, PlayerName!",
  ui_story_5004_50040401_207_dialog_content = "Probablemente tengas razón en eso...",
  ui_story_5004_50040401_208_dialog_content = "Pero, ¿y si el premio no es Nightium?",
  ui_story_5004_50040401_209_dialog_content = "Podemos dárselo a Sheol para que lo venda.",
  ui_story_5004_50040401_210_dialog_content = "No te preocupes, PlayerName. ¡Descansa, seguro que ganaremos!",
  ui_story_5004_50040401_211_dialog_content = "Si así es como te sientes, ¡hagámoslo!",
  ui_story_5004_50040401_212_option_content = "Llama a Carleen",
  ui_story_5004_50040401_213_dialog_content = "¿PlayerName? ¿Algo malo?",
  ui_story_5004_50040401_214_dialog_content = "Perdóname. Tengo curiosidad por lo que haces, Carleen.",
  ui_story_5004_50040401_215_dialog_content = "Preparándome para ir a la cama, según mi horario diario.",
  ui_story_5004_50040401_216_dialog_content = "Siempre eres tan disciplinado.",
  ui_story_5004_50040401_217_dialog_content = "Oh, ¿qué sientes en el Soberano del Océano?",
  ui_story_5004_50040401_218_dialog_content = "Sin duda ganaremos.",
  ui_story_5004_50040401_219_dialog_content = "¿Por qué dices eso cuando aún no hemos decidido entrar?",
  ui_story_5004_50040401_220_dialog_content = "¿Por qué no? Estamos invitados por una razón. Es nuestro destino responder al desafío.",
  ui_story_5004_50040401_221_dialog_content = "Un verdadero guerrero nunca se echa atrás.",
  ui_story_5004_50040401_222_dialog_content = "Sé que puedes estar confundido o ansioso, PlayerName.",
  ui_story_5004_50040401_223_dialog_content = "Pero debes creer que puedes superar obstáculos y forjar tu propio camino.",
  ui_story_5004_50040401_224_dialog_content = "Eres especial para todos los aurorians, incluyéndome.",
  ui_story_5004_50040401_225_dialog_content = "¿Me estás mentalizando?",
  ui_story_5004_50040401_226_dialog_content = "Si, te estoy dando una charla de ánimo.",
  ui_story_5004_50040401_227_dialog_content = "Por eso eres el Capitán de los Guardianes de Lumopolis. Estoy inspirado.",
  ui_story_5004_50040401_228_dialog_content = "Bien. Ahora descansa.",
  ui_story_5004_50040401_229_dialog_content = "Está bien. ¡Dormiré ya que se decidió que ingresaremos al Soberano del Océano!",
  ui_story_5004_50040401_230_dialog_content = "Hablando de acostarse, ¿hay cama individual en todas las habitaciones?",
  ui_story_5004_50040401_230X1_dialog_content = "<color=#e8d9bb>¡Wham!</color>",
  ui_story_5004_50040401_230X2_dialog_content = "¡Ay!",
  ui_story_5004_50040401_230X3_dialog_content = "¡Lo siento! ¿Estás bien?",
  ui_story_5004_50040401_230X4_dialog_content = "¿Por qué te quedaste en la puerta con los platos en la mano? ¡Eso es solo buscar problemas!",
  ui_story_5004_50040401_230X5_dialog_content = "Huff, huff... Te fuiste muy rápido, Raphaela...",
  ui_story_5004_50040401_230X6_dialog_content = "Estaba entregando el postre que ordenó el invitado en esta sala.",
  ui_story_5004_50040401_230X7_dialog_content = "Si no hay nada más, tengo que irme. Está ocupado en la cocina.",
  ui_story_5004_50040401_230X8_dialog_content = "¿Por qué hace ruido afuera?",
  ui_story_5004_50040401_230X9_dialog_content = "<color=#e8d9bb>¡Toc, toc!</color>",
  ui_story_5004_50040401_231_dialog_content = "¿Qué pasa con Beryl y...",
  ui_story_5004_50040401_232_dialog_content = "¡Estamos aquí para pasar el rato, PlayerName! ¡Oye, estás comiendo a nuestras espaldas!",
  ui_story_5004_50040401_233_dialog_content = "¿Raphaela? No, no voy a comer nada...",
  ui_story_5004_50040401_234_dialog_content = "B-Buenas noches ...",
  ui_story_5004_50040401_235_dialog_content = "¿También estás aquí, Beryl?",
  ui_story_5004_50040401_236_dialog_content = "¿No tienes algo que decirle a PlayerName, Beryl?",
  ui_story_5004_50040401_237_dialog_content = "Bien...",
  ui_story_5004_50040401_238_dialog_content = "¿Estás tímida? ¿Lo digo por ti?",
  ui_story_5004_50040401_239_dialog_content = "Si...",
  ui_story_5004_50040401_240_dialog_content = "Está bien.",
  ui_story_5004_50040401_241_dialog_content = "Entonces, Beryl quiere estar en el Soberano del Océano.",
  ui_story_5004_50040401_242_dialog_content = "Seguro.",
  ui_story_5004_50040401_243_dialog_content = "Ella no puede estar en el Soberano del Océano.",
  ui_story_5004_50040401_244_dialog_content = "¿Qué?",
  ui_story_5004_50040401_245_dialog_content = "¿No puedes usar esa cabeza tuya, PlayerName?",
  ui_story_5004_50040401_246_dialog_content = "No culpes a PlayerName, Raphaela. No organicé bien mis pensamientos.",
  ui_story_5004_50040401_247_dialog_content = "PlayerName, ¿recuerdas las recompensas que mencionó Bonacie?",
  ui_story_5004_50040401_248_dialog_content = "Oh, ¿Beryl necesita dinero? En realidad yo...",
  ui_story_5004_50040401_249_dialog_content = "¡No, es el título de Guerrero de la Playa!",
  ui_story_5004_50040401_250_dialog_content = "...",
  ui_story_5004_50040401_251_dialog_content = "¿Qué expresión es esa? ¿Tienes problemas con el sueño de una joven inocente?",
  ui_story_5004_50040401_252_dialog_content = "¡No me atrevería! Me aparté por un segundo.",
  ui_story_5004_50040401_253_dialog_content = "¿Hablas en serio, Beryl?",
  ui_story_5004_50040401_254_dialog_content = "¡Sí...!",
  ui_story_5004_50040401_255_dialog_content = "La participación no es problema. Todos piensan lo mismo también.",
  ui_story_5004_50040401_256_dialog_content = "¿En serio?",
  ui_story_5004_50040401_257_dialog_content = "¡Eso es genial!",
  ui_story_5004_50040401_258_dialog_content = "¿Qué quieres decir con que no puedes estar en él?",
  ui_story_5004_50040401_259_dialog_content = "Bueno, Beryl...",
  ui_story_5004_50040401_260_dialog_content = "Yo misma le diré a PlayerName. Gracias, Raphaela.",
  ui_story_5004_50040401_261_dialog_content = "Uf...",
  ui_story_5004_50040401_262_dialog_content = "Viste lo que puedo hacer hoy...",
  ui_story_5004_50040401_263_dialog_content = "Bien, fue increíblemente poderoso.",
  ui_story_5004_50040401_264_dialog_content = "Pero también puedo perder el control fácilmente... Es peligroso...",
  ui_story_5004_50040401_265_dialog_content = "Cuanto más poder libero, más me afecta física y emocionalmente...",
  ui_story_5004_50040401_266_dialog_content = "Gasté mucho para sacar todos esos Eclipsites, no puedo involucrarme en actividades rigurosas durante los próximos días.",
  ui_story_5004_50040401_267_dialog_content = "Ya veo. Lo hiciste para ayudarnos, ¡así que todos te ayudaremos!",
  ui_story_5004_50040401_268_dialog_content = "Hablaré con los demás y te pondré en el equipo como reserva.",
  ui_story_5004_50040401_269_dialog_content = "Puedes decidir si estás en forma para participar en un concurso.",
  ui_story_5004_50040401_270_dialog_content = "¿Te parece bien?",
  ui_story_5004_50040401_271_dialog_content = "¡Sí!",
  ui_story_5004_50040401_272_dialog_content = "Sin embargo, mencionaste que tiene un impacto emocional. Me gustaría saber los detalles.",
  ui_story_5004_50040401_273_dialog_content = "Me pongo muy triste y deprimida, lo que a su vez aumenta mi poder... y me hace aún más fácil perder el control.",
  ui_story_5004_50040401_274_dialog_content = "¡Ese es un círculo vicioso!",
  ui_story_5004_50040401_275_dialog_content = "Sí.",
  ui_story_5004_50040401_276_dialog_content = "Espero que algún día puedas deshacerte del dolor y la depresión y encontrar el valor para controlar ese poder.",
  ui_story_5004_50040401_277_dialog_content = "Espero mucho que suceda eso.",
  ui_story_5004_50040501_1_dialog_content = "...",
  ui_story_5004_50040501_2_dialog_content = ".",
  ui_story_5004_50040501_3_dialog_content = "No, todavía no estoy acostumbrado a dormir lejos del Colossus.",
  ui_story_5004_50040501_4_option_content = "Intenta salir de la cama",
  ui_story_5004_50040501_5_dialog_content = "<color=#e8d9bb>¡Toc, toc!</color>",
  ui_story_5004_50040501_6_dialog_content = "¿Estás despierto, PlayerName?",
  ui_story_5004_50040501_7_option_content = "Intenta salir de la cama de nuevo",
  ui_story_5004_50040501_8_dialog_content = "Sí. Espera mientras me levanto.",
  ui_story_5004_50040501_9_dialog_content = "<color=#e8d9bb>Clic.</color>",
  ui_story_5004_50040501_10_dialog_content = "Buenos días, PlayerName. Hora de levantarse.",
  ui_story_5004_50040501_11_dialog_content = "¡Carleen y los otros están esperando en el comedor!",
  ui_story_5004_50040501_12_dialog_content = "Buenos días, PlayerName. No parece que hayas tenido una buena noche de sueño.",
  ui_story_5004_50040501_13_dialog_content = "Buenos días. No estoy acostumbrado a dormir lejos del Colossus...",
  ui_story_5004_50040501_14_dialog_content = "Pero, disfruto de experiencias especiales como esta.",
  ui_story_5004_50040501_15_dialog_content = "He pasado por muchas cosas que nunca hubiera esperado desde que conocí a Vice y Carleen.",
  ui_story_5004_50040501_16_dialog_content = "Suenas maduro cuando hablas de esa manera, PlayerName.",
  ui_story_5004_50040501_17_dialog_content = "¿Hay magia en la brisa del mar?",
  ui_story_5004_50040501_18_dialog_content = "Jaja... O puede ser simplemente por no dormir bien anoche.",
  ui_story_5004_50040501_19_dialog_content = "¿Y ustedes dos, Raphaela y Beryl?",
  ui_story_5004_50040501_20_option_content = "¿Durmieron bien?",
  ui_story_5004_50040501_21_dialog_content = "Muy bien, aunque estaba un poco abarrotado en la cama.",
  ui_story_5004_50040501_22_dialog_content = "(Era una cama individual).",
  ui_story_5004_50040501_23_dialog_content = "¡Dato curioso sobre Beryl, PlayerName! Le gusta agarrarse a algo cuando duerme, ¿no es adorable?",
  ui_story_5004_50040501_24_dialog_content = "Es normal sostener una almohada cuando duermes... ¿verdad?",
  ui_story_5004_50040501_25_option_content = "¿Hay una cama doble en su cuarto?",
  ui_story_5004_50040501_26_dialog_content = "No. Es muy pequeña...",
  ui_story_5004_50040501_27_dialog_content = "Porque aparte, hay una almohada gigante.",
  ui_story_5004_50040501_28_dialog_content = "Ese es mi...",
  ui_story_5004_50040501_29_dialog_content = "No esperaba que Beryl fuera del tipo que sostiene algo cuando duerme.",
  ui_story_5004_50040501_30_dialog_content = "¡Es normal sostener una almohada al dormir!",
  ui_story_5004_50040501_31_dialog_content = "Sí, una almohada para la primera mitad de la noche...",
  ui_story_5004_50040501_32_dialog_content = "¿Podemos dejar de hablar de eso?",
  ui_story_5004_50040501_33_dialog_content = "¡Buenos días a todos! ¿Tuvieron un buen descanso?",
  ui_story_5004_50040501_34_dialog_content = "¡Hola, Fleur!",
  ui_story_5004_50040501_35_dialog_content = "Estuvo bien. Excelentes comodidades y la cama es muy cómoda.",
  ui_story_5004_50040501_36_dialog_content = "Pero todavía me estoy acostumbrando.",
  ui_story_5004_50040501_37_dialog_content = "Jajaja, he escuchado mucho eso de los clientes, pero estoy seguro de que te acostumbrarás.",
  ui_story_5004_50040501_38_dialog_content = "La gente se siente más segura en casa hoy en día, especialmente con todos los Eclipsites deambulando.",
  ui_story_5004_50040501_39_dialog_content = "Tienes razón, Fleur. Carleen mencionó que hay una <color=#FFB400>tienda de trajes de baño</color> aquí.",
  ui_story_5004_50040501_40_dialog_content = "¿Sabes cómo llegar, Fleur?",
  ui_story_5004_50040501_41_dialog_content = "Por supuesto, está en el <color=#FFB400>lado noreste del comedor</color>.",
  ui_story_5004_50040501_42_dialog_content = "Genial, ¡iremos después del desayuno!",
  ui_story_5004_50040501_43_dialog_content = "¡Sí!",
  ui_story_5004_50040601_44_dialog_content = "¿Por lo general, toma tanto tiempo elegir algo?",
  ui_story_5004_50040601_45_dialog_content = "Me dijeron que esperara en la <color=#FFB400>playa</color>, pero eso fue hace más de una hora.",
  ui_story_5004_50040601_46_dialog_content = "La luz del sol es intensa, pero no está mal para tomar el sol.",
  ui_story_5004_50040601_47_dialog_content = "Solo Vice y los otros como mis viejos amigos... Sin más Eclipsites o sus malvados complots...",
  ui_story_5004_50040601_48_dialog_content = "Disfrutar del tiempo libre y vaguear... ¡qué relajante!",
  ui_story_5004_50040601_49_dialog_content = "...",
  ui_story_5004_50040601_50_dialog_content = "Incluso la arena es cálida y reconfortante, tal vez debería dibujar algo.",
  ui_story_5004_50040601_51_dialog_content = "¿Qué es lo que estás dibujando, PlayerName? ¿Un pulpo?",
  ui_story_5004_50040601_52_dialog_content = "¿Qué? ¡No! ¡Es un gato! ¡Gato!",
  ui_story_5004_50040601_53_dialog_content = "¿Entonces los tentáculos torcidos son bigotes?",
  ui_story_5004_50040601_54_dialog_content = "¡Te ayudaré a dibujar mejores bigotes!",
  ui_story_5004_50040601_55_dialog_content = "¡No uses tus pies, Vice! ¡Ok, ahora los bigotes son más gruesos que mis brazos!",
  ui_story_5004_50040601_56_dialog_content = "...",
  ui_story_5004_50040601_57_dialog_content = "¿Qué pasa?",
  ui_story_5004_50040601_58_dialog_content = "Emm... nada mal.",
  ui_story_5004_50040601_59_dialog_content = "¿Nada mal qué?",
  ui_story_5004_50040601_60_dialog_content = "Estás actuando raro, PlayerName.",
  ui_story_5004_50040601_61_dialog_content = "No importa, solo disfrutaré del paisaje.",
  ui_story_5004_50040601_62_dialog_content = "El verano no es verano hasta que te pones un bañador en la playa.",
  ui_story_5004_50040601_63_dialog_content = "Tu traje de baño no es apto para ser una armadura de batalla.",
  ui_story_5004_50040601_64_dialog_content = "¡PlayerName! ¡Te mostraré cómo es un caballero que no teme a las grandes olas!",
  ui_story_5004_50040601_65_dialog_content = "(A pesar de la diferencia de opiniones, Carleen también parece emocionada...)",
  ui_story_5004_50040601_66_dialog_content = "(Tanto es así que me dejó mirarla en traje de baño.)",
  ui_story_5004_50040601_67_dialog_content = "¿Qué opinas, PlayerName?",
  ui_story_5004_50040601_68_dialog_content = "¿Qué quieres decir con qué opino?",
  ui_story_5004_50040601_69_dialog_content = "Los trajes de baño, claro. ¿Quién crees que conquistará la playa?",
  ui_story_5004_50040601_70_option_content = "Vice es linda y vivaz en su traje de baño.",
  ui_story_5004_50040601_72_dialog_content = "¿Eso es lo que te gusta, PlayerName?",
  ui_story_5004_50040601_73_dialog_content = "Vice era conocido por ser enérgico en la escuela.",
  ui_story_5004_50040601_74_dialog_content = "Desde tirar el doble para alcanzar un objetivo de entrenamiento hasta estudiar toda la noche para una prueba, de todo.",
  ui_story_5004_50040601_75_dialog_content = "¡Seguro! ¡Nadie es rival para mí en eso!",
  ui_story_5004_50040601_76_option_content = "El bañador de Carleen es sofisticado y elegante.",
  ui_story_5004_50040601_78_dialog_content = "¡También lo creo!",
  ui_story_5004_50040601_79_dialog_content = "No se puede exudar la noble gracia que ella hace sin someterse al estricto entrenamiento de etiqueta que Carleen hizo.",
  ui_story_5004_50040601_80_dialog_content = "Illumina desarrolla la disciplina militar. Es diferente a Lumopolis.",
  ui_story_5004_50040601_81_dialog_content = "Es cierto, Vice me pisó los talones en nuestras clases de ciencias...",
  ui_story_5004_50040601_82_dialog_content = "Jeje, solo tengo más talento en esos campos.",
  ui_story_5004_50040601_83_dialog_content = "Y terrible en todo relacionado con el arte.",
  ui_story_5004_50040601_84_dialog_content = "Eso es porque Lumopolis no ofrecía clases de dibujo mecánico.",
  ui_story_5004_50040601_85_dialog_content = "¿Le llamas arte? ¡No lo ves en ningún otro lugar que no sea Illumina!",
  ui_story_5004_50040601_86_dialog_content = "¡Podría tener talento en la música! ¡Ayudé a PlayerName a iniciar el Colossus antes!",
  ui_story_5004_50040601_87_dialog_content = "Si lo hiciste. Y te agradezco nuevamente en nombre de Soroz, teniente Vice.",
  ui_story_5004_50040601_88_dialog_content = "Gracias a ti, todos tuvieron la oportunidad de divertirse junto al mar.",
  ui_story_5004_50040601_89_dialog_content = "¡Lamento hacerlos esperar!",
  ui_story_5004_50040601_90_dialog_content = "¡Raphaela! No estás en traje de baño.",
  ui_story_5004_50040601_91_dialog_content = "Estoy en servicio médico. No es ético para mí ponerme un traje de baño y relacionarme con un paciente bajo mi cuidado.",
  ui_story_5004_50040601_92_dialog_content = "Ya veo. ¿Dónde está Beryl?",
  ui_story_5004_50040601_93_dialog_content = "¿Beryl?",
  ui_story_5004_50040601_94_dialog_content = "¡Ven, Beryl!",
  ui_story_5004_50040601_95_dialog_content = "No... Esto es incómodo...",
  ui_story_5004_50040601_96_dialog_content = "Nunca antes había usado nada que mostrara tanta piel...",
  ui_story_5004_50040601_97_dialog_content = "¡No seas tímida, te ves muy linda con él!",
  ui_story_5004_50040601_98_dialog_content = "¿No es así, PlayerName?",
  ui_story_5004_50040601_99_dialog_content = "Si. Todo tu temperamento ha cambiado en él, de una buena manera, y te queda bien.",
  ui_story_5004_50040601_100_dialog_content = "Es verdad, ni siquiera yo puedo negar que ahora serías una buena caballera.",
  ui_story_5004_50040601_101_dialog_content = "El ajuste personalizado debe hacerlo más fácil moverse.",
  ui_story_5004_50040601_102_dialog_content = "Estoy de acuerdo. Es mucho más adorable que el atuendo habitual de Beryl.",
  ui_story_5004_50040601_103_dialog_content = "¡Nada con nosotros con ese lindo traje!",
  ui_story_5004_50040601_104_dialog_content = "¡Todos piensan que eres adorable, Beryl!",
  ui_story_5004_50040601_105_dialog_content = "¡Es la forma en que todos están vestidos!",
  ui_story_5004_50040601_106_dialog_content = "Bien...",
  ui_story_5004_50040601_107_dialog_content = "Está bien, supongo.",
  ui_story_5004_50040601_108_dialog_content = "¡Deja de preocuparte tanto, Beryl!",
  ui_story_5004_50040601_108X1_dialog_content = "<color=#e8d9bb>Snap.</color>",
  ui_story_5004_50040601_108X2_dialog_content = "<color=#e8d9bb>Snap, snap.</color>",
  ui_story_5004_50040601_108X3_dialog_content = "¿Es el asistente de ayer?",
  ui_story_5004_50040601_108X4_dialog_content = "¿El que sostiene una cámara? Eso debería ser una cámara, ¡vi algo similar en Lumopolis antes!",
  ui_story_5004_50040601_108X5_dialog_content = "Eso es extraño. ¿Por qué alguien que toma fotografías se escondería?",
  ui_story_5004_50040601_108X6_dialog_content = "¿Probablemente con fines promocionales? ¡Déjame ver si puedo tomar prestada la cámara!",
  ui_story_5004_50040601_108X7_dialog_content = "Oh, las chicas en traje de baño deberían ganarme un bono...",
  ui_story_5004_50040601_108X8_dialog_content = "¡Permiso!",
  ui_story_5004_50040601_108X9_dialog_content = "¡Argh!",
  ui_story_5004_50040601_108X10_dialog_content = "¿Qué...? ¡Lo arrojaste antes de que lo pidiera!",
  ui_story_5004_50040601_108X11_dialog_content = "Supongo que no te importa prestarme esto, ¡gracias!",
  ui_story_5004_50040601_108X12_dialog_content = "Me asustaste...",
  ui_story_5004_50040601_108X13_dialog_content = "Lo necesito de vuelta...",
  ui_story_5004_50040601_108X14_dialog_content = "El asistente parece reacio, Raphaela. Quizás deberías devolver la cámara.",
  ui_story_5004_50040601_108X15_dialog_content = "Beryl es una chica tan dulce. Aquí tienes, no vuelvas a tirarla.",
  ui_story_5004_50040601_108X16_dialog_content = "Gracias...",
  ui_story_5004_50040601_109_dialog_content = "¡Bien, divirtámonos un poco, Beryl!",
  ui_story_5004_50040601_110_dialog_content = "Vamos también, PlayerName.",
  ui_story_5004_50040601_111_dialog_content = "¡Seguro!",
  ui_story_5004_50040701_1_dialog_content = "¿Por qué son tan animados y enérgicos?",
  ui_story_5004_50040701_2_dialog_content = "(Vice está nadando como si tuviera una hélice, esparciendo agua por todas partes.)",
  ui_story_5004_50040701_3_dialog_content = "(Carleen está sacando todo tipo de criaturas marinas del agua con su lanza).",
  ui_story_5004_50040701_4_dialog_content = "(Y tirando a criaturas aun mayores que ella a la costa.)",
  ui_story_5004_50040701_5_dialog_content = "(Incluso Beryl y Raphaela están recogiendo conchas y haciendo castillos de arena.)",
  ui_story_5004_50040701_6_dialog_content = "(Debo admitir que Beryl construyó un castillo de arena impresionante...)",
  ui_story_5004_50040701_7_dialog_content = "(Aparte de las espinas que sobresalen y las agujas, tiene una torre de reloj gigante.)",
  ui_story_5004_50040701_X7_dialog_content = "(Parece que el castillo está gobernado por fuerzas del mal...)",
  ui_story_5004_50040701_8_dialog_content = "Entonces, ¿estoy siendo... débil?",
  ui_story_5004_50040701_9_dialog_content = "Apenas hice ejercicio en el Colossus.",
  ui_story_5004_50040701_10_dialog_content = "Me quedé de pie y di órdenes mientras estaba en combate...",
  ui_story_5004_50040701_11_dialog_content = "Quizás debería correr en la playa para ponerme en forma.",
  ui_story_5004_50040701_12_dialog_content = "Oye, no es el Gran Maestro del Colossus, el Futuro Comandante de Illumina, el Guardián de Lumopolis...",
  ui_story_5004_50040701_13_dialog_content = "¿Y el mejor amigo del próximo jefe de Rediesel Wrench, PlayerName?",
  ui_story_5004_50040701_14_dialog_content = "¿Brock? ¿Qué estás haciendo acá?",
  ui_story_5004_50040701_15_dialog_content = "¿No se supone que debes ayudar a Fleur?",
  ui_story_5004_50040701_16_dialog_content = "Por cierto, no creo que puedas vencer a Sinsa y ser el nuevo jefe.",
  ui_story_5004_50040701_17_dialog_content = "Eres un buen comandante, PlayerName, pero un pobre juez de personalidades.",
  ui_story_5004_50040701_18_dialog_content = "Sinsa está en declive, y yo, ¡soy una estrella en ascenso!",
  ui_story_5004_50040701_X18_dialog_content = "...",
  ui_story_5004_50040701_19_dialog_content = "¡Mucha gente en Rediesel Wrench está de mi lado ahora!",
  ui_story_5004_50040701_20_dialog_content = "¿Mucha gente? ¿Como quién?",
  ui_story_5004_50040701_21_dialog_content = "Hay Fleur...",
  ui_story_5004_50040701_22_dialog_content = "...",
  ui_story_5004_50040701_23_dialog_content = "¿Y?",
  ui_story_5004_50040701_24_dialog_content = "Fleur, Fleur y Fleur. ¡Debería hablar con Regina sobre eso!",
  ui_story_5004_50040701_25_dialog_content = "No creo que a Regina le interese eso.",
  ui_story_5004_50040701_26_dialog_content = "Entonces te hablaré.",
  ui_story_5004_50040701_27_dialog_content = "¿Puedes anunciar que tienes el apoyo de la raza Celestita?",
  ui_story_5004_50040701_28_dialog_content = "¡PlayerName, eres el Celestita más inteligente que conozco!",
  ui_story_5004_50040701_29_dialog_content = "¡Sí, soy el único Celestita que conoces!",
  ui_story_5004_50040701_30_dialog_content = "Shh.",
  ui_story_5004_50040701_31_dialog_content = "¿...?",
  ui_story_5004_50040701_32_dialog_content = "¿Ves esa<color=#FFB400> persona de allí</color>, PlayerName?",
  ui_story_5004_50040701_33_dialog_content = "¿La niña?",
  ui_story_5004_50040701_34_dialog_content = "Sí. Ella está merodeando, hurgando en todo.",
  ui_story_5004_50040701_35_dialog_content = "No, probablemente esté buscando algo que perdió.",
  ui_story_5004_50040701_36_dialog_content = "¿Has visto a alguien levantar una roca tan grande para buscar algo que perdió?",
  ui_story_5004_50040701_37_dialog_content = "Muy bien, vamos a verlo.",
  ui_story_5004_50040701_38_option_content = "Okay...",
  ui_story_5004_50040701_39_dialog_content = "Pero, ¿por qué tienes tanta curiosidad?",
  ui_story_5004_50040701_40_dialog_content = "¿Y si ella es ladrona?",
  ui_story_5004_50040701_41_dialog_content = "¿Cómo? ¿Quién escondería algo debajo de esa roca?",
  ui_story_5004_50040701_42_dialog_content = "No recuerdo ese sentido de justicia tuyo en Rediesel Wrench.",
  ui_story_5004_50040701_43_dialog_content = "¡Es diferente ahora, trabajo para Fleur! ¡Ahora soy el <color=#FFB400>Jefe de Seguridad de la Costa Celestial</color>!",
  ui_story_5004_50040701_44_dialog_content = "(¿Qué genio contrató un Rediesel Wrench para la seguridad?)",
  ui_story_5004_50040701_45_option_content = "Creo que no debemos entrometernos en los asuntos de otra persona.",
  ui_story_5004_50040701_46_dialog_content = "No recuerdo ese sentido de justicia tuyo en Rediesel Wrench.",
  ui_story_5004_50040701_47_dialog_content = "¡Es diferente ahora, trabajo para Fleur! ¡Ahora soy el <color=#FFB400>Jefe de Seguridad de la Costa Celestial</color>!",
  ui_story_5004_50040701_48_dialog_content = "(¿Qué genio contrató un Rediesel Wrench para la seguridad?)",
  ui_story_5004_50040701_49_dialog_content = "Cállate y sígueme.",
  ui_story_5004_50040701_50_dialog_content = "¡Oye tú, persona sospechosa!",
  ui_story_5004_50040701_51_dialog_content = "...",
  ui_story_5004_50040701_52_dialog_content = "¡Hey!",
  ui_story_5004_50040701_53_dialog_content = "¡No me toques!",
  ui_story_5004_50040701_54_dialog_content = "¿Ves eso, PlayerName? ¡Me golpeó primero!",
  ui_story_5004_50040701_55_dialog_content = "Espera, ¿no lo esquivaste? No seamos violentos.",
  ui_story_5004_50040701_56_dialog_content = "¿Quién eres? ¿Y quién es este musculoso?",
  ui_story_5004_50040701_57_dialog_content = "¡Qué crees que haces gritándole a la gente y tratando de agarrar el hombro de una dama!",
  ui_story_5004_50040701_58_dialog_content = "¡No quieres meterte conmigo! ¡Coquetea con alguien más!",
  ui_story_5004_50040701_59_dialog_content = "¡Apártate, PlayerName! ¡Voy a encerrar a esta chica en el asiento trasero!",
  ui_story_5004_50040701_60_dialog_content = "Tiempo perfecto. Estaba buscando desahogarme...",
  ui_story_5004_50040701_61_dialog_content = "Je, ha pasado mucho tiempo desde que te vi. No pensé que estarías cerca de esta gente sencilla, <color=#FFB400>Smokey</color>.",
  ui_story_5004_50040701_62_dialog_content = "¿Todavía te llamas noble?",
  ui_story_5004_50040701_63_dialog_content = "¿Quién eres? ¿Qué te importa si soy noble o no?",
  ui_story_5004_50040701_64_dialog_content = "¡¿No me recuerdas?!",
  ui_story_5004_50040701_65_dialog_content = "Oye, no he terminado contigo...",
  ui_story_5004_50040701_66_dialog_content = "¡Cállate!",
  ui_story_5004_50040701_67_dialog_content = "¡Mira más de cerca esta vez!",
  ui_story_5004_50040701_68_dialog_content = "No sé quién eres, así que mantente alejada de mí.",
  ui_story_5004_50040701_69_dialog_content = "¡Soy <color=#FFB400>Genevieve</color>! ¡<color=#FFB400>Genevieve</color> de <color=#FFB400>Vronsky</color>!",
  ui_story_5004_50040701_70_dialog_content = "Espera, eso me suena...",
  ui_story_5004_50040701_71_dialog_content = "Petyaburg...",
  ui_story_5004_50040701_72_dialog_content = "¡Correcto, Petyaburg!",
  ui_story_5004_50040701_73_dialog_content = "<size=30>PlayerName, qué está pasando con esas chicas...</size>",
  ui_story_5004_50040701_74_dialog_content = "<size=30>¿Cómo puedo saberlo?</size>",
  ui_story_5004_50040701_75_dialog_content = "¡Ahora recuerdo! ¡Genevieve! Has crecido mucho más.",
  ui_story_5004_50040701_76_dialog_content = "¿Qué? ¡Qué desprecio de tu parte!",
  ui_story_5004_50040701_77_dialog_content = "¡Mi familia y yo fuimos deshonrados por tu culpa!",
  ui_story_5004_50040701_78_dialog_content = "¿De qué estás hablando? Realmente no recuerdo eso.",
  ui_story_5004_50040701_79_dialog_content = "Ahora me duele mucho la cabeza por intentar recordar.",
  ui_story_5004_50040701_80_dialog_content = "Oh, perdí la memoria. ¿Está bien?",
  ui_story_5004_50040701_81_dialog_content = "Ok, tengo que irme. ¡Adiós, ahora hermosa señorita Genevieve!",
  ui_story_5004_50040701_82_dialog_content = "¡No vas a ninguna parte!",
  ui_story_5004_50040701_83_dialog_content = "...",
  ui_story_5004_50040701_84_dialog_content = "¿Por qué me miras?",
  ui_story_5004_50040701_85_dialog_content = "¡Oye, no te aferres a mí! Nunca le pegaría a una mujer, pero pensaré en otra cosa.",
  ui_story_5004_50040701_86_dialog_content = "No es apropiado que otros nos vean así.",
  ui_story_5004_50040701_87_dialog_content = "¡No quiero que nadie se lo tome a mal!",
  ui_story_5004_50040701_88_dialog_content = "¡Smokey!",
  ui_story_5004_50040701_89_dialog_content = "¡Nunca te perdonaré!",
  ui_story_5004_50040701_90_dialog_content = "Siento una pelea cerca, PlayerName.",
  ui_story_5004_50040701_91_dialog_content = "¿Por qué estás esperando eso?",
  ui_story_5004_50040701_92_dialog_content = "No lo entiendes. La lucha es una forma importante de comunicarse y demostrar tu valor en Rediesel Wrench.",
  ui_story_5004_50040701_93_dialog_content = "Lo que sea... Creo que la rubia ganará.",
  ui_story_5004_50040701_94_dialog_content = "¿Por qué piensas eso?",
  ui_story_5004_50040701_95_dialog_content = "Sensación de Celestita.",
  ui_story_5004_50040701_96_dialog_content = "Estás fuera de tu liga aquí. Mira a Smokey, la chica del cabello plateado.",
  ui_story_5004_50040701_97_dialog_content = "Tiene buen juego de pies y sin fallas en sus movimientos.",
  ui_story_5004_50040701_98_dialog_content = "Sus ojos están llenos de confianza, por lo que esta no es su primera vez.",
  ui_story_5004_50040701_99_dialog_content = "Mientras que la rubia de allí, puede ser agresiva, pero no poder controlar tus emociones significa que no puedes controlar tu poder.",
  ui_story_5004_50040701_100_dialog_content = "Todavía le queda un largo camino para dominar sus Luminatics.",
  ui_story_5004_50040701_101_dialog_content = "Que profundo... ¿Dónde aprendiste eso?",
  ui_story_5004_50040701_102_dialog_content = "¡Wooga!",
  ui_story_5004_50040701_103_dialog_content = "¡Fuera de mi camino!",
  ui_story_5004_50040701_103X_dialog_content = "¿También hay Eclipsites aquí?",
  ui_story_5004_50040701_103X1_dialog_content = "Eso no es nada. Piensa en Eclipsites como una especialidad local.",
  ui_story_5004_50040701_104_dialog_content = "Hmm, esa Genevieve sabe luchar algo.",
  ui_story_5004_50040701_105_dialog_content = "¡Eclipsite detrás de ti!",
  ui_story_5004_50040701_106_dialog_content = "Dime, ¿no eres seguridad, Brock? ¿Solo lo vas a ver?",
  ui_story_5004_50040701_107_dialog_content = "¡Oh si, lo olvidé!",
  ui_story_5004_50040701_108_dialog_content = "Ok, inmundos Eclipsites, ¡es hora de enterrarlos a todos en la arena!",
  ui_story_5004_50040701_109_dialog_content = "¡Máxima velocidad adelante!",
  ui_story_5004_50040701_110_dialog_content = "¡Eso solo tomó un segundo!",
  ui_story_5004_50040701_111_dialog_content = "Por supuesto, ¿qué más esperas?",
  ui_story_5004_50040701_112_dialog_content = "¿Estás bien?",
  ui_story_5004_50040701_113_dialog_content = "¿Quién te dijo que interfirieras?",
  ui_story_5004_50040701_114_dialog_content = "¡Smokey se escapó gracias a ti!",
  ui_story_5004_50040701_115_dialog_content = "¡Lo siento!",
  ui_story_5004_50040701_116_dialog_content = "¡No me hables! Estoy muy enojada ahora...",
  ui_story_5004_50040701_117_dialog_content = "¡Debo averiguar qué está tramando y frustrar su plan por completo!",
  ui_story_5004_50040701_118_dialog_content = "¡Gracias y adiós!",
  ui_story_5004_50040701_119_dialog_content = "Ella se ha ido.",
  ui_story_5004_50040701_120_dialog_content = "¿Ves eso, PlayerName? Los asuntos entre dos mujeres son mucho más horribles que cualquier Eclipsite.",
  ui_story_5004_50040701_121_dialog_content = "Te sugiero que no te involucres.",
  ui_story_5004_50040701_122_dialog_content = "Ni siquiera lo consideré.",
  ui_story_5004_50040701_123_dialog_content = "¡Delicioso!",
  ui_story_5004_50040701_124_dialog_content = "Lo tienes en el costado de tus labios. Déjame limpiarlo.",
  ui_story_5004_50040701_125_dialog_content = "Oh, gracias.",
  ui_story_5004_50040701_126_dialog_content = "No puedo controlarme, ¡el comedor de Illumina nunca sirvió algo tan bueno!",
  ui_story_5004_50040701_127_dialog_content = "Especialmente cuando la dama de manos temblorosas dejaba caer la carne ya escasa en la olla mientras me recogía la comida.",
  ui_story_5004_50040701_128_dialog_content = "Estoy creciendo aun, ¡sabes!",
  ui_story_5004_50040701_129_dialog_content = "No es raro que prácticamente vivieras en el café cuando estudiabas en Lumopolis.",
  ui_story_5004_50040701_132_dialog_content = "No nos tienes que esperar, Fleur. Únete a nosotros, eres nuestro amigo.",
  ui_story_5004_50040701_133_dialog_content = "No puedo. Son nuestros invitados y es mi trabajo atenderlos.",
  ui_story_5004_50040701_134_dialog_content = "Pero...",
  ui_story_5004_50040701_135_dialog_content = "No le hagas caso, PlayerName.",
  ui_story_5004_50040701_136_dialog_content = "Todo el mundo sabe que esa es su naturaleza y él disfruta con eso.",
  ui_story_5004_50040701_137_dialog_content = "¿Qué te gustaría beber, Brock?",
  ui_story_5004_50040701_138_dialog_content = "¡Algo helado!",
  ui_story_5004_50040701_139_dialog_content = "Entiendo. Ya viene.",
  ui_story_5004_50040701_140_dialog_content = "...",
  ui_story_5004_50040701_141_dialog_content = "¿Por qué tu cara se pone roja, PlayerName?",
  ui_story_5004_50040701_142_dialog_content = "¿Está? No lo creo...",
  ui_story_5004_50040701_143_dialog_content = "Parece que los Celestitas tampoco son inmunes al efecto.",
  ui_story_5004_50040701_144_dialog_content = "¿Inmune? ¿De qué estás hablando?",
  ui_story_5004_50040701_145_dialog_content = "Mejor pregúntale al compañero en persona.",
  ui_story_5004_50040701_146_dialog_content = "Entonces, ¿qué está pasando con las dos mujeres de esta tarde?",
  ui_story_5004_50040701_147_dialog_content = "¿Cómo puedo saber? Yo tampoco las conozco.",
  ui_story_5004_50040701_148_dialog_content = "Es muy sospechoso. La persona que me pateó estaba obviamente buscando algo.",
  ui_story_5004_50040701_149_dialog_content = "Debería enterrar la llave del auto en algún lugar.",
  ui_story_5004_50040701_150_dialog_content = "¡Nadie quiere robar tu auto!",
  ui_story_5004_50040701_151_dialog_content = "¿Otra persona buscando algo? ¡Beryl y yo nos encontramos con alguien así esta tarde!",
  ui_story_5004_50040701_152_dialog_content = "¿Verdad, Beryl?",
  ui_story_5004_50040701_153_dialog_content = "Si. Cabello blanco grisáceo, usando gafas de sol, inaccesible y un poco aterradora...",
  ui_story_5004_50040701_154_dialog_content = "(Suena como la misma persona.)",
  ui_story_5004_50040701_155_dialog_content = "Fue de mala educación como hurgó, PlayerName.",
  ui_story_5004_50040701_156_dialog_content = "¡Y pisó el castillo de arena que Beryl pasó tres horas construyendo!",
  ui_story_5004_50040701_157_dialog_content = "¡Más de 9 pies de altura y era sublime! ¡Así de grande!",
  ui_story_5004_50040701_158_dialog_content = "Está bien, se disculpó.",
  ui_story_5004_50040701_159_dialog_content = "¡Pero te pasaste una tarde entera haciendo ese castillo, Beryl!",
  ui_story_5004_50040701_160_dialog_content = "Aún así, estoy feliz de estar así de relajada y despreocupada.",
  ui_story_5004_50040701_161_dialog_content = "Ese castillo siempre está en mi mente. Puedo verlo cuando cierro los ojos.",
  ui_story_5004_50040701_162_dialog_content = "Si a Raphaela le gusta, puedo construir otro mañana.",
  ui_story_5004_50040701_163_dialog_content = "¿En serio? ¡Déjame ayudarte!",
  ui_story_5004_50040701_164_dialog_content = "Seguro.",
  ui_story_5004_50040701_165_dialog_content = "Todavía no sabemos quién es y qué motivo.",
  ui_story_5004_50040701_166_dialog_content = "Déjalo y no le prestes tanta atención, Brock.",
  ui_story_5004_50040701_167_dialog_content = "Le prometí a Fleur que haría un gran trabajo asegurando las instalaciones.",
  ui_story_5004_50040701_168_dialog_content = "(¿Es por eso que corriste hacia mí la primera oportunidad que tuviste?)",
  ui_story_5004_50040701_169_dialog_content = "Le pedí a Brock que viniera.",
  ui_story_5004_50040701_170_dialog_content = "Tu bebida con hielo extra. ¡Disfrútalo!",
  ui_story_5004_50040701_171_dialog_content = "Te dije que mantengo mis palabras... ¡Ack!",
  ui_story_5004_50040701_172_dialog_content = "¡¿Qué diablos es esto?!",
  ui_story_5004_50040701_173_dialog_content = "Lo siento, no tenemos las cosas a las que estás acostumbrado, así que hice algunas sustituciones.",
  ui_story_5004_50040701_174_dialog_content = "¿A qué tipo de cosas estás acostumbrado, Brock? ¡La gente de Rediesel Wrench son cosa seria!",
  ui_story_5004_50040701_175_dialog_content = "Este es para ti, PlayerName.",
  ui_story_5004_50040701_176_dialog_content = "Nuestro toque especial como bienvenida.",
  ui_story_5004_50040701_177_dialog_content = "Especial... no hay nada venenoso ahí, ¿verdad?",
  ui_story_5004_50040701_178_dialog_content = "No te preocupes, no contiene veneno ni alcohol. Todos pueden disfrutar.",
  ui_story_5004_50040701_X178_dialog_content = "¡Eres muy reflexivo!",
  ui_story_5004_50040701_179_dialog_content = "Además, si te parece bien, me gustaría charlar contigo en privado lo antes posible, PlayerName.",
  ui_story_5004_50040701_180_dialog_content = "Tengo tiempo.",
  ui_story_5004_50040701_181_dialog_content = "(Un gran equilibrio entre lo dulce y lo amargo, la fragancia de los cítricos aclara toda la bebida y le agrega muchas capas.)",
  ui_story_5004_50040701_182_dialog_content = "(Bebida agradable e intrincada...)",
  ui_story_5004_50040901_1_dialog_content = "No, debo levantarme...",
  ui_story_5004_50040901_2_dialog_content = "Me quedé dormido en un montón de piezas mecánicas. Me duele la espalda.",
  ui_story_5004_50040901_3_dialog_content = "Probablemente dibujé este plano anoche...",
  ui_story_5004_50040901_4_dialog_content = "Es inútil. Debería estar en la basura.",
  ui_story_5004_50040901_5_dialog_content = "Supongo que tengo que confiar en el <color=#FFB400>conocimiento de Celestitas</color>...",
  ui_story_5004_50040901_6_dialog_content = "Esos robots de Illumina y Lumopolis no son suficientes. Con un análisis preliminar, no puedo crear lo que quiero.",
  ui_story_5004_50040901_7_dialog_content = "Dúchate primero antes de la cita con PlayerName.",
  ui_story_5004_50040901_8_dialog_content = "Si no puedo completar el Soberano del Océano, no podré escapar del efecto de mi <color=#FFB400>rasgo especial</color>.",
  ui_story_5004_50040901_9_dialog_content = "(Se suponía que yo era un mecánico ordinario de Illumina.)",
  ui_story_5004_50040901_10_dialog_content = "(Pero debido al rasgo especial latente en mis genes...)",
  ui_story_5004_50040901_11_dialog_content = "(Cuando estaba en el colegio...)",
  ui_story_5004_50040901_12_dialog_content = "Fleur, <size=45>¡Fleur!</size>",
  ui_story_5004_50040901_13_dialog_content = "¡Hola! ¡Y hola a ti también!",
  ui_story_5004_50040901_14_dialog_content = "¿Puedes mostrarme cómo resolver este problema, Fleur?",
  ui_story_5004_50040901_15_dialog_content = "Seguro. Pregúntame libremente.",
  ui_story_5004_50040901_16_dialog_content = "¿Por qué molestas a Fleur todo el tiempo?",
  ui_story_5004_50040901_17_dialog_content = "¿Estás intentando mudarte Fleur?",
  ui_story_5004_50040901_18_dialog_content = "¿Qué tal? <size=45>¡Fleur no te pertenece!</size>",
  ui_story_5004_50040901_19_dialog_content = "¡Oigan, chicas, dejen de acorralar a Fleur todo el día!",
  ui_story_5004_50040901_20_dialog_content = "No está interesado en ustedes. ¿Verdad, Fleur?",
  ui_story_5004_50040901_21_dialog_content = "¿Qué? ¿Te gustan las niñas o los niños, Fleur? ¡Contéstame!",
  ui_story_5004_50040901_22_dialog_content = "Me gustan todos.",
  ui_story_5004_50040901_23_dialog_content = "Tiene un don para las máquinas, trabaja duro y es amable.",
  ui_story_5004_50040901_24_dialog_content = "Él es extraordinario.",
  ui_story_5004_50040901_25_dialog_content = "Pero ese rasgo especial suyo hace que sea difícil para él estar cerca.",
  ui_story_5004_50040901_26_dialog_content = "Ya sea masculino o femenino, incluso los animales acuden a él.",
  ui_story_5004_50040901_27_dialog_content = "Sin mencionar <color=#FFB400>el incidente</color> que causó muchas bajas.",
  ui_story_5004_50040901_28_dialog_content = "¿Por qué no lo enviamos al nuevo <color=#FFB400>Undercity 38</color>? Al menos hay menos aurorians allí...",
  ui_story_5004_50040901_29_dialog_content = "Es lo mejor, él no se molesta y nos quedamos sin problemas.",
  ui_story_5004_50040901_30_dialog_content = "Felicitaciones, Fleur. Serás enviado a la Subciudad 38 como especialista en construcción.",
  ui_story_5004_50040901_31_dialog_content = "Es una oportunidad única en la vida y el testimonio de la fe de Illumina en ti.",
  ui_story_5004_50040901_32_dialog_content = "Tendrás mucho espacio para mostrar lo que puedes hacer, ¡y sabemos que puedes dejar tu huella allí!",
  ui_story_5004_50040901_33_dialog_content = "(Fue un momento feliz, tranquilo y silencioso.)",
  ui_story_5004_50040901_34_dialog_content = "Mi esposa vendrá a la Subciudad 38 la semana que viene. ¡No nos hemos visto en años!",
  ui_story_5004_50040901_35_dialog_content = "No podemos estar con nuestros cónyuges porque ese tipo está aquí. ¡Ni nuestras hijas pueden venir!",
  ui_story_5004_50040901_36_dialog_content = "¡Nuestras mascotas siguen yendo a su casa!",
  ui_story_5004_50040901_37_dialog_content = "¡Aléjate de él a menos que quieras caer bajo su hechizo!",
  ui_story_5004_50040901_38_dialog_content = "Cálmate. Fleur no es una amenaza para todos.",
  ui_story_5004_50040901_39_dialog_content = "¡Ja! ¡Todos en Illumina conocen <color=#FFB400>el incidente</color> que causó en la escuela!",
  ui_story_5004_50040901_40_dialog_content = "¡La gente se lastimó por su culpa! ¡No uno, eran muchos! ¿Por qué lo estás encubriendo?",
  ui_story_5004_50040901_42_dialog_content = "Gracias por tu contribución a la Subciudad 38, Fleur.",
  ui_story_5004_50040901_43_dialog_content = "Pero es hora de que regreses a Gannon. La gente está...",
  ui_story_5004_50040901_44_dialog_content = "Está bien, lo entiendo.",
  ui_story_5004_50040901_45_dialog_content = "Pero no quiero volver.",
  ui_story_5004_50040901_46_dialog_content = "No quiero dejar la Subciudad 38. He tenido tiempos felices y tranquilos aquí.",
  ui_story_5004_50040901_47_dialog_content = "No hay gente a mi alrededor y puedo investigar en paz.",
  ui_story_5004_50040901_48_dialog_content = "Dijiste que dejaría mi marca aquí...",
  ui_story_5004_50040901_49_dialog_content = "...",
  ui_story_5004_50040901_50_dialog_content = "Lo siento, ahora es diferente. No nos obligues a llevarte de regreso.",
  ui_story_5004_50040901_51_dialog_content = "¿Qué puedo hacer si vuelvo?",
  ui_story_5004_50040901_52_dialog_content = "¿Me pondrán en cuarentena o permaneceré en el Departamento de Investigación como sujeto de experimentos?",
  ui_story_5004_50040901_53_dialog_content = "Lo siento...",
  ui_story_5004_50040901_54_dialog_content = "Hicimos todo lo que pudimos.",
  ui_story_5004_50040901_55_dialog_content = "¡Pero hay un chance ahora!",
  ui_story_5004_50040901_56_dialog_content = "¡Bienvenido al Tir' Hotel, Fleur! Supongo que has leído la carta, ¿no?",
  ui_story_5004_50040901_57_dialog_content = "Si. Puedo ayudarte con el Soberano del Océano, pero ¿eres realmente capaz de eliminar mi rasgo especial?",
  ui_story_5004_50040901_58_dialog_content = "No te preocupes, encontré la información en las ruinas. Si la leyenda es cierta, sí, lo soy.",
  ui_story_5004_50040901_59_dialog_content = "Ah, este joven debe ser Fleur. Serás el administrador del lobby y responsable de la preparación del Soberano del Océano.",
  ui_story_5004_50040901_59X1_dialog_content = "Entiendo. Empezaré ahora mismo.",
  ui_story_5004_50040901_59X2_dialog_content = "Empezamos bien. Oh, ¿qué es eso de la leyenda que acabas de mencionar?",
  ui_story_5004_50040901_59X3_dialog_content = "Me lo inventé. Siempre que los consiga aquí, ¿cuál es la diferencia, no?",
  ui_story_5004_50040901_59X4_dialog_content = "Je, claro. Siempre que incluyas a todos en la lista...",
  ui_story_5004_50040901_59X5_dialog_content = "El Soberano del Océano... Aprovecharé esta oportunidad.",
  ui_story_5004_50040901_60_dialog_content = "Estoy listo...",
  ui_story_5004_50040901_61_dialog_content = "¡Ve, Fleur!",
  ui_story_5004_50040901_62_dialog_content = "¡Fleur!",
  ui_story_5004_50040901_63_dialog_content = "<size=45>¡Sr. Fleur!</size>",
  ui_story_5004_50040901_64_dialog_content = "Buenos días a todos.",
  ui_story_5004_50040901_65_dialog_content = "¡Hueles tan bien, Sr. Fleur!",
  ui_story_5004_50040901_66_dialog_content = "¿Estabas en la ducha? ¡Escuché agua correr!",
  ui_story_5004_50040901_67_dialog_content = "Oh, umm... ¿Te importaría cederme el paso?",
  ui_story_5004_50040901_68_dialog_content = "¿Puedo entrar a tu habitación?",
  ui_story_5004_50040901_69_dialog_content = "Prefiero que todas las partes mecánicas de mi habitación se queden exactamente donde están...",
  ui_story_5004_50040901_70_dialog_content = "Fleury, el instructor de yoga dijo que podría hacer ejercicio contigo en la clase si me inscribía. ¿Es cierto?",
  ui_story_5004_50040901_71_dialog_content = "¿En serio? Eso suena a estafa...",
  ui_story_5004_50040901_72_dialog_content = "Todos, por favor cálmense, gracias. Tengo que ver a alguien, así que abran paso...",
  ui_story_5004_50040901_73_dialog_content = "<anim type=Shake><size=45>¿Qué?</size></anim>",
  ui_story_5004_50040901_74_dialog_content = "¿Quién es? ¡Qué pequeño bribón astuto!",
  ui_story_5004_50040901_75_dialog_content = "Sr. Fleur, ¿no sería mejor pasar el rato con nosotros?",
  ui_story_5004_50040901_76_dialog_content = "(Maldita sea, parece que PlayerName tendrá que esperar.)",
  ui_story_5004_50041001_1_dialog_content = "Ya veo. Ahora entiendo.",
  ui_story_5004_50041001_2_dialog_content = "Gracias por tu paciencia y perdón. ¡Te lo agradezco mucho!",
  ui_story_5004_50041001_3_dialog_content = "No lo menciones. Pero Fleur, ¿realmente vas a construir un robot por tu cuenta?",
  ui_story_5004_50041001_4_dialog_content = "Sí, ese es mi deseo.",
  ui_story_5004_50041001_5_dialog_content = "<color=#e8d9bb>Toc, toc.</color>",
  ui_story_5004_50041001_6_dialog_content = "¿Puedo entrar, PlayerName?",
  ui_story_5004_50041001_7_dialog_content = "Seguro.",
  ui_story_5004_50041001_8_dialog_content = "Oh, Fleur también está aquí.",
  ui_story_5004_50041001_9_dialog_content = "Eres el jefe del Comité Soberano del Océano. Holgazanear es lo último para ti, ¿no?",
  ui_story_5004_50041001_10_dialog_content = "No lo estoy. Estoy aquí para pedir la opinión de PlayerName sobre problemas de diseño.",
  ui_story_5004_50041001_11_dialog_content = "Debería volver y revisar los planos nuevamente. Adiós.",
  ui_story_5004_50041001_12_dialog_content = "¿Alguna decisión sobre unirse al Soberano del Océano, PlayerName? El premio incluye...",
  ui_story_5004_50041001_13_dialog_content = "Queremos participar.",
  ui_story_5004_50041001_14_dialog_content = "¿Qué?",
  ui_story_5004_50041001_15_dialog_content = "¿Algún problema? Lo hablé con mis amigos y ellos...",
  ui_story_5004_50041001_16_dialog_content = "Inesperado. Pensé que tardarías más que esto, ¿no?",
  ui_story_5004_50041001_17_dialog_content = "Al final, es un festival. ¿Qué hay que pensar?",
  ui_story_5004_50041001_18_dialog_content = "¿No tienes miedo de que pueda ser una conspiración, PlayerName?",
  ui_story_5004_50041001_19_dialog_content = "¿Conspiración? ¡Entonces no!",
  ui_story_5004_50041001_20_dialog_content = "Jajaja, que adorable. ¡Aun yo, un miembro de True Order, no lo revelaría abiertamente si fuera una conspiración!",
  ui_story_5004_50041001_21_dialog_content = "Es un cumplido, porque tomaste la decisión correcta, ¿no?",
  ui_story_5004_50041001_22_dialog_content = "(¿Por qué todo mundo en la True Order es tan raro?)",
  ui_story_5004_50041001_23_dialog_content = "Ya que estás inscrito, firma este documento.",
  ui_story_5004_50041001_24_dialog_content = "Usa este bolígrafo.",
  ui_story_5004_50041001_25_dialog_content = "Oye, es muy refinado.",
  ui_story_5004_50041001_26_dialog_content = "Y frío, como el hielo.",
  ui_story_5004_50041001_27_dialog_content = "Está hecho de un cristal excepcionalmente raro, parece muy caro, ¿no?",
  ui_story_5004_50041001_28_dialog_content = "Y de hecho, está valorado a la mitad de este hotel en precio.",
  ui_story_5004_50041001_29_dialog_content = "Puedes llevarlo como regalo, PlayerName. Estás interesado, ¿no?",
  ui_story_5004_50041001_30_dialog_content = "¡No, no puedo aceptar un regalo tan valioso!",
  ui_story_5004_50041001_31_dialog_content = "Está bien, fue desenterrado de las ruinas.",
  ui_story_5004_50041001_32_dialog_content = "Ese es el True Order que conozco, excavando ruinas por todas partes.",
  ui_story_5004_50041001_33_dialog_content = "Qué halagador. Oh, escuché que el panel de control de tu Colossus se parece a un... ¿piano?",
  ui_story_5004_50041001_34_dialog_content = "¿Tendría la fortuna de verlo? Soy música y tú tienes un piano inusual, ¿no?",
  ui_story_5004_50041001_35_dialog_content = "Se puede organizar un recorrido. ¡El papel está firmado!",
  ui_story_5004_50041001_36_dialog_content = "Ya veo. Ok, listo, ¡ahora eres oficialmente un concursante!",
  ui_story_5004_50041001_37_dialog_content = "El primer partido será esta tarde. Deberías descansar un poco antes de eso.",
  ui_story_5004_50041001_38_dialog_content = "Espero tu éxito.",
  ui_story_5004_50041001_39_dialog_content = "Oye, eso fue muy suave, ¿no?",
  ui_story_5004_50041001_40_dialog_content = "¿Es culpa lo que estoy sintiendo ahora?",
  ui_story_5004_50041001_X40_dialog_content = "Hmm... no.",
  ui_story_5004_50041001_X40X1_dialog_content = "Entonces, aquí estamos, incluido el Celestita.",
  ui_story_5004_50041001_X40X2_dialog_content = "No esperaba que PlayerName firmara con el lápiz de esa persona tan fácil...",
  ui_story_5004_50041001_X40X3_dialog_content = "Me pregunto qué trama esa persona... No importa, esos Eclipsites no significarán nada, de todos modos.",
  ui_story_5004_50041001_41_dialog_content = "La primera mitad del <color=#FFB400>Movimiento</color>, bastante fácil.",
  ui_story_5004_50041001_42_dialog_content = "PlayerName seguro que es una figura interesante.",
  ui_story_5004_50041101_1_dialog_content = "<color=#e8d9bb>Mientras tanto...</color>",
  ui_story_5004_50041101_2_dialog_content = "Muy bien, has captado la clave.",
  ui_story_5004_50041101_3_dialog_content = "Te acercarás un paso más a lo divino con el poder del Celestita.",
  ui_story_5004_50041101_4_dialog_content = "Te muestro el camino, tú me consigues la fruta.",
  ui_story_5004_50041101_5_dialog_content = "Ya no tienes que atender a las masas sucias... Alcanzarás el verdadero pináculo de la música.",
  ui_story_5004_50041101_6_dialog_content = "Entiendo. ¡Esto es exactamente lo que quería!",
  ui_story_5004_50041101_7_dialog_content = "Es extraño cada vez que te veo murmurar para ti misma. Entonces, ¿qué dijo la voz en tu cabeza esta vez?",
  ui_story_5004_50041101_8_dialog_content = "Te entregué la primera mitad del Movimiento, ya que pusiste a todos los de la lista en el concurso, como acordamos.",
  ui_story_5004_50041101_9_dialog_content = "¿Te está molestando esa voz por conseguir la segunda mitad?",
  ui_story_5004_50041101_10_dialog_content = "Los Eclipsites están excavando, pero es inútil incluso si lo consigues.",
  ui_story_5004_50041101_11_dialog_content = "Todavía necesitas el poder de un Celestita para despertarlo.",
  ui_story_5004_50041101_12_dialog_content = "Esto no te incumbe.",
  ui_story_5004_50041101_13_dialog_content = "Para que quede claro, mi objetivo es el Movimiento Divino completo, no incitar a los Eclipsites.",
  ui_story_5004_50041101_14_dialog_content = "Esto sucedió solo porque proporcionaste la primera mitad y me prometiste la segunda mitad.",
  ui_story_5004_50041101_15_dialog_content = "Eso hace que esto sea un interés mutuo, no una asociación permanente, ¿ok?",
  ui_story_5004_50041101_15X_dialog_content = "Por cierto, los Eclipsites que enviaste fueron eliminados por PlayerName y esos Aurorians.",
  ui_story_5004_50041101_16_dialog_content = "Ratas inútiles.",
  ui_story_5004_50041101_17_dialog_content = "¡Vil e inmundo Aurorian!",
  ui_story_5004_50041101_18_dialog_content = "Déjalo enfriar.",
  ui_story_5004_50041101_19_dialog_content = "No quieres descubran tu madriguera y sea estropeada, ¿verdad?",
  ui_story_5004_50041101_20_dialog_content = "¿No tienes planes ridículos tú mismo? Como dibujar turistas con el Soberano del Océano para financiar su esfuerzo, ¿no?",
  ui_story_5004_50041101_21_dialog_content = "Estafas tontas para lanzarse sobre los turistas. Lecciones de yoga, divertidas.",
  ui_story_5004_50041101_22_dialog_content = "Estoy muy segura de que la mayor parte del dinero todavía se canaliza al jefe real, ¿no?",
  ui_story_5004_50041101_23_dialog_content = "Como decoración, eres solo una herramienta.",
  ui_story_5004_50041101_24_dialog_content = "Me pregunto como tus compañeros Eclipsites se burlarán de ti por trabajar para un Aurorian.",
  ui_story_5004_50041101_25_dialog_content = "¡Cómo te atreves! Nosotros...",
  ui_story_5004_50041101_26_dialog_content = "¡Señor Prinny!",
  ui_story_5004_50041101_27_dialog_content = "¡Esto no ha terminado, ya verás!",
  ui_story_5004_50041101_28_dialog_content = "Ve al invitado fuera, maestro Thaddius.",
  ui_story_5004_50041101_29_dialog_content = "Por aquí por favor.",
  ui_story_5004_50041101_30_dialog_content = "Permíteme contarte sobre mi último curso de yoga mientras te llevo a casa.",
  ui_story_5004_50041101_31_dialog_content = "Perfección es un estado mental. Elegancia es una forma de vida. Tolerancia es una forma de pensar. Una hermosa vida comienza con el yoga.",
  ui_story_5004_50041101_32_dialog_content = "El yoga es tu viaje de lo mundano a lo extraordinario.",
  ui_story_5004_50041101_33_dialog_content = "El yoga es el arte espiritual de la trascendencia.",
  ui_story_5004_50041101_34_dialog_content = "...",
  ui_story_5004_50041201_1_dialog_content = "¿Es este el sitio de la competencia?",
  ui_story_5004_50041201_2_dialog_content = "Puesto de árbitro, red... Básicamente coincide con la descripción del archivo de Soroz.",
  ui_story_5004_50041201_2X1_dialog_content = "Oye, ¿qué es eso de ahí?",
  ui_story_5004_50041201_2X2_dialog_content = "No te preocupes. Es solo un dispositivo de control de daños.",
  ui_story_5004_50041201_2X3_dialog_content = "Es para evitar que dañes los accesorios circundantes en el fragor de la batalla.",
  ui_story_5004_50041201_2X4_dialog_content = "(¿Batalla? ¿Pensé que era un juego de voleibol?)",
  ui_story_5004_50041201_2X5_dialog_content = "Uf, hecho.",
  ui_story_5004_50041201_3_dialog_content = "Ok, el árbitro también está en posición.",
  ui_story_5004_50041201_4_dialog_content = "¡Bienvenidos al partido inaugural de voleibol Soberano del Océano, una prueba de fuerza y valentía!",
  ui_story_5004_50041201_5_dialog_content = "A mi derecha está el equipo dirigido por PlayerName.",
  ui_story_5004_50041201_6_dialog_content = "Hola, Fleur, estás con PlayerName, ¿no?",
  ui_story_5004_50041201_7_dialog_content = "¿Fleur está aquí?",
  ui_story_5004_50041201_8_dialog_content = "No he practicado deportes con Brock desde hace mucho tiempo, y Bonacie me ha estado incitando.",
  ui_story_5004_50041201_9_dialog_content = "Pero la multitud probablemente se saldrá de control con él aquí...",
  ui_story_5004_50041201_10_dialog_content = "¡Fleur!",
  ui_story_5004_50041201_11_dialog_content = "¡Fleury!",
  ui_story_5004_50041201_12_dialog_content = "También lo creo...",
  ui_story_5004_50041201_13_dialog_content = "No soy el mejor en los deportes...",
  ui_story_5004_50041201_14_dialog_content = "No te preocupes, PlayerName. ¡Soy muy buena en el voleibol!",
  ui_story_5004_50041201_15_dialog_content = "Cierto, a Vice le fue muy bien en educación física y deportes en la escuela.",
  ui_story_5004_50041201_16_dialog_content = "No la llaman <color=#FFB400>la Doncella de Hierro</color> por nada.",
  ui_story_5004_50041201_17_dialog_content = "Puedes estar seguro, PlayerName. Si podemos.",
  ui_story_5004_50041201_18_dialog_content = "(¡Las escuelas de Lumopolis y los apodos extraños!)",
  ui_story_5004_50041201_19_dialog_content = "¿En serio? Eso es genial. ¡Muestra lo que tienes, Vice!",
  ui_story_5004_50041201_20_dialog_content = "Qué suerte tengo, estoy en tu equipo.",
  ui_story_5004_50041201_21_dialog_content = "Oye, eres la chica de ayer... ¿Te inscribiste también?",
  ui_story_5004_50041201_22_dialog_content = "¡Es la chica que arruinó el castillo de arena de Beryl!",
  ui_story_5004_50041201_23_dialog_content = "¿Y qué? ¿Puedo unirme? ¡Bonacie me invitó!",
  ui_story_5004_50041201_24_dialog_content = "Además, mi nombre es Smokey y ya me disculpé por el castillo de arena.",
  ui_story_5004_50041201_25_dialog_content = "No peleemos. Estamos en el mismo equipo. Necesitamos trabajar juntos y ganar.",
  ui_story_5004_50041201_26_dialog_content = "¿Esa es la mala chica que mencionaste ayer? No parece que sepa jugar limpio...",
  ui_story_5004_50041201_27_dialog_content = "Si. Pero <color=#FFB400>la otra</color> que mencioné es aún más difícil de llevar.",
  ui_story_5004_50041201_28_dialog_content = "¡A mi izquierda están Genevieve y sus ardientes fans!",
  ui_story_5004_50041201_29_dialog_content = "¡Hmph!",
  ui_story_5004_50041201_30_dialog_content = "¡Esa es ella!",
  ui_story_5004_50041201_31_dialog_content = "<anim type=Shake><size=45>¡Hurra, hurra, hurra!</size></anim>",
  ui_story_5004_50041201_32_dialog_content = "Je, ¿ves eso, Smokey?",
  ui_story_5004_50041201_33_dialog_content = "Un verdadero noble es amado por la gente común dondequiera que vaya.",
  ui_story_5004_50041201_34_dialog_content = "¡Ellos reconocen mi posición más alta debido a mi carácter noble y se someten a mi autoridad!",
  ui_story_5004_50041201_35_dialog_content = "¡Es algo que nunca entenderás, Smokey!",
  ui_story_5004_50041201_36_dialog_content = "Bien, bien, lo que sea.",
  ui_story_5004_50041201_37_dialog_content = "Quién querría entender ese tipo de tonterías aburridas de todos modos-",
  ui_story_5004_50041201_38_dialog_content = "Hey, no se detengan, chicos. ¡Empecemos ya!",
  ui_story_5004_50041201_39_dialog_content = "¿Estás burlándote? Te mostrare...",
  ui_story_5004_50041201_40_dialog_content = "¡Espera, el juego aún no ha comenzado!",
  ui_story_5004_50041201_41_dialog_content = "Tsk.",
  ui_story_5004_50041201_42_dialog_content = "¡Wow, reflejos asombrosos!",
  ui_story_5004_50041201_43_dialog_content = "!!!",
  ui_story_5004_50041201_44_dialog_content = "(La pelota se dirige hacia mí después de que Smokey la esquivó.)",
  ui_story_5004_50041201_45_dialog_content = "(Aunque es solo un juego de voleibol, en este momento realmente deseaba tener poder de combate.)",
  ui_story_5004_50041201_46_dialog_content = "(Ese pico asesino da más miedo que enfrentar que los Eclipsites.)",
  ui_story_5004_50041201_47_dialog_content = "(Cierro los ojos mientras mi vida pasa por mi mente.)",
  ui_story_5004_50041201_48_dialog_content = "(Con suerte, Vice puede sacarme del mar rápido).",
  ui_story_5004_50041201_49_dialog_content = "¿Te preguntas a qué sabe el agua de mar?",
  ui_story_5004_50041201_50_dialog_content = "¡PlayerName!",
  ui_story_5004_50041201_51_dialog_content = "Vice, ¿estás bien?",
  ui_story_5004_50041201_52_dialog_content = "Estoy bien, aunque casi me saca de los límites.",
  ui_story_5004_50041201_53_dialog_content = "Oye, el juego aún no ha comenzado. ¡Es en contra de las reglas, Genevieve!",
  ui_story_5004_50041201_54_dialog_content = "PlayerName, leíste el manual que te di, ¿no?",
  ui_story_5004_50041201_55_dialog_content = "¿Quién tiene tiempo para leer el libro lleno de anuncios patrocinados?",
  ui_story_5004_50041201_56_dialog_content = "Entonces no me culpes.",
  ui_story_5004_50041201_57_dialog_content = "¡Dale! ¡Muestra todo lo que tienes a los cielos!",
  ui_story_5004_50041201_58_dialog_content = "(Fui ingenuo al pensar que este era el juego de voleibol que conocía.)",
  ui_story_5004_50041201_59_dialog_content = "(Es una batalla de playa completa.)",
  ui_story_5004_50041202_1_dialog_content = "No he terminado aún...",
  ui_story_5004_50041202_2_dialog_content = "¿Es todo lo que tienes?",
  ui_story_5004_50041202_3_dialog_content = "Lo siento, PlayerName. Habría traído Capullo de luna si supiera...",
  ui_story_5004_50041202_4_dialog_content = "Está bien. Capullo de luna solo pincharía la pelota. Todavía tenemos a Brock y otros. Ustedes guarden sus fuerzas.",
  ui_story_5004_50041202_5_dialog_content = "¡Chicos, pongan algo de músculo en ello!",
  ui_story_5004_50041202_6_dialog_content = "¡Cállense!",
  ui_story_5004_50041202_7_dialog_content = "¡Oye, ojos en la pelota!",
  ui_story_5004_50041202_8_dialog_content = "¡Gracias, Brock!",
  ui_story_5004_50041202_9_dialog_content = "¡Reagrupa y pasa el balón a Genevieve!",
  ui_story_5004_50041202_10_dialog_content = "<size=45>¡Sí!</size>",
  ui_story_5004_50041202_11_dialog_content = "Genevieve me ignora. ¿Soy una amenaza para ella?",
  ui_story_5004_50041202_12_dialog_content = "Cuando la situación es tan mala, ¡es hora de sacar las <color=#FFB400>grandes armas</color>!",
  ui_story_5004_50041202_13_dialog_content = "Espera, ¿qué acabas de hacer?",
  ui_story_5004_50041202_14_dialog_content = "¿Es un <color=#FFB400>brazo mecánico</color>?",
  ui_story_5004_50041202_15_dialog_content = "Je, no, obviamente es solo <color=#FFB400>mi mano</color>.",
  ui_story_5004_50041202_16_dialog_content = "Se llama Doom RX100. ¡Lo creé con Tiny One, y me aseguré de aumentar el poder tres veces!",
  ui_story_5004_50041202_17_dialog_content = "Doom, ¿lo llamaste? ¿Es ese el nombre del brazo robótico de Jona?",
  ui_story_5004_50041202_18_dialog_content = "La única diferencia es ese rojo en el puño. ¿Cómo es ese triple potencia?",
  ui_story_5004_50041202_19_dialog_content = "¡Mi mano derecha arde en la llama de la victoria!",
  ui_story_5004_50041202_20_dialog_content = "¡Deja de jugar! ¡Seguro no funcionará ese brazo!",
  ui_story_5004_50041202_21_dialog_content = "¡La precisión y la fuerza de mi creación no perderán a nadie!",
  ui_story_5004_50041202_22_dialog_content = "¡Por supuesto, es mecánico!",
  ui_story_5004_50041202_23_dialog_content = "Es tan poderoso que puede hacer retroceder a un objetivo una docena de pies sin una pelota.",
  ui_story_5004_50041202_24_dialog_content = "De hecho, me preocupa que sea demasiado poderoso...",
  ui_story_5004_50041202_25_dialog_content = "Por supuesto, de nuevo, es mecánico. ¡Quítatelo antes de que nos descalifiquen!",
  ui_story_5004_50041202_26_dialog_content = "¿Aun no? Brock, no lo entiendes...",
  ui_story_5004_50041202_27_dialog_content = "¡Cuidado!",
  ui_story_5004_50041202_28_dialog_content = "¡Una abertura!",
  ui_story_5004_50041202_29_dialog_content = "<color=#e8d9bb>¡Aplasta, aplasta!</color>",
  ui_story_5004_50041202_30_dialog_content = "Aww, ay...",
  ui_story_5004_50041202_31_dialog_content = "Estoy acabado... El cielo... es tan bonito...",
  ui_story_5004_50041202_32_dialog_content = "¡Brock se derrumbó en la arena! ¡¿Es realmente un juego de voleibol normal?!",
  ui_story_5004_50041202_33_dialog_content = "Se acabó el primer juego. Es hora de un breve intermedio.",
  ui_story_5004_50041202_34_dialog_content = "¡Disfruta de las palabras de nuestros patrocinadores en el intermedio!",
  ui_story_5004_50041202_X33_dialog_content = "3",
  ui_story_5004_50041202_X34_dialog_content = "2",
  ui_story_5004_50041202_X35_dialog_content = "1",
  ui_story_5004_50041202_35_dialog_content = "Permítenos presentarte los paquetes de temporada más populares del Gremio de Explorador Nublar.",
  ui_story_5004_50041202_36_dialog_content = "¡Toca el icono ahora para obtener la oferta especial exclusiva de Bonacie y 10 Destello de Estrellas especial adicionales!",
  ui_story_5004_50041202_37_dialog_content = "¡Además de un tanque de pistola de agua inflable perfecto para la playa!",
  ui_story_5004_50041202_38_dialog_content = "Rápido, solo hay 5000 unidades... ¡No, quedan 1001 ahora!",
  ui_story_5004_50041202_39_dialog_content = "¡Consigue uno antes de que se acaben!",
  ui_story_5004_50041202_40_dialog_content = "¡Oh, se agotó en solo 10 segundos!",
  ui_story_5004_50041202_41_dialog_content = "Bueno, estén atentos a la Red de Compras de Bonacie. ¡Hasta la próxima!",
  ui_story_5004_50041202_42_dialog_content = "¡Este no es el momento de ver comerciales!",
  ui_story_5004_50041202_43_dialog_content = "¿Así que solo quedamos Smokey y yo?",
  ui_story_5004_50041202_44_dialog_content = "¡Oye tú, deja de holgazanear y haz algo!",
  ui_story_5004_50041202_45_dialog_content = "¿Qué? ¿En serio? Pensé que todos ustedes serían más útiles que esto.",
  ui_story_5004_50041202_46_dialog_content = "¡Resultó ser un grupo de perdedores!",
  ui_story_5004_50041202_47_dialog_content = "¡Pero bloquearon muchos golpes para ti!",
  ui_story_5004_50041202_48_dialog_content = "¡Sin ellos, te habrías perdido!",
  ui_story_5004_50041202_49_dialog_content = "¿De verdad vas a tirar la toalla ahora y desperdiciar todos sus sacrificios?",
  ui_story_5004_50041202_50_dialog_content = "Ok, biiieeen. ¿Pero no estabas mirando al margen todo este tiempo también?",
  ui_story_5004_50041202_51_dialog_content = "Dicho esto, no quiero deberle a nadie.",
  ui_story_5004_50041202_52_dialog_content = "Solo retrocede y observa de cerca. ¡Asegúrate de comentar mis increíbles movimientos!",
  ui_story_5004_50041202_53_dialog_content = "¿Comentar? ¡Ok, puedo hacer eso! ¡Lo que sea necesario para que realmente juegues!",
  ui_story_5004_50041202_54_dialog_content = "¡Ok, resuelto!",
  ui_story_5004_50041202_55_dialog_content = "Hey...",
  ui_story_5004_50041202_56_dialog_content = "¡Genevieve!",
  ui_story_5004_50041202_57_dialog_content = "¿Qué es? ¿Admitirás la derrota?",
  ui_story_5004_50041202_58_dialog_content = "Déjame preguntarte, ¿realmente te importa tanto ser superada por los demás?",
  ui_story_5004_50041202_59_dialog_content = "¡Si, claro! Mi familia y mi orgullo no tolerarán que pierda contra nadie, ¡especialmente contigo!",
  ui_story_5004_50041202_60_dialog_content = "Me robaste mi gloria. He estado siguiendo tus rastros todos estos años.",
  ui_story_5004_50041202_61_dialog_content = "¡Solo por el día en que pueda derrotarte y ver el dolor y arrepentimiento en tu rostro!",
  ui_story_5004_50041202_62_dialog_content = "Bueno, es una pena.",
  ui_story_5004_50041202_63_dialog_content = "¿Qué?",
  ui_story_5004_50041202_64_dialog_content = "¡Yo también odio perder!",
  ui_story_5004_50041202_65_dialog_content = "¡Enséñame lo que tienes!",
  ui_story_5004_50041202_66_dialog_content = "¡Veamos si realmente puedes vencerme!",
  ui_story_5004_50041202_67_dialog_content = "<anim type=Shake><size=45>¡SUPER HELLSTORM SPIKE!</size></anim>",
  ui_story_5004_50041202_68_dialog_content = "!!!",
  ui_story_5004_50041202_69_dialog_content = "¡Oh! ¡La pelota está envuelta en el fuego infernal y atraviesa el aire hacia Genevieve!",
  ui_story_5004_50041202_70_dialog_content = "(¡De hecho, hago jugada por jugada! Esto es penoso...)",
  ui_story_5004_50041202_71_dialog_content = "¡Genevieve!",
  ui_story_5004_50041202_72_dialog_content = "Los fans de Genevieve formaron un círculo para protegerla. ¿Funcionará?",
  ui_story_5004_50041202_73_dialog_content = "¡¡Como un meteorito, la pelota estalló hacia la multitud!!",
  ui_story_5004_50041202_74_dialog_content = "¡Pobre Genevieve y sus fans están fuera de los límites! ¡Y el campo ahora tiene un cráter profundo!",
  ui_story_5004_50041202_75_dialog_content = "El ganador es... ¡Equipo PlayerName!",
  ui_story_5004_50041202_76_dialog_content = "Smokey apunta hacia el cielo, ¡su pose de victoria! ¡Qué pico tan asombroso!",
  ui_story_5004_50041202_77_dialog_content = "Eres un comentarista decente. Pudiste capturar al menos la mitad de mi grandeza en tu comentario.",
  ui_story_5004_50041202_78_dialog_content = "Gracias ... ¿pero comentar no debería ser el trabajo de alguien que NO está en el juego?",
  ui_story_5004_50041202_79_dialog_content = "¡Debo decir que fue totalmente increíble! ¡Pillaste a todos de una sola vez!",
  ui_story_5004_50041202_80_dialog_content = "(¡Es un monstruo! ¿Por qué me siento triste por Genevieve de repente?)",
  ui_story_5004_50041301_1_dialog_content = "Ay... Estoy cansado.",
  ui_story_5004_50041301_2_dialog_content = "Si bien no hice mucho, todavía es agotador huir de la pelota...",
  ui_story_5004_50041301_3_dialog_content = "No pensé que sería tan intenso y es solo el primer día.",
  ui_story_5004_50041301_4_dialog_content = "Genevieve es poderosa, pero Smokey está en otro nivel.",
  ui_story_5004_50041301_5_dialog_content = "¿Qué pasa con esas chicas?",
  ui_story_5004_50041301_6_dialog_content = "Beryl y Raphaela se fueron a pescar después. Parecían haberlo pasado muy bien.",
  ui_story_5004_50041301_7_dialog_content = "Beryl se veía abatida, pero debería estar bien con Raphaela cerca.",
  ui_story_5004_50041301_8_dialog_content = "Oh, tengo que agradecerle a Vice por tomarlo por mí.",
  ui_story_5004_50041301_9_dialog_content = "Seguro aun estaría en cuidados intensivos si no fuera por ella.",
  ui_story_5004_50041301_10_dialog_content = "<color=#e8d9bb>Toc, toc.</color>",
  ui_story_5004_50041301_11_dialog_content = "¿Estás despierto, PlayerName?",
  ui_story_5004_50041301_12_dialog_content = "Ya voy.",
  ui_story_5004_50041301_13_dialog_content = "¿Qué está pasando, Carleen?",
  ui_story_5004_50041301_14_dialog_content = "Solo compruebo si te has entregado, PlayerName.",
  ui_story_5004_50041301_15_dialog_content = "No es normal que esté en la playa. No quiero estar encerrada toda la noche.",
  ui_story_5004_50041301_16_dialog_content = "¿Quieres dar un paseo conmigo?",
  ui_story_5004_50041301_17_dialog_content = "Si, ¡feliz de hacerlo!",
  ui_story_5004_50041301_19_dialog_content = "¡Bueno, vamos!",
  ui_story_5004_50041301_20_dialog_content = "Está bien.",
  ui_story_5004_50041301_21_dialog_content = "Aunque, se siente un poco incómodo.",
  ui_story_5004_50041301_22_dialog_content = "PlayerName.",
  ui_story_5004_50041301_23_dialog_content = "¿Qué? ¡Estoy Aquí!",
  ui_story_5004_50041301_24_dialog_content = "Acerca de Aviduz y Schummer... Siempre he querido mostrarte mi gratitud formalmente.",
  ui_story_5004_50041301_25_dialog_content = "Está bien, no es necesario.",
  ui_story_5004_50041301_26_dialog_content = "Tú y Vice también me han ayudado mucho.",
  ui_story_5004_50041301_27_dialog_content = "Sí. Recordándolo en una playa tan hermosa...",
  ui_story_5004_50041301_28_dialog_content = "Casi se siente como un sueño, ¿no crees?",
  ui_story_5004_50041301_29_dialog_content = "No estoy segura de que no esté soñando ahora.",
  ui_story_5004_50041301_30_dialog_content = "La primera vez que te vi, no podía creer que pasaras más de una década solo...",
  ui_story_5004_50041301_31_dialog_content = "Eres el primer Celestita que conozco hasta ese momento... Para mí es asombroso ver a alguien que podía ver el Sendero de la Luz.",
  ui_story_5004_50041301_32_dialog_content = "Has demostrado una y otra vez que eres un excelente líder.",
  ui_story_5004_50041301_33_dialog_content = "Es posible que no puedas luchar contra los Eclipsites directamente, pero nunca te echas atrás.",
  ui_story_5004_50041301_34_dialog_content = "...",
  ui_story_5004_50041301_35_dialog_content = "Incluso te pones en peligro por otras personas.",
  ui_story_5004_50041301_36_dialog_content = "Tu dedicación y abnegación para salvar a otros, incluso a riesgo de tu propia vida, es un testimonio de tu carácter extraordinario.",
  ui_story_5004_50041301_37_dialog_content = "El coraje que demuestras es más respetable que el de esos nobles que solo se preocupan por sí mismos en una crisis.",
  ui_story_5004_50041301_38_dialog_content = "...",
  ui_story_5004_50041301_39_dialog_content = "¿Estás escuchando, PlayerName?",
  ui_story_5004_50041301_40_dialog_content = "Ah, he dicho demasiado, ¿no?",
  ui_story_5004_50041301_41_dialog_content = "Escucho y asimilé todo lo que dijiste. Es bueno hablar contigo con esta brisa.",
  ui_story_5004_50041301_42_dialog_content = "Y todo a la vista...",
  ui_story_5004_50041301_43_dialog_content = "El mar, el cielo estrellado...",
  ui_story_5004_50041301_44_dialog_content = "Y...",
  ui_story_5004_50041301_45_dialog_content = "...",
  ui_story_5004_50041301_46_dialog_content = "Todo es muy lindo.",
  ui_story_5004_50041301_47_dialog_content = "...",
  ui_story_5004_50041301_48_dialog_content = ".",
  ui_story_5004_50041301_49_dialog_content = "(Puedo sentir el sutil cambio de humor...)",
  ui_story_5004_50041301_50_dialog_content = "¡Sí, claro! No verás esto en Lumopolis.",
  ui_story_5004_50041301_51_dialog_content = "El vasto cielo nocturno tiene un aire de magnificencia con las tranquilas olas chapoteando contra la arena.",
  ui_story_5004_50041301_52_dialog_content = "(Menos mal que Carleen se lo perdió...)",
  ui_story_5004_50041301_53_dialog_content = "El pescado debería tener buen sabor en este hermoso mar, ¿no crees?",
  ui_story_5004_50041301_54_dialog_content = "¿Deberíamos pescar y averiguarlo?",
  ui_story_5004_50041301_55_dialog_content = "Es una buena idea, pero nunca tomé clases de cocina.",
  ui_story_5004_50041301_56_dialog_content = "Podemos llevarnos el pescado al hotel y pedirle al chef extraño que nos lo cocine a la parrilla.",
  ui_story_5004_50041301_57_dialog_content = "O llevarlo a Lumopolis. Se de algunos restaurantes tranquilos y sabrosos.",
  ui_story_5004_50041301_58_dialog_content = "¡Genial! ¡De acuerdo!",
  ui_story_5004_50041301_59_dialog_content = "Pero probablemente no deberíamos hacerlo ahora. Es muy tarde y puede ser peligroso meterse en el agua...",
  ui_story_5004_50041301_60_dialog_content = "Y probablemente también estés cansada del juego de voleibol de hoy, Carleen.",
  ui_story_5004_50041301_61_dialog_content = "Cierto. La próxima entonces.",
  ui_story_5004_50041301_62_dialog_content = "¿Oh...?",
  ui_story_5004_50041301_63_dialog_content = "¿Qué pasa, PlayerName?",
  ui_story_5004_50041301_64_dialog_content = "Creo que la estatua de abajo simplemente brillaba.",
  ui_story_5004_50041301_65_dialog_content = "Yo no vi eso. ¿Quizás es fatiga de tu parte?",
  ui_story_5004_50041301_66_dialog_content = "¿O tal vez todavía tienes en mente el Super Hellstorm Spike de Smokey?",
  ui_story_5004_50041301_67_dialog_content = "¿Recuerdas cómo se llama?",
  ui_story_5004_50041301_68_dialog_content = "Podría estar viendo cosas.",
  ui_story_5004_50041301_69_dialog_content = "Regresemos.",
  ui_story_5004_50041301_70_dialog_content = "El descendiente Celestita... El poder del cristal... así como \"eso\" sigue funcionando...",
  ui_story_5004_50041301_71_dialog_content = "Un grupo de tontos Aurorians ofreciendo a Lumina...",
  ui_story_5004_50041301_72_dialog_content = "Además...",
  ui_story_5004_50041301_73_dialog_content = "Beryl.",
  ui_story_5004_50041301_74_dialog_content = "Es mi turno en el juego de ajedrez.",
  ui_story_5004_50041501_1_dialog_content = "<color=#e8d9bb>Hace unos días.</color>",
  ui_story_5004_50041501_2_dialog_content = "¡Diablos!",
  ui_story_5004_50041501_3_dialog_content = "<color=#e8d9bb>Smokey rompió la carta con ira y la tiró a un lado.</color>",
  ui_story_5004_50041501_4_dialog_content = "¿Ese chico me engañó?",
  ui_story_5004_50041501_5_dialog_content = "No me pegues. ¡Te pagaré lo que sea!",
  ui_story_5004_50041501_6_dialog_content = "¿No estabas tratando de chantajear a una chica hace unos segundos?",
  ui_story_5004_50041501_7_dialog_content = "¿Ahora qué? ¡Vamos, veamos a ese arrogante engreído tuyo de nuevo!",
  ui_story_5004_50041501_8_dialog_content = "¿Crees que diriges este lugar?",
  ui_story_5004_50041501_9_dialog_content = "<size=45>¿Crees que bromeo</size> cuando dije que no acosaré a ninguna mujer?",
  ui_story_5004_50041501_10_dialog_content = "Yo... ¡No soy local! Por favor, ten piedad y perdóname. ¡No volveré a causar ningún problema!",
  ui_story_5004_50041501_11_dialog_content = "¿No eres local? Bien, punto por originalidad.",
  ui_story_5004_50041501_12_dialog_content = "Así que te daré treinta segundos para que me digas de dónde eres, qué estás haciendo aquí y quién te envió.",
  ui_story_5004_50041501_13_dialog_content = "Si me dices lo que quiero escuchar, te dejaré ir.",
  ui_story_5004_50041501_14_dialog_content = "De lo contrario...",
  ui_story_5004_50041501_15_dialog_content = "Te romperé un dedo cada treinta segundos. ¿Entiendes?",
  ui_story_5004_50041501_16_dialog_content = "El primer dedo comienza en 30, 29...",
  ui_story_5004_50041501_17_dialog_content = "¡No, déjame ir! ¡Solo hago entregas!",
  ui_story_5004_50041501_18_dialog_content = "¡No soy mala persona! ¡No puedes culparme por esa chica que lleva tan poco!",
  ui_story_5004_50041501_19_dialog_content = "Solo hago un mandado. ¡Nadie me envió!",
  ui_story_5004_50041501_20_dialog_content = "10, 9, 8...",
  ui_story_5004_50041501_21_dialog_content = "¡Te he contado todo! ¿Qué más esperas de mí?",
  ui_story_5004_50041501_22_dialog_content = "Snap, crack.",
  ui_story_5004_50041501_23_dialog_content = "<size=45><anim type=Shake>¡Aww! ¡Mi mano!</anim></size>",
  ui_story_5004_50041501_24_dialog_content = "¡Estás loco! ¡Van dos dedos! ¡¿Qué sucede contigo?!",
  ui_story_5004_50041501_25_dialog_content = "¡Estás loco! ¡Lunático! Aww...",
  ui_story_5004_50041501_26_dialog_content = "Un dedo porque se acabó el tiempo, otro por mentir.",
  ui_story_5004_50041501_27_dialog_content = "Realmente... me enviaron solo para la entrega, maldita sea...",
  ui_story_5004_50041501_28_dialog_content = "Dámelo.",
  ui_story_5004_50041501_29_dialog_content = "¡De ninguna manera!",
  ui_story_5004_50041501_30_dialog_content = "¿Estás seguro? Es hora del tercer dedo... 5, 4...",
  ui_story_5004_50041501_31_dialog_content = "¡No puedo! ¡Me matarán!",
  ui_story_5004_50041501_32_dialog_content = "CERO.",
  ui_story_5004_50041501_33_dialog_content = "<size=45><anim type=Shake>¡Aghhh!</anim></size> Huff...",
  ui_story_5004_50041501_34_dialog_content = "¿Y crees que no lo haría?",
  ui_story_5004_50041501_35_dialog_content = "O mueres ahora o mueres más tarde, tú eliges.",
  ui_story_5004_50041501_36_dialog_content = "Ok, ok, ¡suéltame!",
  ui_story_5004_50041501_37_dialog_content = "¡Ten, todo tuyo, loco!",
  ui_story_5004_50041501_38_dialog_content = "¿Una carta? ¿Qué contiene?",
  ui_story_5004_50041501_39_dialog_content = "Te sugiero que me lo devuelvas. Es para alguien grande. ¡No funcionará para ninguno de nosotros si lo tienes!",
  ui_story_5004_50041501_40_dialog_content = "Demasiado tarde.",
  ui_story_5004_50041501_41_dialog_content = "Ahora tengo curiosidad por ver qué es.",
  ui_story_5004_50041501_42_dialog_content = "¿Qué es esta Costa Celestial?",
  ui_story_5004_50041501_43_dialog_content = "¿Es un mapa del tesoro?",
  ui_story_5004_50041501_44_dialog_content = "¡¿Lo leíste?! ¡Estamos muertos!",
  ui_story_5004_50041501_45_dialog_content = "<size=45>¡Soy yo quien hace las preguntas!</size>",
  ui_story_5004_50041501_46_dialog_content = "Yo tampoco lo sé. ¡Lo que sé es que son muy peligrosos!",
  ui_story_5004_50041501_47_dialog_content = "¡Parecen planear algún tipo de ritual para convocar la perdición sobre el mundo!",
  ui_story_5004_50041501_48_dialog_content = "¡Devuélvemelo, no quiero problemas!",
  ui_story_5004_50041501_49_dialog_content = "Hmm, no te golpeé en la cabeza, ¿verdad?",
  ui_story_5004_50041501_50_dialog_content = "¿Qué tonterías dices ahora?",
  ui_story_5004_50041501_51_dialog_content = "Cuanto más dices, más quiero involucrarme.",
  ui_story_5004_50041501_52_dialog_content = "¡He decidido verlo por mí mismo!",
  ui_story_5004_50041501_53_dialog_content = "<color=#e8d9bb>Como decía la carta...</color>",
  ui_story_5004_50041501_54_dialog_content = "<color=#e8d9bb>Lo que busco son tres muros de lamento</color>",
  ui_story_5004_50041501_55_dialog_content = "<color=#e8d9bb>Lo que busco es renacer de las cenizas</color>",
  ui_story_5004_50041501_56_dialog_content = "<color=#e8d9bb>Lluvia de sangre cae al amanecer</color>",
  ui_story_5004_50041501_57_dialog_content = "<color=#e8d9bb>Pintar la puesta de sol con lágrimas</color>",
  ui_story_5004_50041501_58_dialog_content = "<color=#e8d9bb>Hasta el momento del juicio, el fin de los días</color>",
  ui_story_5004_50041501_59_dialog_content = "<color=#e8d9bb>Cuando el Monarca despierte</color>",
  ui_story_5004_50041501_60_dialog_content = "¿Qué es esto? ¿Un acertijo?",
  ui_story_5004_50041501_61_dialog_content = "No me digas que vine aquí por nada...",
  ui_story_5004_50041501_62_dialog_content = "<color=#e8d9bb>Toc, toc.</color>",
  ui_story_5004_50041501_63_dialog_content = "Pasa adelante...",
  ui_story_5004_50041501_64_dialog_content = "Hola. Señorita Smokey Manticore de Umbraton, ¿supongo?",
  ui_story_5004_50041501_65_dialog_content = "¿Me conoces?",
  ui_story_5004_50041501_66_dialog_content = "Por supuesto. Sé quién eres, entiendo por qué estás aquí y que la carta que tienes en tus manos no te pertenece.",
  ui_story_5004_50041501_67_dialog_content = "Dime que quieres.",
  ui_story_5004_50041501_68_dialog_content = "¡Hahaha!",
  ui_story_5004_50041501_69_dialog_content = "¿.?",
  ui_story_5004_50041501_70_dialog_content = "Disculpa, pero eso fue muy divertido, ¿no?",
  ui_story_5004_50041501_71_dialog_content = "¿Por qué querría algo? Solo estoy aquí para invitarte al Soberano del Océano como anfitrión.",
  ui_story_5004_50041501_72_dialog_content = "¿Eso es todo?",
  ui_story_5004_50041501_73_dialog_content = "Es todo.",
  ui_story_5004_50041501_74_dialog_content = "Eres de True Order. No confío en ustedes.",
  ui_story_5004_50041501_75_dialog_content = "Incluso si estoy con True Order, todavía puedo ser anfitrión, ¿no?",
  ui_story_5004_50041501_76_dialog_content = "Además, se necesita materialismo para perseguir La Verdad, y este trabajo paga bien.",
  ui_story_5004_50041501_77_dialog_content = "Entonces, ¿te unirás? Tal vez el premio del ganador incluya exactamente lo que buscas.",
  ui_story_5004_50041501_78_dialog_content = "Aun si pierdes...",
  ui_story_5004_50041501_79_dialog_content = "Alto ahí. No perderé y no me interesan las consecuencias de perder.",
  ui_story_5004_50041501_80_dialog_content = "¿Esa persona de los mandados es de tu gente?",
  ui_story_5004_50041501_81_dialog_content = "¿Cómo iba a saber eso?",
  ui_story_5004_50041501_82_dialog_content = "Ya estoy aquí, así que bien podrías aclararlo.",
  ui_story_5004_50041501_83_dialog_content = "Quiero ver lo que intentas ponerme debajo de la nariz.",
  ui_story_5004_50041601_1_dialog_content = "¿Dices que la condición de Beryl se debe a Lumina inestable?",
  ui_story_5004_50041601_2_dialog_content = "Sí, he estado en contacto con Beretta los últimos días y encontró casos similares.",
  ui_story_5004_50041601_3_dialog_content = "Luego está el archivo de los Gautiers...",
  ui_story_5004_50041601_4_dialog_content = "Pero está guardado y solo al descubierto para el señor de la ciudad y un puñado de otros.",
  ui_story_5004_50041601_5_dialog_content = "¿Beryl es un Gautier?",
  ui_story_5004_50041601_6_dialog_content = "¡Correcto! Habló de su familia cuando charlábamos por la noche y mencionó a otra familia...",
  ui_story_5004_50041601_7_dialog_content = "Pirro-algo... No recuerdo ahora.",
  ui_story_5004_50041601_8_dialog_content = "Está bien. Parece que se están conectando muy bien.",
  ui_story_5004_50041601_9_dialog_content = "Por supuesto. ¡Las chicas tendemos a hablar de todo! ¡Y Beryl es más habladora de lo que piensas!",
  ui_story_5004_50041601_10_dialog_content = "Ya veo. Bueno, cuídala bien.",
  ui_story_5004_50041601_11_dialog_content = "¡No hay problema! Hablaré con Carleen y veré qué podemos hacer. ¡Te avisaré si surge algo!",
  ui_story_5004_50041601_12_dialog_content = "¡Ahora vuelvo a Beryl! ¡Nos vemos en el juego!",
  ui_story_5004_50041601_13_dialog_content = "Ok, ten cuidado.",
  ui_story_5004_50041601_14_dialog_content = "¡Uh!",
  ui_story_5004_50041601_15_dialog_content = "¿Estás bien?",
  ui_story_5004_50041601_16_dialog_content = "Estoy bien. ¡Perdóname!",
  ui_story_5004_50041601_17_dialog_content = "¿Smokey?",
  ui_story_5004_50041601_18_dialog_content = "Eres PlayerName, ¿verdad? Quiero presentarme formalmente.",
  ui_story_5004_50041601_19_dialog_content = "Soy Smokey de Umbraton.",
  ui_story_5004_50041601_20_dialog_content = "...",
  ui_story_5004_50041601_21_dialog_content = ".",
  ui_story_5004_50041601_22_dialog_content = "¿Es así?",
  ui_story_5004_50041601_23_dialog_content = "Si.",
  ui_story_5004_50041601_24_dialog_content = "Y, Smokey, ¿qué te trae por aquí?",
  ui_story_5004_50041601_25_dialog_content = "Como somos compañeros de equipo, pensé que debería conocerte.",
  ui_story_5004_50041601_26_dialog_content = "A juzgar por el último juego, eventualmente podríamos tener problemas si seguimos confiando solo en mí.",
  ui_story_5004_50041601_27_dialog_content = "(¿Estás seguro?)",
  ui_story_5004_50041601_28_dialog_content = "Así que pensé que debo empezar a llevarme bien con el equipo.",
  ui_story_5004_50041601_29_dialog_content = "Bueno, hagámoslo. ¡Nos vemos!",
  ui_story_5004_50041601_30_dialog_content = "Espera.",
  ui_story_5004_50041601_31_dialog_content = "¿Si?",
  ui_story_5004_50041601_32_dialog_content = "Perdóname por ser franco, pero ¿qué está pasando entre tú y Genevieve?",
  ui_story_5004_50041601_33_dialog_content = "Sabía que me ibas a preguntar eso.",
  ui_story_5004_50041601_34_dialog_content = "Dudo que encuentres mi respuesta satisfactoria.",
  ui_story_5004_50041601_35_dialog_content = "Ambos nacimos en Petyaburg. Soy una Manticore, ella una Vronsky.",
  ui_story_5004_50041601_36_dialog_content = "Cómo lo digo... Las dos familias son rivales, aunque nos llevábamos bastante bien cuando éramos pequeños.",
  ui_story_5004_50041601_37_dialog_content = "Ella era bastante linda, siguiéndome en ese entonces, mucho mejor de lo que es ahora.",
  ui_story_5004_50041601_38_dialog_content = "Supongo que porque era joven, rebelde y un buscador de emociones.",
  ui_story_5004_50041601_39_dialog_content = "Presumí un poco en una de las pruebas de Genevieve.",
  ui_story_5004_50041601_X39_dialog_content = "Llamó la atención de los jueces, y le costó la oportunidad de convertirse en noble de Lumopolis.",
  ui_story_5004_50041601_40_dialog_content = "Eso la avergonzó a ella y a su familia.",
  ui_story_5004_50041601_41_dialog_content = "Solo estaba buscando algo de emoción. ¿Quién hubiera sabido que serían tan sensibles?",
  ui_story_5004_50041601_42_dialog_content = "Por eso me escapé de casa. Los nobles no son más que problemas.",
  ui_story_5004_50041601_43_dialog_content = "Ok...",
  ui_story_5004_50041601_44_dialog_content = "Debo irme. Hagámoslo mejor en el partido de la tarde.",
  ui_story_5004_50041701_1_dialog_content = "Wow...",
  ui_story_5004_50041701_2_dialog_content = "¿Nervioso, PlayerName?",
  ui_story_5004_50041701_3_dialog_content = "Un poquito...",
  ui_story_5004_50041701_4_dialog_content = "No lo estés. El comandante Hiiro me enseñó que <color=#FFB400>cuando hay una forma, hay voluntad</color>.",
  ui_story_5004_50041701_5_dialog_content = "Creo que estás pensando en <color=#FFB400>cuando hay voluntad, hay una forma</color>.",
  ui_story_5004_50041701_6_dialog_content = "Correcto, correcto. Me pregunto si eso significa que el Comandante Hiiro se perdió una vez en Rediesel Wrench antes...",
  ui_story_5004_50041701_7_dialog_content = "(¡Hiiro te haría escribirlo 100 veces si ella escuchara eso!)",
  ui_story_5004_50041701_8_dialog_content = "Traigo el Capullo de luna hoy. Déjame el trabajo pesado a mí.",
  ui_story_5004_50041701_9_dialog_content = "¡Entonces dispararé misiles desde fuera de los límites para respaldarlos!",
  ui_story_5004_50041701_10_dialog_content = "¡No, no! Puede que sea una batalla, pero debemos seguir las reglas básicas.",
  ui_story_5004_50041701_11_dialog_content = "Guarda los misiles para Eclipsites, Raphaela.",
  ui_story_5004_50041701_12_dialog_content = "Eres un ángel de Lumopolis, al final.",
  ui_story_5004_50041701_13_dialog_content = "Cierto. Debo guardarlos para la protección de Beryl.",
  ui_story_5004_50041701_14_dialog_content = "¡Te animaré con Beryl!",
  ui_story_5004_50041701_15_dialog_content = "Vice, no creo que un arco sea adecuado para la posición en la que juegas.",
  ui_story_5004_50041701_16_dialog_content = "¡Si, por eso le pedí a Beryl que agregara hojas de cristal para el arco!",
  ui_story_5004_50041701_17_dialog_content = "Lo intentamos, pero no hicimos nada adecuado hasta esta mañana...",
  ui_story_5004_50041701_18_dialog_content = "Sería genial si fuera útil...",
  ui_story_5004_50041701_19_dialog_content = "Parece ser resistente y afilado. Puedo decir que Beryl se ha esforzado mucho en esto.",
  ui_story_5004_50041701_20_dialog_content = "(Beryl es una niña genial...)",
  ui_story_5004_50041701_21_dialog_content = "Gracias. ¡Salgamos y ganemos!",
  ui_story_5004_50041701_22_dialog_content = "¡Sí! ¡Muy confiable y enérgica como siempre, Vice!",
  ui_story_5004_50041701_23_dialog_content = "(¿Pero estás seguro de que quieres usar espadas cuando eres arquero?)",
  ui_story_5004_50041701_24_dialog_content = "Probab. no debería convertirse en una guerra, ya que es solo ajedrez.",
  ui_story_5004_50041701_25_dialog_content = "Genial si ese es el caso, pero ni Smokey ni Genevieve se rinden fácilmente.",
  ui_story_5004_50041701_26_dialog_content = "Debemos estar preparados para lo que sea.",
  ui_story_5004_50041701_27_dialog_content = "Ejem, veo que todos están aquí.",
  ui_story_5004_50041701_28_dialog_content = "Por favor, detente por un momento.",
  ui_story_5004_50041701_29_dialog_content = "Se dice que aquí se originó el aclamado juego de ajedrez.",
  ui_story_5004_50041701_30_dialog_content = "Una vez, un monarca sabio y compasivo deseó que sus súbditos pudieran ser inteligentes.",
  ui_story_5004_50041701_31_dialog_content = "E inventó el juego para perfeccionar su pensamiento crítico y su mente táctica.",
  ui_story_5004_50041701_32_dialog_content = "De eso derivó un ejército formidable que infundió miedo incluso en los Eclipsites, protegiendo al reino de cualquier daño.",
  ui_story_5004_50041701_33_dialog_content = "Pero eso es el pasado.",
  ui_story_5004_50041701_34_dialog_content = "En memoria de ese monarca, comenzaremos el segundo concurso, un juego de ajedrez, ¡versión en vivo!",
  ui_story_5004_50041701_35_dialog_content = "¡Ahora anuncio que el juego de ajedrez de ingenio comienza ahora!",
  ui_story_5004_50041701_36_dialog_content = "¡PlayerName!",
  ui_story_5004_50041701_37_dialog_content = "¡Ten!",
  ui_story_5004_50041701_38_dialog_content = "Está alerta y toma el mando. Haremos todo por conseguir la victoria.",
  ui_story_5004_50041701_39_dialog_content = "(Enfócate... Puedo hacerlo. He jugado algunas partidas de ajedrez con Barton.)",
  ui_story_5004_50041701_40_dialog_content = "(Déjame recordar el momento en que jugamos...)",
  ui_story_5004_50041701_41_dialog_content = "Ganamos porque <color=#FFB400>los generales nos allanaron el camino</color>.",
  ui_story_5004_50041701_42_dialog_content = "¡Lo tengo!",
  ui_story_5004_50041701_43_dialog_content = "Estarás orgulloso, Barton... ¡Soy el general y allanaré el camino!",
  ui_story_5004_50041701_44_dialog_content = "¡Mi turno!",
  ui_story_5004_50041701_45_dialog_content = "¡El Rey mueve uno!",
  ui_story_5004_50041701_46_dialog_content = "...",
  ui_story_5004_50041701_47_dialog_content = "Uh, PlayerName, no sé cómo jugar al ajedrez...",
  ui_story_5004_50041701_48_dialog_content = "Pero no creo que debas seguir adelante a menos que quieras ir a cuestas.",
  ui_story_5004_50041701_49_dialog_content = "¡Je!",
  ui_story_5004_50041701_50_dialog_content = "Sé lo que eres y sé que tu gente son comandantes talentosos, Celestita.",
  ui_story_5004_50041701_51_dialog_content = "¡No creo que hayas captado los matices de un juego como el ajedrez!",
  ui_story_5004_50041701_52_dialog_content = "Para emparejar a los Aurorians que tienes, ¡he contratado específicamente a los <color=#FFB400>guerreros</color> más poderosos!",
  ui_story_5004_50041701_53_dialog_content = "Vaya, habla demasiado. Pensé que habíamos acordado no delatarnos.",
  ui_story_5004_50041701_54_dialog_content = "Hola, jefe, esta es una clara violación del contrato, como se indica en la Sección III, Cláusula 9.",
  ui_story_5004_50041701_55_dialog_content = "Es un pago adicional del 135% según el acuerdo.",
  ui_story_5004_50041701_56_dialog_content = "¡Cállate, te pagaré lo que te mereces! ¡Consíguelos!",
  ui_story_5004_50041701_57_dialog_content = "PlayerName, enlázate conmigo. Yo te guiaré a través de esto.",
  ui_story_5004_50041701_58_dialog_content = "¡Ok gracias!",
  ui_story_5004_50041701_59_dialog_content = "¡Toma esto!",
  ui_story_5004_50041701_60_dialog_content = "¡Wow, su técnica con la espada es casi tan hábil como la del comandante Hiiro!",
  ui_story_5004_50041701_61_dialog_content = "Y el estilo de pelea... ¿Eres tú...?",
  ui_story_5004_50041701_62_dialog_content = "Supongo que no hay necesidad de ocultar mi identidad ahora.",
  ui_story_5004_50041701_63_dialog_content = "¡¿Sr. Taki?!",
  ui_story_5004_50041701_64_dialog_content = "¿Taki?",
  ui_story_5004_50041701_65_dialog_content = "¿Qué estás haciendo acá?",
  ui_story_5004_50041701_66_dialog_content = "Lo siento, eso es lo que hace Trabajos Ocasionales: ¡aceptar trabajo remunerado que no sea inmoral!",
  ui_story_5004_50041701_67_dialog_content = "¡Y no seré fácil ya que es solo un juego!",
  ui_story_5004_50041701_68_dialog_content = "Te sugiero que te rindas ahora, PlayerName. ¡No quiero lastimar a alguien desarmada!",
  ui_story_5004_50041701_69_dialog_content = "Sr. Taki, ¡va a ser difícil para mi negocio si estás expuesto!",
  ui_story_5004_50041701_70_dialog_content = "¡Esa es la oportunidad!",
  ui_story_5004_50041701_71_dialog_content = "¡Ay!",
  ui_story_5004_50041701_72_dialog_content = "No tan fuerte, Carleen. ¡El coco estallará pronto!",
  ui_story_5004_50041701_72X1_dialog_content = "¿Qué? ¡Esos son sombreros, no cocos reales!",
  ui_story_5004_50041701_72X2_dialog_content = "Oh sí... Maldita sea, eso realmente parecía un coco.",
  ui_story_5004_50041701_73_dialog_content = "Sabía que eras tú, Jomu.",
  ui_story_5004_50041701_74_dialog_content = "Tengo mis razones... ¡Puedo explicarlo! ¡Acepté el trabajo <color=#FFB400>por ti</color>, jefe!",
  ui_story_5004_50041701_75_dialog_content = "¿Ah? ¿Para mí?",
  ui_story_5004_50041701_76_dialog_content = "¡Sí! Si obtengo el bono de Genevieve, puedo expandir mi negocio.",
  ui_story_5004_50041701_77_dialog_content = "Quizás incluso puedas comprarme cosas como <color=#FFB400>Lumocrystal</color> con Nightium en el futuro.",
  ui_story_5004_50041701_78_dialog_content = "Te daré ofertas especiales y una <color=#FFB400>linda cajita</color> de edición limitada mensual.",
  ui_story_5004_50041701_79_dialog_content = "PlayerName, ¡los otros que llevan <color=#FFFFFF>sombreros</color> también lucen sospechosos!",
  ui_story_5004_50041701_80_dialog_content = "¡Solo estáfalos!",
  ui_story_5004_50041701_81_dialog_content = "¡Exactamente! ¡Ustedes pueden, Vice y Carleen!",
  ui_story_5004_50041701_82_dialog_content = "¡Mi sierra no tiene diesel! ¡Adiós!",
  ui_story_5004_50041701_83_dialog_content = "Renuncio. ¡Nos vemos!",
  ui_story_5004_50041701_84_dialog_content = "¡Chirrido!",
  ui_story_5004_50041701_85_dialog_content = "Tsk, lo sabía, un montón de tipos poco fiables.",
  ui_story_5004_50041701_86_dialog_content = "Ahh, parece que la competencia está estancada, ¿no?",
  ui_story_5004_50041701_87_dialog_content = "Tenemos desertores en un lado, pero habrá un jaque mate en el otro lado.",
  ui_story_5004_50041701_88_dialog_content = "¡Oye, ahora muéveme a mí!",
  ui_story_5004_50041701_89_dialog_content = "Ya sea un ascenso o un jaque mate, conseguiré a Genevieve si me acerco a ella.",
  ui_story_5004_50041701_90_dialog_content = "No lo creo. ¡Carleen debe volver para defender a Vice y reagruparnos!",
  ui_story_5004_50041701_91_dialog_content = "Se nos acabó el tiempo. Su moral está baja, ¡así que aprovechemos esta oportunidad! No hay tiempo para que salves a tu pequeña novia.",
  ui_story_5004_50041701_92_dialog_content = "¿Qué? Ella no es...",
  ui_story_5004_50041701_93_dialog_content = "¡Escúchame y ganaremos! ¡Apúrate!",
  ui_story_5004_50041701_94_dialog_content = "Está bien.",
  ui_story_5004_50041701_95_dialog_content = "¡Genevieve!",
  ui_story_5004_50041701_96_dialog_content = "¡Vamos, Smokey!",
  ui_story_5004_50041701_97_dialog_content = "¡Ja!",
  ui_story_5004_50041701_98_dialog_content = "¡¿Comenzando con el movimiento más poderoso?!",
  ui_story_5004_50041701_99_dialog_content = "¡Je!",
  ui_story_5004_50041701_100_dialog_content = "¡Están emparejados! ¿Cómo? ¿Genevieve tiene habilidades de lucha tan finas?",
  ui_story_5004_50041701_101_dialog_content = "Me descuidé la última vez. ¡No te engañes pensando que siempre podrás vencerme!",
  ui_story_5004_50041701_102_dialog_content = "Estás mejor ahora, ¡pero nunca pienses en pasarme!",
  ui_story_5004_50041701_103_dialog_content = "Esto no puede continuar. ¡Están igualados y el lugar se va a quemar!",
  ui_story_5004_50041701_104_dialog_content = "Parece que tengo que intervenir, ¿no?",
  ui_story_5004_50041701_105_dialog_content = "¡Vamos a animar las cosas con nuevas reglas!",
  ui_story_5004_50041701_106_dialog_content = "¡Juego alternativo!",
  ui_story_5004_50041701_107_dialog_content = "Hay un pedazo de Crystal King en algún lugar del campo. Lo escondí antes del juego.",
  ui_story_5004_50041701_108_dialog_content = "La regla es muy sencilla. ¡Cual sea el rey que lo encuentre primero, ese bando gana!",
  ui_story_5004_50041701_109_dialog_content = "Supongo que así será... ¡Adelante! ¡Mis fans!",
  ui_story_5004_50041701_110_dialog_content = "¡Ataque! ¡Ataque!",
  ui_story_5004_50041701_111_dialog_content = "¡Por Lady Genevieve!",
  ui_story_5004_50041701_112_dialog_content = "Me preguntaba cuándo aparecerían.",
  ui_story_5004_50041701_113_dialog_content = "Espera, ¿cuál es el problema con las pistolas de agua? ¿por qué se unen los fans al juego?",
  ui_story_5004_50041701_114_dialog_content = "Realmente deberías leer el manual. Te envié uno nuevo, ¿no?",
  ui_story_5004_50041701_115_dialog_content = "¡El nuevo manual es el doble de grueso que el anterior!",
  ui_story_5004_50041701_116_dialog_content = "El partido anterior fue sensacional, muchos nuevos patrocinadores se inscribieron.",
  ui_story_5004_50041701_117_dialog_content = "Debido a que Genevieve aguantó mucho tiempo, este juego se considera un empate.",
  ui_story_5004_50041701_118_dialog_content = "¡Estamos en el juego alternativo, en el que solo se pueden usar pistolas de agua!",
  ui_story_5004_50041701_119_dialog_content = "Igual, PlayerName, no irás muy lejos dependiendo de que otros te lean el Manual de batalla...",
  ui_story_5004_50041701_120_dialog_content = "¡No puedo comprender como de una competencia seria paso a un juego de humor de verano!",
  ui_story_5004_50041701_121_dialog_content = "Ni siquiera trajimos pistolas de agua ...",
  ui_story_5004_50041701_122_dialog_content = "Oye, ¿qué son esos en tus manos?",
  ui_story_5004_50041701_123_dialog_content = "¡Cúbrete y contraataca, Vice!",
  ui_story_5004_50041701_124_dialog_content = "¡Entendido! ¡Cúbrete también, PlayerName!",
  ui_story_5004_50041701_125_dialog_content = "¡No tengo armas!",
  ui_story_5004_50041701_126_dialog_content = "¡Atrapa, PlayerName!",
  ui_story_5004_50041701_127_dialog_content = "¡Gracias, Beryl!",
  ui_story_5004_50041701_128_dialog_content = "¡Buen intento!",
  ui_story_5004_50041701_129_dialog_content = "¡Uh!",
  ui_story_5004_50041701_130_dialog_content = "¡Piensa en algo, Smokey!",
  ui_story_5004_50041701_131_dialog_content = "¡Creo que es hora de mostrarte lo que tengo!",
  ui_story_5004_50041701_132_dialog_content = "¡¿De dónde sacaste estas <color=#FFB400>pistolas de agua súper pesadas</color>?!",
  ui_story_5004_50041701_133_dialog_content = "¡No creas que puedes ganar con solo números!",
  ui_story_5004_50041701_134_dialog_content = "¡Diablos! ¡Protege a Lady Genevieve a toda costa!",
  ui_story_5004_50041701_135_dialog_content = "No puedo seguir, Capitán...",
  ui_story_5004_50041701_136_dialog_content = "¡Argh!",
  ui_story_5004_50041701_136X1_dialog_content = "¿Te atreves a apuntarle a mis fans?",
  ui_story_5004_50041701_136X2_dialog_content = "¡No te mostraré piedad!",
  ui_story_5004_50041701_136X3_dialog_content = "¡Oh, no puedo ver!",
  ui_story_5004_50041701_136X4_dialog_content = "Retrocede, Vice, te cubriré.",
  ui_story_5004_50041701_136X5_dialog_content = "¡Te mostraré el poder de mi Rose Hunter!",
  ui_story_5004_50041701_136X6_dialog_content = "¡Hey!",
  ui_story_5004_50041701_136X7_dialog_content = "Oh, yo tampoco puedo ver.",
  ui_story_5004_50041701_136X8_dialog_content = "Puedes hacerlo, Carleen. Esto no está bajo el mar.",
  ui_story_5004_50041701_136X9_dialog_content = "¿Son ustedes dos usuarios Luminatics de agua? ¿Cómo sucumbiste así de fácil a las pistolas de agua?",
  ui_story_5004_50041701_136X10_dialog_content = "¡Jajaja! ¡Ríndete a menos que quieras empaparte!",
  ui_story_5004_50041701_136X11_dialog_content = "¡Eres muy molesto!",
  ui_story_5004_50041701_136X12_dialog_content = "¿Smokey? Sabía que mis fans no podrían detenerte por mucho.",
  ui_story_5004_50041701_136X13_dialog_content = "¡Todos, apunten a Smokey mientras yo me ocupo de estos dos!",
  ui_story_5004_50041701_138_dialog_content = "¡Sí, mi sra.!",
  ui_story_5004_50041701_139_dialog_content = "¡Hut, hut, hut!",
  ui_story_5004_50041701_140_dialog_content = "¡Tsk, no puedo apuntar con toda esta agua!",
  ui_story_5004_50041701_141_dialog_content = "¡Neutralizaron a Smokey! ¡Haz algo, Brock!",
  ui_story_5004_50041701_142_dialog_content = "¿Qué puedo hacer? Ni siquiera leíste las reglas, ¿por qué lo haría yo?",
  ui_story_5004_50041701_143_dialog_content = "No estoy nada listo. ¿Quieres que les dé un puñetazo?",
  ui_story_5004_50041701_144_dialog_content = "¡Brock, PlayerName! ¿Ves lo que encontré en mi bolsillo?",
  ui_story_5004_50041701_145_dialog_content = "¡Una <color=#FFB400>carpa exterior</color> impermeable! ¿Quieren refugiarse?",
  ui_story_5004_50041701_146_dialog_content = "¡Nadie quiere estar en una carpa contigo!",
  ui_story_5004_50041701_147_dialog_content = "¿Pero no es reconfortante escuchar el sonido del agua salpicando la tienda?",
  ui_story_5004_50041701_148_dialog_content = "Tengo una <color=#FFB400>silla para exteriores</color>. ¿Quieres sentarte?",
  ui_story_5004_50041701_149_dialog_content = "¡No!",
  ui_story_5004_50041701_150_dialog_content = "¡Oigan, chicos, dejen de acampar allí!",
  ui_story_5004_50041701_151_dialog_content = "Eres Brock, ¿verdad?",
  ui_story_5004_50041701_152_dialog_content = "Sí. ¿Qué quieres?",
  ui_story_5004_50041701_153_dialog_content = "¡Crearé una apertura y tirarás PlayerName al medio para desenterrar esa pieza!",
  ui_story_5004_50041701_154_dialog_content = "¿¿¿QUÉ???",
  ui_story_5004_50041701_155_dialog_content = "¿Por qué debería escucharte?",
  ui_story_5004_50041701_156_dialog_content = "¿Ni eso puedes hacer? ¡Entonces entra en esa tonta carpa y escóndete!",
  ui_story_5004_50041701_157_dialog_content = "Tú... ¡Bien, esto podría doler un poco, PlayerName!",
  ui_story_5004_50041701_158_dialog_content = "¡Vaya, tiene que haber otra manera!",
  ui_story_5004_50041701_159_dialog_content = "3... 2...",
  ui_story_5004_50041701_160_dialog_content = "¡Bájame y pensemos en esto! ¡Brock!",
  ui_story_5004_50041701_161_dialog_content = "¡1!",
  ui_story_5004_50041701_162_dialog_content = "¡Espero tengas buena puntería!",
  ui_story_5004_50041701_163_dialog_content = "...",
  ui_story_5004_50041701_164_dialog_content = ".",
  ui_story_5004_50041701_165_dialog_content = "PlayerName.",
  ui_story_5004_50041701_166_dialog_content = "¡Despierta!",
  ui_story_5004_50041701_167_dialog_content = "¿Mamá?",
  ui_story_5004_50041701_168_dialog_content = "Despierta, PlayerName.",
  ui_story_5004_50041701_169_dialog_content = "¡¿Brock?!",
  ui_story_5004_50041701_170_dialog_content = "Ganamos. Brock te lanzó a través del escudo de agua de los fans. Tu cabeza golpeó el suelo e hizo un agujero, la pieza estaba justo debajo de ti, así que... la encontraste, ganamos.",
  ui_story_5004_50041701_171_dialog_content = "Quedaste inconsciente de inmediato, pero los fans de Genevieve estaban frustrados. Te dispararon antes que Genevieve pudiera ordenarles que se detuvieran.",
  ui_story_5004_50041701_172_dialog_content = "Lo siento, estabas a punto de ahogarte, solo Brock tiene entrenamiento en RCP.",
  ui_story_5004_50041701_173_dialog_content = "Está bien. ¿Puedo descansar un rato?",
  ui_story_5004_50041901_1_dialog_content = "...",
  ui_story_5004_50041901_2_dialog_content = "Genevieve.",
  ui_story_5004_50041901_3_dialog_content = "La responsabilidad de revivir el nombre de Vronsky está sobre sus hombros.",
  ui_story_5004_50041901_4_dialog_content = "...",
  ui_story_5004_50041901_5_dialog_content = "Debes someterte a un entrenamiento riguroso, a pesar de que ahora eres un niño.",
  ui_story_5004_50041901_6_dialog_content = "Todo es por tu propio bien.",
  ui_story_5004_50041901_7_dialog_content = "Sí, padre, madre, lo entiendo.",
  ui_story_5004_50041901_8_dialog_content = "Este es su mentor de Luminatics y etiqueta. Ella era una noble prominente en Lumopolis.",
  ui_story_5004_50041901_9_dialog_content = "Debes seguir a tu mentor y estudiar mucho para la familia Vronsky.",
  ui_story_5004_50041901_10_dialog_content = "Sí, entiendo.",
  ui_story_5004_50041901_11_dialog_content = "Deberías poder superar a esa chica Mantícora.",
  ui_story_5004_50041901_12_dialog_content = "¿Genevieve? ¿Genevieve?",
  ui_story_5004_50041901_13_dialog_content = "Disculpa, señora.",
  ui_story_5004_50041901_14_dialog_content = "No es propio de ti estar distraído.",
  ui_story_5004_50041901_15_dialog_content = "Me quedé despierto hasta tarde anoche terminando la tarea que me diste.",
  ui_story_5004_50041901_16_dialog_content = "La tarea fue para toda la semana. No tienes que exagerar con esto.",
  ui_story_5004_50041901_17_dialog_content = "...",
  ui_story_5004_50041901_18_dialog_content = "¿Qué quieres ser de mayor, Genevieve?",
  ui_story_5004_50041901_19_dialog_content = "¿Alcanzar honor y gloria para la familia?",
  ui_story_5004_50041901_20_dialog_content = "Te pregunto qué te gustaría hacer a ti.",
  ui_story_5004_50041901_21_dialog_content = "No entiendo. No estoy seguro. Quizás nunca lo pensé.",
  ui_story_5004_50041901_22_dialog_content = "Seguro. No hablemos de esto.",
  ui_story_5004_50041901_23_dialog_content = "Fuiste a ver a esa chica Mantícora la semana pasada, ¿verdad, Genevieve?",
  ui_story_5004_50041901_24_dialog_content = "¿Como lo descubriste?",
  ui_story_5004_50041901_25_dialog_content = "Todo está bien. No se lo diré a nadie.",
  ui_story_5004_50041901_26_dialog_content = "Gracias.",
  ui_story_5004_50041901_27_dialog_content = "Pero por qué tu...",
  ui_story_5004_50041901_28_dialog_content = "No importa, no debería hacer preguntas como esa.",
  ui_story_5004_50041901_29_dialog_content = "...",
  ui_story_5004_50041901_30_dialog_content = "Pero Genevieve, quizás no deberías estar obsesionada con ganar la gloria para tu familia.",
  ui_story_5004_50041901_31_dialog_content = "¿Por qué no?",
  ui_story_5004_50041901_32_dialog_content = "¿Sabes por qué ERA un noble prominente?",
  ui_story_5004_50041901_33_dialog_content = "Gracias por todo lo que le ha enseñado a lo largo de los años.",
  ui_story_5004_50041901_34_dialog_content = "Genevieve es una chica talentosa y trabajadora también.",
  ui_story_5004_50041901_35_dialog_content = "Se ha vuelto mucho más competente en magia ritual que muchos nobles.",
  ui_story_5004_50041901_36_dialog_content = "Y esa es la razón por la que no me queda nada que enseñarle.",
  ui_story_5004_50041901_37_dialog_content = "¿A dónde va, señora?",
  ui_story_5004_50041901_38_dialog_content = "Para citarte, no lo sé. Quizás para buscar algo, quizás alguien.",
  ui_story_5004_50041901_39_dialog_content = "Quién sabe, el viaje en sí podría valer la pena.",
  ui_story_5004_50041901_40_dialog_content = "Adiós, Genevieve.",
  ui_story_5004_50041901_41_dialog_content = "¿Qué, los Eclipsites se están acercando?",
  ui_story_5004_50041901_42_dialog_content = "No tenemos suficiente para defender Petyaburg. Debemos pedir ayuda a Lumopolis.",
  ui_story_5004_50041901_43_dialog_content = "Los Salars de Lumopolis han acordado ayudar, pero con una condición ...",
  ui_story_5004_50041901_44_dialog_content = "Quieren examinar la magia ritual de nuestros hijos y adoptarla como su línea familiar si es apropiado.",
  ui_story_5004_50041901_45_dialog_content = "No es malo si tenemos una conexión firme con una familia tan poderosa. Solo nos beneficiará a los Vronskys.",
  ui_story_5004_50041901_46_dialog_content = "Genevieve.",
  ui_story_5004_50041901_47_dialog_content = "Entiendo, padre.",
  ui_story_5004_50041901_48_dialog_content = "De hecho, eres poderosa, Genevieve.",
  ui_story_5004_50041901_49_dialog_content = "Conocerás al anciano después de la prueba.",
  ui_story_5004_50041901_50_dialog_content = "Gracias.",
  ui_story_5004_50041901_51_dialog_content = "¡Hey!",
  ui_story_5004_50041901_52_dialog_content = "¿Smokey? ¿Qué estás haciendo acá?",
  ui_story_5004_50041901_53_dialog_content = "Escuché que hay un tipo de prueba, ¡así que aquí estoy!",
  ui_story_5004_50041901_54_dialog_content = "Acabo de dar en el blanco con Luminatics, ¿verdad?",
  ui_story_5004_50041901_55_dialog_content = "Oh Dios, tan...",
  ui_story_5004_50041901_56_dialog_content = "¡Increíble poder! ¿Cómo es posible para una niña?",
  ui_story_5004_50041901_57_dialog_content = "¿Cuál es tu nombre? ¿De qué familia eres?",
  ui_story_5004_50041901_58_dialog_content = "¿Recibo un premio? No quiero las cosas habituales, sabes.",
  ui_story_5004_50041901_59_dialog_content = "¡Escuchen bien, soy Smokey de las Mantícoras!",
  ui_story_5004_50041901_60_dialog_content = "Smokey de las Mantícoras...",
  ui_story_5004_50041901_61_dialog_content = "¿Hay otros eventos o esto es todo?",
  ui_story_5004_50041901_62_dialog_content = "Espera, al anciano le gustaría hablar contigo.",
  ui_story_5004_50041901_63_dialog_content = "No puedo esperar, ¡todavía tengo que comprar ropa!",
  ui_story_5004_50041901_64_dialog_content = "¿Vienes conmigo, Genev?",
  ui_story_5004_50041901_65_dialog_content = "Acaso...",
  ui_story_5004_50041901_66_dialog_content = "Escucha, Genevieve...",
  ui_story_5004_50041901_67_dialog_content = "Perdiste la oportunidad de tu vida.",
  ui_story_5004_50041901_68_dialog_content = "Está bien, los Salars todavía están dispuestos a defender Petyaburg.",
  ui_story_5004_50041901_69_dialog_content = "Pero no hay posibilidad de una alianza.",
  ui_story_5004_50041901_70_dialog_content = "Puedes irte.",
  ui_story_5004_50041901_71_dialog_content = "Lo siento padre.",
  ui_story_5004_50041901_72_dialog_content = "(¿Por qué apareciste, Smokey?)",
  ui_story_5004_50041901_73_dialog_content = "(¿Solo querías competir? ¿Para ganar? O...)",
  ui_story_5004_50041901_74_dialog_content = "¡Genevieve!",
  ui_story_5004_50041901_75_dialog_content = "¿Qué te pasa, madre?",
  ui_story_5004_50041901_76_dialog_content = "¿Has escuchado?",
  ui_story_5004_50041901_77_dialog_content = "Los Salars hicieron un pacto con las Mantícoras...",
  ui_story_5004_50041901_78_dialog_content = "Yo sé sobre eso. Es una propuesta de matrimonio.",
  ui_story_5004_50041901_79_dialog_content = "¡Pero Smokey se fue sin dejar rastro!",
  ui_story_5004_50041901_80_dialog_content = "¿Qué?",
  ui_story_5004_50041901_81_dialog_content = "¿Smokey escapó?",
  ui_story_5004_50041901_82_dialog_content = "¡Maldita sea, no debimos haberle dado una oportunidad a esos patanes de Petyaburg!",
  ui_story_5004_50041901_83_dialog_content = "Que pérdida de tiempo. Mira el lado positivo, al menos no tenemos que ir a las afueras ahora.",
  ui_story_5004_50041901_84_dialog_content = "¡Oíd! Según el anciano, ¡Petyaburg ya no necesita protección de Lumopolis! ¡Dando la vuelta! ¡Ve!",
  ui_story_5004_50041901_85_dialog_content = "Y así, el ya desventurado Petyaburg cayó en picada hacia un mayor declive.",
  ui_story_5004_50041901_86_dialog_content = "La madre falleció en un accidente y el padre se enfermó.",
  ui_story_5004_50041901_87_dialog_content = "Genevieve...",
  ui_story_5004_50041901_88_dialog_content = "Estoy aquí, padre.",
  ui_story_5004_50041901_89_dialog_content = "La familia que juraste defender está llegando a su fin...",
  ui_story_5004_50041901_90_dialog_content = "¿Estás molesto o aliviado? ¿Has planeado lo que harás ahora?",
  ui_story_5004_50041901_91_dialog_content = "No lo sé, padre... Esto sucedió demasiado rápido para procesarlo.",
  ui_story_5004_50041901_92_dialog_content = "Pobre niño...",
  ui_story_5004_50041901_93_dialog_content = "...",
  ui_story_5004_50041901_94_dialog_content = "No pensé que te perdería a ti también, Anna.",
  ui_story_5004_50041901_95_dialog_content = "Relincho...",
  ui_story_5004_50041901_96_dialog_content = "¿Este caballo es suyo, señorita?",
  ui_story_5004_50041901_97_dialog_content = "Si.",
  ui_story_5004_50041901_98_dialog_content = "Puedo salvarla, pero debes...",
  ui_story_5004_50041901_99_dialog_content = "¡Lo haré, lo haré! ¡Necesito a Anna! ¡Necesito que encuentre a alguien conmigo!",
  ui_story_5004_50041901_100_dialog_content = "Smokey...",
  ui_story_5004_50041901_100X1_dialog_content = "Bueno, ¿si no es Genevieve?",
  ui_story_5004_50041901_100X2_dialog_content = "Sabes quién soy, así que ve al grano. No me interesa la charla.",
  ui_story_5004_50041901_100X3_dialog_content = "Oh, te interesará esta. Se trata de Smokey.",
  ui_story_5004_50041901_100X4_dialog_content = "¡¡!!",
  ui_story_5004_50041901_100X5_dialog_content = "¿Conoces a Smokey?",
  ui_story_5004_50041901_100X6_dialog_content = "Por supuesto. Incluso sé que está en la Costa Celestial...",
  ui_story_5004_50041901_100X7_dialog_content = "¡Oye, no te vayas, aún no he terminado!",
  ui_story_5004_50041901_102_dialog_content = "Srta. Genevieve.",
  ui_story_5004_50041901_103_dialog_content = "¡Srta. Genevieve!",
  ui_story_5004_50041901_104_dialog_content = "Si.",
  ui_story_5004_50041901_105_dialog_content = "Listos para emocionar las cosas como nos indicaste.",
  ui_story_5004_50041901_106_dialog_content = "Está bien, te enfrentaré uno a uno.",
  ui_story_5004_50041901_107_dialog_content = "Voy a vencer... no, ¡te venceré con mi canto!",
  ui_story_5004_50042001_1_dialog_content = "Qué escenario tan fabuloso. ¿Fleur lo diseñó?",
  ui_story_5004_50042001_2_dialog_content = "Al juzgar por la decoración de Rediesel Wrench, lo más probable.",
  ui_story_5004_50042001_3_dialog_content = "Es tan versátil.",
  ui_story_5004_50042001_4_dialog_content = "¿No estás en esto, PlayerName?",
  ui_story_5004_50042001_5_dialog_content = "Lo estoy omitiendo. Cantar no es lo mío en absoluto.",
  ui_story_5004_50042001_6_dialog_content = "Y yo... no me siento cómodo... con la multitud.",
  ui_story_5004_50042001_7_dialog_content = "Yo tampoco. Estoy viendo a Beryl.",
  ui_story_5004_50042001_8_dialog_content = "¡Sí, Raphaela y yo te animaremos mucho!",
  ui_story_5004_50042001_9_dialog_content = "¡Déjame los vítores a mí! ¡Cubriré a todos con misiles!",
  ui_story_5004_50042001_10_dialog_content = "¡No, no lo hagas! ¡Por favor!",
  ui_story_5004_50042001_11_dialog_content = "Ok, ¡lo tienes entonces!",
  ui_story_5004_50042001_12_dialog_content = "¡Prepárate a disfrutar del espectáculo y animarnos!",
  ui_story_5004_50042001_13_dialog_content = "Aquí estamos, la última competencia del Soberano del Océano, un concurso de inteligencia y belleza: ¡Playa EN VIVO!",
  ui_story_5004_50042001_14_dialog_content = "¡Con la afluencia de patrocinadores, podemos invitar a dos destacados A-listers como jueces!",
  ui_story_5004_50042001_15_dialog_content = "¡El anónimo Sr. S de Lumopolis!",
  ui_story_5004_50042001_16_dialog_content = "Ejem.",
  ui_story_5004_50042001_17_dialog_content = "¡Y el anónimo Sr. Y de Umbraton!",
  ui_story_5004_50042001_18_dialog_content = "Hola a todos.",
  ui_story_5004_50042001_19_dialog_content = "Bonacie invitó a dos jueces. Oye, ¿por qué se me hacen familiares?",
  ui_story_5004_50042001_20_dialog_content = "¡Los jueces y la audiencia en vivo elegirán al ganador!",
  ui_story_5004_50042001_21_dialog_content = "El primer competidor...",
  ui_story_5004_50042001_22_dialog_content = "es un cantante de heavy metal enmascarado infernal...",
  ui_story_5004_50042001_23_dialog_content = "Mi nombre es Sneaky Slim, ¡una cantante misteriosa de Umbraton!",
  ui_story_5004_50042001_24_dialog_content = "¿No es ese Seleucid? ¡El nombre y el casco prácticamente lo delatan!",
  ui_story_5004_50042001_25_dialog_content = "¡Ahora, permíteme rugir desde lo más profundo de mi alma!",
  ui_story_5004_50042001_26_dialog_content = "¡Y darte la interpretación de heavy metal más pesada de tu vida!",
  ui_story_5004_50042001_27_dialog_content = "¡Bájate del escenario!",
  ui_story_5004_50042001_28_dialog_content = "¡Bájate, bájate!",
  ui_story_5004_50042001_29_dialog_content = "¡Es trajes de baño EN VIVO!",
  ui_story_5004_50042001_30_dialog_content = "¿Qué haces sin traje de baño?",
  ui_story_5004_50042001_31_dialog_content = "¡Publicidad falsa! ¡Publicidad falsa!",
  ui_story_5004_50042001_32_dialog_content = "¡Vine por las chicas en traje de baño! ¡Reembolso! ¡Reembolso!",
  ui_story_5004_50042001_33_dialog_content = "Esto es penoso... Afortunadamente, no di mi nombre real.",
  ui_story_5004_50042001_34_dialog_content = "¡Bueno, supongo que los veré a todos otro día!",
  ui_story_5004_50042001_35_dialog_content = "¿Ya se acabó? Demasiado pronto...",
  ui_story_5004_50042001_36_dialog_content = "Qué lástima, ese tipo de la máscara de gato parece un buen cantante...",
  ui_story_5004_50042001_37_dialog_content = "No dejes que su apariencia te engañe, Beryl.",
  ui_story_5004_50042001_38_dialog_content = "Pero, hizo un buen trabajo, gran Seleucid.",
  ui_story_5004_50042001_39_dialog_content = "¡Bajó tanto la expectativa que las chicas seguro obtendrán puntuaciones más altas!",
  ui_story_5004_50042001_40_dialog_content = "El siguiente es... ¿Fleur y Brock?",
  ui_story_5004_50042001_41_dialog_content = "<color=#e8d9bb>Brock se inclina ante la audiencia, se gira y extiende un brazo...</color>",
  ui_story_5004_50042001_42_dialog_content = "¡Ahhhh!",
  ui_story_5004_50042001_43_dialog_content = "¡Ohhhh!",
  ui_story_5004_50042001_44_dialog_content = "¿Viste eso? ¡Fleur me sonrió!",
  ui_story_5004_50042001_45_dialog_content = "¡Tu mirada me disparó directo al corazón, Fleury! ¡Arde de amor!",
  ui_story_5004_50042001_46_dialog_content = "¡Chillido, chillido!",
  ui_story_5004_50042001_47_dialog_content = "¡Y aquí vienen las gaviotas! ¿No deberías estar cazando peces?",
  ui_story_5004_50042001_48_dialog_content = "¿Seguro que lo estamos haciendo?",
  ui_story_5004_50042001_49_dialog_content = "¡Claro, mi querido amigo!",
  ui_story_5004_50042001_50_dialog_content = "¡¿Por qué Brock tiene una barra de acero?!",
  ui_story_5004_50042001_51_dialog_content = "Espera un minuto. No está intentando ese truco de magia, ¿verdad?",
  ui_story_5004_50042001_52_dialog_content = "¿Puede la Rediesel Wrench más densa lograrlo?",
  ui_story_5004_50042001_53_dialog_content = "¡Kiyeah!",
  ui_story_5004_50042001_54_dialog_content = "<color=#e8d9bb>La barra de acero rasga la cortina y empala la caja, hasta que la punta sobresale del otro extremo.</color>",
  ui_story_5004_50042001_55_dialog_content = "¡Fleur!",
  ui_story_5004_50042001_56_dialog_content = "La caja se tambalea...",
  ui_story_5004_50042001_57_dialog_content = "¿Fleur está bien? No se ve bien...",
  ui_story_5004_50042001_58_dialog_content = "Relájate, estoy listo para dar ayuda médica.",
  ui_story_5004_50042001_59_dialog_content = "Nadie va a morir, ¿verdad?",
  ui_story_5004_50042001_60_dialog_content = "(¿Brock está murmurando algo?)",
  ui_story_5004_50042001_61_dialog_content = "La caja dejó de moverse... ¡Raphaela!",
  ui_story_5004_50042001_62_dialog_content = "Ok, ¡listo para disparar!",
  ui_story_5004_50042001_63_dialog_content = "¡Espera!",
  ui_story_5004_50042001_64_dialog_content = "¡Yoo-Hoo!",
  ui_story_5004_50042001_65_dialog_content = "¡Vaya, eso es increíble!",
  ui_story_5004_50042001_66_dialog_content = "Maravilloso...",
  ui_story_5004_50042001_67_dialog_content = "No, es una pérdida de energía. ¡Estaba listo a disparar!",
  ui_story_5004_50042001_68_dialog_content = "¿Disparar? ¿Con tus misiles? ¿Cómo es esa ayuda médica?",
  ui_story_5004_50042001_69_dialog_content = "Pero todos parecen disfrutar de la actuación y aplauden.",
  ui_story_5004_50042001_70_dialog_content = "Creo que eso se debe a que Fleur todavía está viva.",
  ui_story_5004_50042001_71_dialog_content = "Alto, estoy seguro de que dije que solo se permite cantar para el concurso, ¿no?",
  ui_story_5004_50042001_72_dialog_content = "No es bueno violar las reglas, Brock y Fleur. Especialmente cuando los conoces, ¿no?",
  ui_story_5004_50042001_73_dialog_content = "Jaja, lo siento por eso. Solo queremos alegrar a la multitud y generar más entusiasmo.",
  ui_story_5004_50042001_74_dialog_content = "Pero no puedo cantar, así que pensé que haría esto.",
  ui_story_5004_50042001_75_dialog_content = "¿Quién es esa mujer para sermonear así a Fleur?",
  ui_story_5004_50042001_76_dialog_content = "¡Fleur! ¡Te amamos!",
  ui_story_5004_50042001_77_dialog_content = "(No está mal que esto se convierta en un concurso de talentos).",
  ui_story_5004_50042001_78_dialog_content = "(Aunque es una lástima que Seleucid se haya retirado temprano).",
  ui_story_5004_50042001_79_dialog_content = "(Aunque, con su máscara de gato, es mejor para espectáculos de cantantes enmascarados).",
  ui_story_5004_50042001_80_dialog_content = "Reglas son reglas. Por esto descalifico a Fleur.",
  ui_story_5004_50042001_81_dialog_content = "¡¿Por qué tiene que ser cantando?!",
  ui_story_5004_50042001_82_dialog_content = "¡Puedes actuar en nuestras salas en cualquier momento, Fleur!",
  ui_story_5004_50042001_83_dialog_content = "¡Guau guau!",
  ui_story_5004_50042001_84_dialog_content = "¡Miau!",
  ui_story_5004_50042001_85_dialog_content = "¡Y aquí vienen los animales! El rasgo especial de Fleur es aterrador...",
  ui_story_5004_50042001_86_dialog_content = "¡Concursante número ocho!",
  ui_story_5004_50042001_87_dialog_content = "¡Genevieve Vronsky!",
  ui_story_5004_50042001_88_dialog_content = "Je, este es el nivel de competidor al que me enfrento.",
  ui_story_5004_50042001_89_dialog_content = "¡Aprovecharé la oportunidad para impresionar a los jueces y al público y obtener la puntuación más alta!",
  ui_story_5004_50042001_90_dialog_content = "(Más competidores extraños...)",
  ui_story_5004_50042001_91_dialog_content = "(¿Ya es el turno de Vice?)",
  ui_story_5004_50042001_92_dialog_content = "Genevieve está ahora, PlayerName.",
  ui_story_5004_50042001_93_dialog_content = "Sí, probab. sea la competencia más grande que tenemos.",
  ui_story_5004_50042001_94_dialog_content = "Cayendo de una tormenta♪",
  ui_story_5004_50042001_95_dialog_content = "¡¡...!!",
  ui_story_5004_50042001_96_dialog_content = "¿Fue un juicio despiadado o una salvación liberadora?♪",
  ui_story_5004_50042001_97_dialog_content = "Desvaneciéndose desde el horizonte♪",
  ui_story_5004_50042001_98_dialog_content = "Es tu figura inescrutable♪",
  ui_story_5004_50042001_99_dialog_content = "Anhelos persistentes con vendaval y lluvia♪",
  ui_story_5004_50042001_100_dialog_content = "Desafiando la vulgaridad♪",
  ui_story_5004_50042001_101_dialog_content = "Arrancó el camino por delante con pasión e impulso♪",
  ui_story_5004_50042001_102_dialog_content = "Haciendo la vista gorda a la llamada guerra♪",
  ui_story_5004_50042001_103_dialog_content = "Eso es impresionante.",
  ui_story_5004_50042001_104_dialog_content = "...",
  ui_story_5004_50042001_105_dialog_content = "¡Ohhhh, Genevieve!",
  ui_story_5004_50042001_106_dialog_content = "Qué actuación tan emotiva. Todo el mundo lo sentía.",
  ui_story_5004_50042001_107_dialog_content = "La voz de Genevieve llega directo a mi corazón. Espero que celebre un concierto en Umbraton.",
  ui_story_5004_50042001_108_dialog_content = "Tenemos los resultados. ¡La puntuación final para Genevieve es 9,6!",
  ui_story_5004_50042001_109_dialog_content = "Felicitaciones, esa es una puntuación muy alta, ¿no?",
  ui_story_5004_50042001_110_dialog_content = "Gracias por la actuación, Genevieve.",
  ui_story_5004_50042001_111_dialog_content = "Entonces, ¿ves eso, Smokey?",
  ui_story_5004_50042001_112_dialog_content = "Impresionante...",
  ui_story_5004_50042001_113_dialog_content = "El canto estuvo lleno de emociones.",
  ui_story_5004_50042001_114_dialog_content = "(El canto de Genevieve está fuera de este mundo, definitivamente ha hecho nuevos fanáticos).",
  ui_story_5004_50042001_115_dialog_content = "(Ahora me preocupa Vice...)",
  ui_story_5004_50042001_116_dialog_content = "¡Ahora tenemos el trío de chicas, Beso de la Mantícora!",
  ui_story_5004_50042001_117_dialog_content = "¡Es el turno de Vice!",
  ui_story_5004_50042001_118_dialog_content = "¡Finalmente! Me estoy poniendo nerviosa.",
  ui_story_5004_50042001_119_dialog_content = "¡Yo también!",
  ui_story_5004_50042001_120_dialog_content = "♪—",
  ui_story_5004_50042001_121_dialog_content = "♪ ♩ ♫ ♬",
  ui_story_5004_50042001_122_dialog_content = "Quién sabe dónde acabarán las chicas vagabundas hoy♪",
  ui_story_5004_50042001_123_dialog_content = "Paseando por la costa bajo la luz de un faro en la noche♪",
  ui_story_5004_50042001_124_dialog_content = "¡Oh!",
  ui_story_5004_50042001_125_dialog_content = "¡Hurra, hurra, hurra!",
  ui_story_5004_50042001_126_dialog_content = "(Incluso los fans de Genevieve vitorean y aplauden como locos).",
  ui_story_5004_50042001_127_dialog_content = "El olor de las mareas se mueve por la playa bajo las estrellas♪",
  ui_story_5004_50042001_128_dialog_content = "Abrazando y nutriendo flores con silenciosa determinación♪",
  ui_story_5004_50042001_129_dialog_content = "Resolviendo superar el oleaje del agua para la victoria final♪",
  ui_story_5004_50042001_130_dialog_content = "¡Carleen! ¡Pequeña Vice! ¡Pequeña Smokey! ¡Son las mejores!",
  ui_story_5004_50042001_131_dialog_content = "¡Toma mi mano y saluda con la mano, Beryl!",
  ui_story_5004_50042001_132_dialog_content = "¡Seguro!",
  ui_story_5004_50042001_133_dialog_content = "Captura el brillo con un orgullo inquebrantable♪",
  ui_story_5004_50042001_134_dialog_content = "Siente el rugido de un corazón al borde de estallar♪",
  ui_story_5004_50042001_135_dialog_content = "Latiendo intensamente♪",
  ui_story_5004_50042001_136_dialog_content = "Con ojos brillantes e impulso desenfrenado hacia el verdadero destino♪",
  ui_story_5004_50042001_137_dialog_content = "Cargar siempre adelante♪",
  ui_story_5004_50042001_138_dialog_content = "A la cima del mundo♪",
  ui_story_5004_50042001_139_dialog_content = "<color=#e8d9bb>Con el micrófono en una mano, Smokey hace una pistola con la otra y un gesto de disparo a Genevieve, luego termina la canción con un guiño.</color>",
  ui_story_5004_50042001_140_dialog_content = "<color=#e8d9bb>El Beso de la Mantícora, termina a la perfección.</color>",
  ui_story_5004_50042001_141_dialog_content = "...",
  ui_story_5004_50042001_142_dialog_content = "(Hmm, ¿cuándo llegó ella aquí?)",
  ui_story_5004_50042001_143_dialog_content = "No está mal, aunque antes era un dúo.",
  ui_story_5004_50042001_144_dialog_content = "¿Qué?",
  ui_story_5004_50042001_145_dialog_content = "(Ella se ha ido. ¿Estaba burlándose? ¿Que quiso decir ella con eso?)",
  ui_story_5004_50042001_146_dialog_content = "¡Beso de la Mantícora! ¡Beso de la Mantícora! ¡Beso de la Mantícora!",
  ui_story_5004_50042001_147_dialog_content = "¡Impresionante, Beso de la Mantícora!",
  ui_story_5004_50042001_148_dialog_content = "A todos le encanta la actuación. Hasta Beryl esta conmovida.",
  ui_story_5004_50042001_149_dialog_content = "¿Conseguiste todo eso en video?",
  ui_story_5004_50042001_150_dialog_content = "Sí, mi S... ¡Señor!",
  ui_story_5004_50042001_151_dialog_content = "Es un grupo divertido.",
  ui_story_5004_50042001_154_dialog_content = "Beso de la Mantícora...",
  ui_story_5004_50042001_155_dialog_content = "¡Un 10 perfecto!",
  ui_story_5004_50042201_1_dialog_content = "¡Salud!",
  ui_story_5004_50042201_2_dialog_content = "¡Ja!",
  ui_story_5004_50042201_3_dialog_content = "¿Cuál es la gran idea con todo el jugo?",
  ui_story_5004_50042201_4_dialog_content = "¿Pero no bebes jugo también?",
  ui_story_5004_50042201_5_dialog_content = "¡No, gracias a ti!",
  ui_story_5004_50042201_6_dialog_content = "¡Jajaja!",
  ui_story_5004_50042201_7_dialog_content = "¡Estuvieron fantásticas, Carleen, Vice y Smokey!",
  ui_story_5004_50042201_8_dialog_content = "¡Se movían por el escenario como superestrellas!",
  ui_story_5004_50042201_9_dialog_content = "Beryl se conmovió hasta las lágrimas, ¿verdad?",
  ui_story_5004_50042201_10_dialog_content = "Oh... Sí, fue una actuación muy conmovedora.",
  ui_story_5004_50042201_11_dialog_content = "Sus voces y movimientos fueron cautivadores.",
  ui_story_5004_50042201_12_dialog_content = "¡Un espectáculo impecable, como dice Beryl!",
  ui_story_5004_50042201_13_dialog_content = "¿Me pregunto cuál será el premio misterioso?",
  ui_story_5004_50042201_14_dialog_content = "Hablando de eso, si tengo curiosidad.",
  ui_story_5004_50042201_15_dialog_content = "Podría preguntarle a Bonacie, pero ella me daría una sonrisa misteriosa y me diría que esperara hasta mañana.",
  ui_story_5004_50042201_16_dialog_content = "Sí, me interesa ver qué es.",
  ui_story_5004_50042201_17_dialog_content = "Espero sea una especie de jarabe increíble. ¡Para atraer a más clientes!",
  ui_story_5004_50042201_18_dialog_content = "¡Quizás debería abrir tiendas de granizado en Lumopolis!",
  ui_story_5004_50042201_19_dialog_content = "Creo que Raphaela te perseguiría por ser un vendedor ambulante sin licencia.",
  ui_story_5004_50042201_20_dialog_content = "¡Je, por Vice, le daré un minuto de ventaja!",
  ui_story_5004_50042201_21_dialog_content = "Hola, felicitaciones a todos.",
  ui_story_5004_50042201_22_dialog_content = "¿Gracias, Genevieve? ¿Estás aquí solo para felicitarnos?",
  ui_story_5004_50042201_23_dialog_content = "Por supuesto, soy un noble. Hmph.",
  ui_story_5004_50042201_24_dialog_content = "¿Por qué me tomas, una niña pequeña quejándose de su pérdida?",
  ui_story_5004_50042201_25_dialog_content = "¿No lloraste? Has crecido mucho, Genev. Ella era una llorona.",
  ui_story_5004_50042201_26_dialog_content = "¿Qué? ¡Debería matarte ahora!",
  ui_story_5004_50042201_27_dialog_content = "Okey, okey. Ven, siéntate y bebe con nosotros. ¿Que lo pasado sea pasado?",
  ui_story_5004_50042201_28_dialog_content = "Smokey agarra los brazos de Genevieve y la arrastra al asiento de al lado.",
  ui_story_5004_50042201_29X1_dialog_content = "¡Prueba esto!",
  ui_story_5004_50042201_29X2_dialog_content = "Tsk, qué molesto.",
  ui_story_5004_50042201_29X3_dialog_content = "¿Es este...?",
  ui_story_5004_50042201_29X4_dialog_content = "Sí, ¿no sabe igual que a la vendimia en esa taberna de Petyaburg, a la que solíamos ir?",
  ui_story_5004_50042201_29X5_dialog_content = "Supongo. Ha pasado tanto tiempo que no lo recuerdo.",
  ui_story_5004_50042201_29X6_dialog_content = "¿Por qué el nombre Beso de la Mantícora?",
  ui_story_5004_50042201_29X7_dialog_content = "Como esta bebida, debes saber por qué. No creo que lo olvides.",
  ui_story_5004_50042201_29X8_dialog_content = "...",
  ui_story_5004_50042201_30_dialog_content = "(Qué complicado entre esos dos.)",
  ui_story_5004_50042201_31_dialog_content = "Me gustaría volver a ver el truco de magia de Fleur.",
  ui_story_5004_50042201_32_dialog_content = "Todavía no puedo entender cómo lo hizo.",
  ui_story_5004_50042201_33_dialog_content = "Por supuesto, me alegra volver a interpretarlo para todos.",
  ui_story_5004_50042201_34_dialog_content = "¿Qué tal un lugar más privado esta vez?",
  ui_story_5004_50042201_35_dialog_content = "Tuvimos que pelear no solo con la gente, sino también con perros y gatos, solo para sacarte de allí.",
  ui_story_5004_50042201_36_dialog_content = "Y te agradezco por eso. Déjame curar tus heridas más tarde.",
  ui_story_5004_50042201_37_dialog_content = "El robot también está a punto de completarse, necesito tu ayuda.",
  ui_story_5004_50042201_38_dialog_content = "No hay problema, pero no me interrumpas bebiendo ahora mismo.",
  ui_story_5004_50042201_39_dialog_content = "¿Está casi completo el robot?",
  ui_story_5004_50042201_40_dialog_content = "¡El departamento de investigación de Illumina necesita varios meses para construir uno!",
  ui_story_5004_50042201_41_dialog_content = "Todo es gracias a la srta. Bonacie. Tuve acceso a una gran cantidad de equipos y archivos útiles que trabajaban para ella.",
  ui_story_5004_50042201_42_dialog_content = "Mi perfecta creación, el NO. 1 robot de batalla en Rediesel Wrench...",
  ui_story_5004_50042201_43_dialog_content = "¡Nacerá esta noche!",
  ui_story_5004_50042201_44_dialog_content = "(La primera vez que veo a Fleur así de seria.)",
  ui_story_5004_50042201_45_dialog_content = "(Fleur debe estar muy interesada en máquinas y robots.)",
  ui_story_5004_50042201_46_dialog_content = "¿Qué fue eso...?",
  ui_story_5004_50042201_47_dialog_content = "Oh...",
  ui_story_5004_50042201_48_dialog_content = "¡Estás sudando, Beryl!",
  ui_story_5004_50042201_49_dialog_content = "¿Puedes llevarme a la habitación, Raphaela?",
  ui_story_5004_50042201_50_dialog_content = "Beryl no se siente bien, PlayerName. Vámonos.",
  ui_story_5004_50042201_51_dialog_content = "¿Aún no se recupera Beryl? Se obligó demasiado la última vez, pero eso fue hace varios días.",
  ui_story_5004_50042201_52_dialog_content = "Su condición no parece haber mejorado.",
  ui_story_5004_50042201_53_dialog_content = "Probab. esté más completo de lo que pensamos. Oh, ¿te habló Raphaela sobre el archivo de Pirro?",
  ui_story_5004_50042201_54_dialog_content = "Sí, envié una solicitud para otorgarle todo acceso a Beretta.",
  ui_story_5004_50042201_55_dialog_content = "Si hay alguna información útil, solo podemos contar con ella",
  ui_story_5004_50042301_1_dialog_content = "Si el ritual tiene éxito...",
  ui_story_5004_50042301_2_dialog_content = "El Celestita debe abrir el movimiento y jugarlo.",
  ui_story_5004_50042301_3_dialog_content = "La gloria del Monarca brillará una vez más en esta playa y castigará a los pomposos aurorians.",
  ui_story_5004_50042301_4_dialog_content = "¡Entendido! Ten la seguridad de que no escatimaré esfuerzos.",
  ui_story_5004_50042301_5_dialog_content = "Aquí estoy.",
  ui_story_5004_50042301_6_dialog_content = "¿No puedes tocar, Bonacie?",
  ui_story_5004_50042301_7_dialog_content = "Para de perder el tiempo. ¿Qué quieres conmigo?",
  ui_story_5004_50042301_8_dialog_content = "El Movimiento está a punto de ser desenterrado y el sello...",
  ui_story_5004_50042301_9_dialog_content = "Lo sé, lo sé, el Celestita tiene que quitarlo, ¿no?",
  ui_story_5004_50042301_10_dialog_content = "Le diré a PlayerName que haga eso.",
  ui_story_5004_50042301_11_dialog_content = "¿No sientes curiosidad por lo que estamos tramando?",
  ui_story_5004_50042301_12_dialog_content = "Nop. Solo quiero mis manos sobre el Movimiento.",
  ui_story_5004_50042301_13_dialog_content = "Y cualquiera de los aurorians en ese grupo podría golpearte sin sudar, de todos modos.",
  ui_story_5004_50042301_14_dialog_content = "Si realmente estás tramando, espero que al menos dejen tus cadáveres en una sola pieza.",
  ui_story_5004_50042301_15_dialog_content = "Esas estafas para hacer dinero son absolutamente ridículas, ¿no?",
  ui_story_5004_50042301_16_dialog_content = "¡Sigues siendo el mismo Aurorian exasperante que has sido!",
  ui_story_5004_50042301_17_dialog_content = "Te pillaré...",
  ui_story_5004_50042301_18_dialog_content = "¡Por favor, cálmate, Lord Prinny!",
  ui_story_5004_50042301_19_dialog_content = "¿Qué estás haciendo acá? Ya es hora de que anuncies las lecciones de yoga, ¿no?",
  ui_story_5004_50042301_20_dialog_content = "No importa, todavía tengo que ver a PlayerName. Pueden jugar entre ustedes.",
  ui_story_5004_50042301_21_dialog_content = "¡Espera, solo un minuto, Bonacie!",
  ui_story_5004_50042301_22_dialog_content = "¡Me gustaría que escuchen los nuevos lemas que escribí!",
  ui_story_5004_50042301_23_dialog_content = "...",
  ui_story_5004_50042301_24_dialog_content = "Debería ser yo quien manipule al Aurorian, pero soy yo el que está cabreado.",
  ui_story_5004_50042301_25_dialog_content = "¡Sin mencionar a los lacayos inútiles que dan prioridad a las lecciones falsas!",
  ui_story_5004_50042301_26_dialog_content = "Ah...",
  ui_story_5004_50042301_35_dialog_content = "¡Aquí, acuéstate en la cama, Beryl!",
  ui_story_5004_50042301_36_dialog_content = "Mmmm, tu temperatura corporal es muy alta y estás sudando profusamente... Debes sentirte terrible.",
  ui_story_5004_50042301_37_dialog_content = "Yo... Estoy aguantando...",
  ui_story_5004_50042301_38_dialog_content = "¡Déjame traerte una toalla para secarte el sudor!",
  ui_story_5004_50042301_39_dialog_content = "Está bien, pero...",
  ui_story_5004_50042301_40_dialog_content = "¿Puedes acostarte conmigo un rato?",
  ui_story_5004_50042301_41_dialog_content = "¡No hay problema!",
  ui_story_5004_50042301_42_dialog_content = "Pobre Beryl, puedo sentir el calor que sale de ti. Una toalla mojada o una bolsa de hielo deberían refrescarte, ¿seguro de que no necesitas una?",
  ui_story_5004_50042301_43_dialog_content = "Quédate... ¿Quieres? Esto lo hará...",
  ui_story_5004_50042301_44_dialog_content = "Después de la ceremonia de mañana, le pediremos a PlayerName que nos lleve a Lumopolis con Soroz.",
  ui_story_5004_50042301_45_dialog_content = "Las instalaciones de allí deberían hacer un mejor trabajo al monitorear su condición.",
  ui_story_5004_50042301_46_dialog_content = "Y encontrarás que Lumopolis está llena de gente interesante, Beryl. También puedo presentarte a los otros ángeles.",
  ui_story_5004_50042301_47_dialog_content = "¡Les agradarás mucho a todos!",
  ui_story_5004_50042301_48_dialog_content = "Oh, tenemos un ángel llamado Uriela. ¡Ella solía estar letárgica como tú, Beryl!",
  ui_story_5004_50042301_49_dialog_content = "Pero al igual que tú, ¡ella es muy confiable!",
  ui_story_5004_50042301_50_dialog_content = "¿Crees que soy digno de confianza?",
  ui_story_5004_50042301_51_dialog_content = "¡Totalmente! Y la ciudad tiene muchas tiendas elegantes y diferentes tipos de restaurantes.",
  ui_story_5004_50042301_52_dialog_content = "¡Puedo llevarte de compras a mis lugares favoritos!",
  ui_story_5004_50042301_53_dialog_content = "Si te gusta hornear, ¡podemos visitar la panadería a la que soy habitual!",
  ui_story_5004_50042301_54_dialog_content = "¡El dueño es muy agradable y me enseñó a hacer diferentes pasteles!",
  ui_story_5004_50042301_55_dialog_content = "¡Ah, y el Lumopolis Music Hall! Consiguen artistas increíbles para tocar allí, aunque las entradas pueden ser difíciles de conseguir...",
  ui_story_5004_50042301_56_dialog_content = "Oh...",
  ui_story_5004_50042301_57_dialog_content = "¿Sí, Beryl?",
  ui_story_5004_50042301_58_dialog_content = "Tengo algo que no sé si debería decirte...",
  ui_story_5004_50042301_59_dialog_content = "¡Cuéntame, cuéntame!",
  ui_story_5004_50042301_60_dialog_content = "Estoy muy asustada...",
  ui_story_5004_50042301_61_dialog_content = "... que yo... no puedo irme de aquí.",
  ui_story_5004_50042301_62_dialog_content = "¿Qué? ¿Cómo?",
  ui_story_5004_50042301_63_dialog_content = "Tengo pesadillas, todas las noches...",
  ui_story_5004_50042301_64_dialog_content = "... Teniendo el mismo sueño, seguía empeorando...",
  ui_story_5004_50042301_65_dialog_content = "Comenzó conmigo solo escuchando una voz débil...",
  ui_story_5004_50042301_66_dialog_content = "Seguía hablándome... me hizo recordar muchas cosas que había olvidado...",
  ui_story_5004_50042301_67_dialog_content = "(¿Del pasado de Beryl? ¿Podría ser sobre los Gautiers y Pyrrhuses?)",
  ui_story_5004_50042301_68_dialog_content = "Dijo muchas cosas que no recuerdo y otras que no quiero recordar... Tengo miedo.",
  ui_story_5004_50042301_69_dialog_content = "La voz terminó repitiéndome...",
  ui_story_5004_50042301_70_dialog_content = "Que mi cuerpo cederá y perderá el control, con mi mente cayendo en una espiral descendente sin fin después de matar a todos.",
  ui_story_5004_50042301_71_dialog_content = "¡¡!!",
  ui_story_5004_50042301_72_dialog_content = "Intenté con todas mis fuerzas sacarme los sueños de la cabeza, pero no desaparecían...",
  ui_story_5004_50042301_73_dialog_content = "Siento que mi cuerpo se deteriora...",
  ui_story_5004_50042301_74_dialog_content = "Oh, Beryl...",
  ui_story_5004_50042301_75_dialog_content = "¡No deberías creer nada en sueños así!",
  ui_story_5004_50042301_76_dialog_content = "Ah...",
  ui_story_5004_50042301_77_dialog_content = "Los sueños son solo eso, sueños. No significan nada.",
  ui_story_5004_50042301_78_dialog_content = "No te sientes bien probablemente porque has estado haciendo cosas para todos los últimos dos días, y tal vez por demasiada emoción.",
  ui_story_5004_50042301_79_dialog_content = "En cuanto a los sueños, verificaré con PlayerName, tal vez esas habilidades psíquicas puedan ayudarte a aclararte.",
  ui_story_5004_50042301_80_dialog_content = "¡Descansa mientras voy!",
  ui_story_5004_50042301_81_dialog_content = "Escúchame y relájate. ¡Regresaremos a Lumopolis mañana!",
  ui_story_5004_50042301_82_dialog_content = "Está bien.",
  ui_story_5004_50042301_83_dialog_content = "Vuelvo enseguida, ¿de acuerdo?",
  ui_story_5004_50042301_84_dialog_content = "Eso estuvo cerca...",
  ui_story_5004_50042301_85_dialog_content = "No puedo dejar que vuelvas pronto.",
  ui_story_5004_50042301_86_dialog_content = "¿Qué? ¿Estás seguro?",
  ui_story_5004_50042301_87_dialog_content = "Si. Casi choca conmigo.",
  ui_story_5004_50042301_88_dialog_content = "Si eso es cierto, debo decírselo a la Reina.",
  ui_story_5004_50042301_89_dialog_content = "Acabo de entregar información vital, así que sobre mi bono de este mes...",
  ui_story_5004_50042301_90_dialog_content = "Te irás ahora.",
  ui_story_5004_50042301_91_dialog_content = "¡Inútil!",
  ui_story_5004_50042301_92_dialog_content = "Mantén la calma.",
  ui_story_5004_50042301_93_dialog_content = "¿Sabes por lo que pasé para poner todas las piezas en su lugar? Ahora por toda tu ineptitud...",
  ui_story_5004_50042301_94_dialog_content = "¡Se están escapando!",
  ui_story_5004_50042301_95_dialog_content = "¡Lo lamentamos!",
  ui_story_5004_50042301_96_dialog_content = "Peones inútiles. Supongo que tendré que hacerlo yo mismo.",
  ui_story_5004_50042301_97_dialog_content = "Una pena que esta pieza sea mi más preciada...",
  ui_story_5004_50042301_98_dialog_content = "Je...",
  ui_story_5004_50042401_1_dialog_content = "¡Ven conmigo por un minuto, PlayerName!",
  ui_story_5004_50042401_2_dialog_content = "Deja de arrastrarme. ¡Estoy discutiendo cómo expandir el negocio del granizado con Vice!",
  ui_story_5004_50042401_3_dialog_content = "¡Podemos actualizarlo con el dinero que ganemos mañana, y luego pasar a cosas más grandes y mejores!",
  ui_story_5004_50042401_4_dialog_content = "Deja de pensar en eso ahora. ¡La Pequeña Beryl está en mal estado!",
  ui_story_5004_50042401_5_dialog_content = "¿Qué está pasando con Beryl?",
  ui_story_5004_50042401_6_dialog_content = "Tenemos que llevarla de regreso a Lumopolis para recibir tratamiento de inmediato.",
  ui_story_5004_50042401_7_dialog_content = "Eso es cierto, deberíamos volver atrás, PlayerName.",
  ui_story_5004_50042401_8_dialog_content = "No olvides que vinimos aquí para animar a Beryl.",
  ui_story_5004_50042401_9_dialog_content = "Pero si realmente la está empeorando, ¡debemos irnos!",
  ui_story_5004_50042401_10_dialog_content = "Estás en lo correcto. Veamos cómo le va ahora.",
  ui_story_5004_50042401_11_dialog_content = "¡Uy, eso duele! No veo nada más que oscuridad...",
  ui_story_5004_50042401_12_dialog_content = "¡Lo siento! ¿Estás bien, Bonacie?",
  ui_story_5004_50042401_13_dialog_content = "Oh, tenemos que irnos a Lumopolis por asuntos urgentes, ¡deja los premios para la próxima vez!",
  ui_story_5004_50042401_14_dialog_content = "¿Qué? ¿Qué quieres decir con eso?",
  ui_story_5004_50042401_15_dialog_content = "Santo movimiento, ¿ahora?",
  ui_story_5004_50042401_16_dialog_content = "Bien, tengo a todos aquí...",
  ui_story_5004_50042401_17_dialog_content = "¿Pequeña Beryl...?",
  ui_story_5004_50042401_18_dialog_content = "¿Dónde está Beryl? ¿A dónde fue?",
  ui_story_5004_50042401_19_dialog_content = "Deja de sacudirme. Yo no la llevé.",
  ui_story_5004_50042401_20_dialog_content = "¡Le dije que se quedara y descansara!",
  ui_story_5004_50042401_21_dialog_content = "Rápido, piensa en algo. ¡Es peligroso para ella estar corriendo enferma!",
  ui_story_5004_50042401_22_dialog_content = "¡PlayerName! ¡PlayerName!",
  ui_story_5004_50042401_23_dialog_content = "¡Usa tus habilidades psíquicas y ayuda a Raphaela, PlayerName!",
  ui_story_5004_50042401_24_dialog_content = "Okey, okey... ¡Pero no puedo hacerlo contigo sacudiéndome!",
  ui_story_5004_50042401_25_dialog_content = "Cálmate y suelta PlayerName, Raphaela.",
  ui_story_5004_50042401_26_dialog_content = "Wow...",
  ui_story_5004_50042401_27_dialog_content = "No en el hotel.",
  ui_story_5004_50042401_28_dialog_content = "Pero todavía puedo seguir su rastro.",
  ui_story_5004_50042401_29_dialog_content = "Parece dirigirse hacia el acantilado donde está la estatua de piedra.",
  ui_story_5004_50042401_30_dialog_content = "¡Haz que todos los demás busquen a Beryl también, PlayerName!",
  ui_story_5004_50042401_31_dialog_content = "¿Todos? ¿Es eso necesario?",
  ui_story_5004_50042401_32_dialog_content = "Las vacaciones deben haberte vuelto estúpido, PlayerName.",
  ui_story_5004_50042401_33_dialog_content = "El hotel es más seguro debido a todas las medidas de seguridad.",
  ui_story_5004_50042401_34_dialog_content = "¿Pero no recuerdas las hordas de Eclipsites con las que nos encontramos en el camino aquí?",
  ui_story_5004_50042401_35_dialog_content = "¿Qué pasaría si Beryl tropezara accidentalmente con algo similar?",
  ui_story_5004_50042401_36_dialog_content = "Eso es verdad...",
  ui_story_5004_50042401_37_dialog_content = "Ok, ¡hagamos que todos ayuden!",
  ui_story_5004_50042401_38_dialog_content = "Gracias a todos por venir... incluso Genevieve está aquí.",
  ui_story_5004_50042401_39_dialog_content = "Ahora somos amigos y los amigos se ayudan unos a otros.",
  ui_story_5004_50042401_40_dialog_content = "En realidad, es de buen corazón, a pesar de su personalidad agresiva.",
  ui_story_5004_50042401_41_dialog_content = "¿Qué? ¡Vine porque no quiero perder ninguna oportunidad de avergonzarte!",
  ui_story_5004_50042401_42_dialog_content = "Espero que ustedes dos puedan suavizar sus diferencias. Ahora, ¡tenemos que encontrar a Beryl!",
  ui_story_5004_50042401_43_dialog_content = "¿Estás seguro de que es por aquí, PlayerName? El bosque se siente aterrador.",
  ui_story_5004_50042401_44_dialog_content = "Sí, esta es la dirección que tomó Beryl.",
  ui_story_5004_50042401_45_dialog_content = "Pero se siente como si estuviéramos dando vueltas y es muy diferente a como se veía de día.",
  ui_story_5004_50042401_46_dialog_content = "(El pasaje parece durar una eternidad, y quién sabe qué criaturas están haciendo todos los ruidos aterradores...)",
  ui_story_5004_50042401_47_dialog_content = "Espera, escucho algo.",
  ui_story_5004_50042401_48_dialog_content = "¡Hey!",
  ui_story_5004_50042401_49_dialog_content = "¡Whoa!",
  ui_story_5004_50042401_50_dialog_content = "¿Bonacie? ¿Qué estás haciendo acá?",
  ui_story_5004_50042401_51_dialog_content = "¿No dijiste que te ibas? Estoy tratando de conseguirle el <color=#FFB400>gran premio</color> lo antes posible.",
  ui_story_5004_50042401_52_dialog_content = "¿Por qué están todos aquí?",
  ui_story_5004_50042401_53_dialog_content = "¿Buscas una última aventura antes de volver?",
  ui_story_5004_50042401_54_dialog_content = "¿Puedo ir?",
  ui_story_5004_50042401_55_dialog_content = "¡No, no es una aventura!",
  ui_story_5004_50042401_56_dialog_content = "Beryl ha desaparecido. Queremos volver porque su condición está empeorando.",
  ui_story_5004_50042401_57_dialog_content = "Raphaela está preocupada por eso o por la posibilidad de que ella se encuentre con Eclipsites.",
  ui_story_5004_50042401_58_dialog_content = "Ya que es Beryl, como compañero de True Order debo insistir en unirme a ustedes.",
  ui_story_5004_50042401_59_dialog_content = "Pero este es un lugar muy peligroso. ¡Hay más peligro presente que solo Eclipsites!",
  ui_story_5004_50042401_60_dialog_content = "No es una aventura, ¡así que detente con las advertencias!",
  ui_story_5004_50042401_61_dialog_content = "Puedo sentir a Beryl en la cima del acantilado... y dejó de moverse.",
  ui_story_5004_50042401_62_dialog_content = "Pero todavía no podemos salir del bosque...",
  ui_story_5004_50042401_63_dialog_content = "Como es para Beryl, te guiaré fuera de aquí. Sígueme.",
  ui_story_5004_50042401_64_dialog_content = "¡Beryl!",
  ui_story_5004_50042401_65_dialog_content = "¡No te acerques más...!",
  ui_story_5004_50042401_66_dialog_content = "¡Deja de avanzar, es peligroso allá!",
  ui_story_5004_50042401_67_dialog_content = "Sé que lo es, así que no te acerques más...",
  ui_story_5004_50042401_68_dialog_content = "Cálmate, Beryl. Cuéntanos por qué quieres venir aquí.",
  ui_story_5004_50042401_69_dialog_content = "Yo... Tampoco estoy segura...",
  ui_story_5004_50042401_70_dialog_content = "Después que Raphaela se fue, caí en la cama, completamente agotada...",
  ui_story_5004_50042401_71_dialog_content = "Y me di cuenta que no podía moverme...",
  ui_story_5004_50042401_72_dialog_content = "Luego, un brazo oscuro se enroscó en mi cuello y me cubrió los ojos.",
  ui_story_5004_50042401_73_dialog_content = "Se río terriblemente en mis oídos y me desmayé...",
  ui_story_5004_50042401_74_dialog_content = "¿Es la misma voz que escuchaste en tus sueños?",
  ui_story_5004_50042401_75_dialog_content = "Si...",
  ui_story_5004_50042401_76_dialog_content = "No sé que estoy haciendo aquí...",
  ui_story_5004_50042401_77_dialog_content = "O qué será de mí...",
  ui_story_5004_50042401_78_dialog_content = "Si la voz es verdad... que los mataré a todos...",
  ui_story_5004_50042401_79_dialog_content = "¡Pero esas son solo pesadillas!",
  ui_story_5004_50042401_80_dialog_content = "Aun así, ¡me han traído aquí!",
  ui_story_5004_50042401_81_dialog_content = "¡No quiero que nadie más muera por mi mano!",
  ui_story_5004_50042401_82_dialog_content = "¡Deja de hablar tonterías!",
  ui_story_5004_50042401_83_dialog_content = "...",
  ui_story_5004_50042401_84_dialog_content = "¡Estarás bien! ¿No eres ahora uno de los guerreros de la playa?",
  ui_story_5004_50042401_85_dialog_content = "(¿Cómo va a ayudar eso?)",
  ui_story_5004_50042401_86_dialog_content = "Raphaela...",
  ui_story_5004_50042401_87_dialog_content = "¿No prometimos ir juntos a Lumopolis?",
  ui_story_5004_50042401_88_dialog_content = "Espera...",
  ui_story_5004_50042401_89_dialog_content = "Vuelve. Es peligroso allá.",
  ui_story_5004_50042401_90_dialog_content = "Los cristales parpadean sin parar... No me gusta esto.",
  ui_story_5004_50042401_91_dialog_content = "¡Cuidado, los cristales van a estallar!",
  ui_story_5004_50042401_92_dialog_content = "¡Cuidado, PlayerName!",
  ui_story_5004_50042401_93_dialog_content = "¡Pequeña Beryl!",
  ui_story_5004_50042401_95_dialog_content = "¡...!",
  ui_story_5004_50042401_96_dialog_content = "¡Beryl!",
  ui_story_5004_50042401_97_dialog_content = "¿Raphaela?",
  ui_story_5004_50042401_98_dialog_content = "¡Toma mi mano!",
  ui_story_5004_50042401_99_dialog_content = "¡Okay...!",
  ui_story_5004_50042401_100_dialog_content = "Lo siento... Todo esto es por mi culpa...",
  ui_story_5004_50042401_101_dialog_content = "Incluso para un ángel de la guarda como tú, Raphaela... No puedes sobrevivir a una caída desde esta altura.",
  ui_story_5004_50042401_102_dialog_content = "Quiero ver Lumopolis... contigo...",
  ui_story_5004_50042401_103_dialog_content = "<size=45>¿QUÉ DIJISTE?</size>",
  ui_story_5004_50042401_104_dialog_content = "¿Ves Lumopolis... contigo?",
  ui_story_5004_50042401_105_dialog_content = "<size=45>¡NO, ANTES DE ESO!</size>",
  ui_story_5004_50042401_106_dialog_content = "¿Incluso para un ángel de la guarda como tú...?",
  ui_story_5004_50042401_107_dialog_content = "Todos los misiles disparan... Grr... Pilar de bendición listo... ¡Máximo poder!",
  ui_story_5004_50042401_108_dialog_content = "<size=45>¡LOS ÁNGELES VUELAN, BERYL!</size>",
  ui_story_5004_50042401_109_dialog_content = "¡Espera, Beryl! ¡Casi nos quedamos sin energía!",
  ui_story_5004_50042401_110_dialog_content = "¡Déjame ir, Raphaela! No puede sostenernos a los dos. Vamos a...",
  ui_story_5004_50042401_111_dialog_content = "¡Para!",
  ui_story_5004_50042401_112_dialog_content = "¡Nunca, jamás lo dejaré ir!",
  ui_story_5004_50042401_113_dialog_content = "<color=#e8d9bb>¡Clac, clac!</color>",
  ui_story_5004_50042401_114_dialog_content = "(¿Casi al límite?)",
  ui_story_5004_50042401_115_dialog_content = "<size=50><color=#e8d9bb>¡BOOM!</color></size>",
  ui_story_5004_50042401_116_dialog_content = "Despierta, Raphaela, despierta...",
  ui_story_5004_50042401_117_dialog_content = "Beryl...",
  ui_story_5004_50042401_118_dialog_content = "¿Estás bien, Beryl?",
  ui_story_5004_50042401_119_dialog_content = "Estoy bien.",
  ui_story_5004_50042401_120_dialog_content = "Gracias...",
  ui_story_5004_50042401_121_dialog_content = "Me alegra ver que estás bien. Lo hiciste bien.",
  ui_story_5004_50042401_123_dialog_content = "Quedémonos tranquilos hasta que PlayerName venga por nosotros.",
  ui_story_5004_50042401_124_dialog_content = "Raphaela, ¿eso es...?",
  ui_story_5004_50042401_125_dialog_content = "¡Grrr!",
  ui_story_5004_50042401_126_dialog_content = "Gah... ¡Gah...!",
  ui_story_5004_50042401_127_dialog_content = "Eclipsites... muchos de ellos.",
  ui_story_5004_50042401_128_dialog_content = "¿Puedes pelear, Beryl?",
  ui_story_5004_50042401_129_dialog_content = "¡Sí!",
  ui_story_5004_50042401_130_dialog_content = "(Esperemos que llegue pronto, PlayerName...)",
  ui_story_5004_50042501_1_dialog_content = "¡Llévanos al fondo, Bonacie!",
  ui_story_5004_50042501_2_dialog_content = "Entiendo. Por aquí, y manténganse cerca a menos que quieran que los monstruos los atrapen, ¿no?",
  ui_story_5004_50042501_2X1_dialog_content = "Debemos obtener el Movimiento lo antes posible para Bonacie.",
  ui_story_5004_50042501_2X2_dialog_content = "Luego haz que consiga el Celestita para abrirlo, para que podamos jugarlo para despertar al Monarca Desolado.",
  ui_story_5004_50042501_2X3_dialog_content = "Lord Prinny, pasamos por todos los problemas para albergar al Soberano del Océano y desviar la energía de los aurorians.",
  ui_story_5004_50042501_2X4_dialog_content = "Y ahora tenemos que engañar a la Celestita para que retire el sello, luego hacer que Bonacie toque la melodía...",
  ui_story_5004_50042501_2X5_dialog_content = "¿Estás seguro de que despertará a ese tipo Monarca? ¿Qué hay para nosotros?",
  ui_story_5004_50042501_2X6_dialog_content = "Esta es una orden de uno de los Ocho Espectros. Escuché que el Monarca es una Eclipsite increíblemente poderosa.",
  ui_story_5004_50042501_2X7_dialog_content = "Si despierta, ¡podemos deshacernos de esos molestos aurorians con certeza!",
  ui_story_5004_50042501_2X8_dialog_content = "Espero. Está muy oscuro... Oye, ¿por qué te detuviste de repente?",
  ui_story_5004_50042501_2X9_dialog_content = "Escuché sonidos de batalla. ¡Cubrámonos!",
  ui_story_5004_50042501_3_dialog_content = "Deberíamos estar bien escondidos aquí.",
  ui_story_5004_50042501_4_dialog_content = "No esperaba encontrar una cueva, pero está oscuro...",
  ui_story_5004_50042501_5_dialog_content = "¡Grrr!",
  ui_story_5004_50042501_6_dialog_content = "Uf, ¿`terminaron estos molestos Eclipsites?",
  ui_story_5004_50042501_7_dialog_content = "¿Cómo estás, Beryl?",
  ui_story_5004_50042501_8_dialog_content = "Resoplan... Estoy bien. Todavía puedo pelear...",
  ui_story_5004_50042501_10_dialog_content = "¡Gah!",
  ui_story_5004_50042501_11_dialog_content = "¡Rugido!",
  ui_story_5004_50042501_12_dialog_content = "¡Maldición, bloquearon el camino!",
  ui_story_5004_50042501_13_dialog_content = "¡Escoria irritante!",
  ui_story_5004_50042501_14_dialog_content = "¡Raphaela, Beryl!",
  ui_story_5004_50042501_15_dialog_content = "¿Están bien?",
  ui_story_5004_50042501_16_dialog_content = "¡Eres muy lento, PlayerName!",
  ui_story_5004_50042501_17_dialog_content = "¿Cómo pudiste hacer que las mujeres esperaran tanto?",
  ui_story_5004_50042501_18_dialog_content = "Lo siento. ¿Por qué no lo sacamos en los Eclipsites?",
  ui_story_5004_50042601_1_dialog_content = "Uf, eso finalmente terminó.",
  ui_story_5004_50042601_2_dialog_content = "Raphaela, Beryl, ¿están heridas?",
  ui_story_5004_50042601_3_dialog_content = "Estamos bien. ¡La pequeña Beryl no saldrá herida mientras yo esté cerca!",
  ui_story_5004_50042601_4_dialog_content = "Sí... Tengo a Raphaela protegiéndome ...",
  ui_story_5004_50042601_5_dialog_content = "Ya que todo está bien, volvamos al hotel.",
  ui_story_5004_50042601_6_dialog_content = "Raphaela, yo y otros aurorians del Colossus ayudaremos a resolver las pesadillas de Beryl.",
  ui_story_5004_50042601_7_dialog_content = "Eso es correcto. Genevieve lo sabe todo, seguro que te ayudará.",
  ui_story_5004_50042601_8_dialog_content = "Oye, ¿por qué me lo pones? Solo estoy aquí para ayudar con la pelea.",
  ui_story_5004_50042601_9_dialog_content = "Tsk. Bien, conozco a un experto en minerales. Le preguntaré.",
  ui_story_5004_50042601_10_dialog_content = "Entonces regresemos y despeguemos hacia Lumopolis.",
  ui_story_5004_50042601_11_dialog_content = "¿Te importaría llevarnos de regreso, Bonacie?",
  ui_story_5004_50042601_12_dialog_content = "¿Bonacie?",
  ui_story_5004_50042601_13_dialog_content = "Espera un minuto, creo que encontré un botón.",
  ui_story_5004_50042601_14_dialog_content = "Je.",
  ui_story_5004_50042601_15_dialog_content = "Es tan brillante... ¿Qué es este lugar?",
  ui_story_5004_50042601_16_dialog_content = "(¿Por qué todo se mira tan familiar? ¿Estoy viendo cosas?)",
  ui_story_5004_50042601_17_dialog_content = "¡Oh no, PlayerName, el camino está bloqueado!",
  ui_story_5004_50042601_18_dialog_content = "¿Qué?",
  ui_story_5004_50042601_19_dialog_content = "No, no puedo moverlo.",
  ui_story_5004_50042601_20_dialog_content = "Locales... bloqueados... <size=35>Reinicie...</size> <size=33>el sistema...</size>",
  ui_story_5004_50042601_21_dialog_content = "¿...?",
  ui_story_5004_50042601_22_dialog_content = "¡Todos, veamos si podemos abrir la puerta por completo!",
  ui_story_5004_50042601_23_dialog_content = "No se mueve y todos nuestros ataques no hacen mella.",
  ui_story_5004_50042601_24_dialog_content = "¿No crees que esto se siente como el interior de Colossus, PlayerName?",
  ui_story_5004_50042601_25_dialog_content = "Sí, lo hace, pero ¿cómo es posible? Oye, ¿dónde está Bonacie?",
  ui_story_5004_50042601_26_dialog_content = "Dónde, dónde...",
  ui_story_5004_50042601_27_dialog_content = "Mi preciosa, mi amor, mi todo...",
  ui_story_5004_50042601_28_dialog_content = "¿Dónde lo escondieron esos estúpidos Eclipsites?",
  ui_story_5004_50042601_29_dialog_content = "Sí, <size=45>¡premio mayor!</size>",
  ui_story_5004_50042601_29X1_dialog_content = "Oye, ¿por qué están ustedes dos aquí?",
  ui_story_5004_50042601_29X2_dialog_content = "¡Shhh, no dejes que los aurorianos lo escuchen!",
  ui_story_5004_50042601_29X3_dialog_content = "Vamos a tomar el Movimiento y dárselo.",
  ui_story_5004_50042601_29X4_dialog_content = "¿Quiere decir que el Movimiento está dentro de esta... cosa?",
  ui_story_5004_50042601_29X5_dialog_content = "Si. Recuerda, debes conseguir el Celestita...",
  ui_story_5004_50042601_29X6_dialog_content = "Haz que el Celestita quite el sello, ¿no? Lo se.",
  ui_story_5004_50042601_29X7_dialog_content = "Ahora que tengo la segunda mitad, ustedes dos pueden descansar un poco, ¿no?",
  ui_story_5004_50042601_29X8_dialog_content = "¡Cuidado, Lord Prinny!",
  ui_story_5004_50042601_29X9_dialog_content = "<color=#e8d9bb>¡BOOM!</color>",
  ui_story_5004_50042601_29X10_dialog_content = "Luego arrastró los cuerpos a un rincón oscuro... ¡Si perfecto!",
  ui_story_5004_50042601_30_dialog_content = "<size=45>¡PlayerName! ¿Sigues ahí?</size>",
  ui_story_5004_50042601_31_dialog_content = "Estamos encerrados, ¿dónde más podemos estar? ¿A dónde fuiste?",
  ui_story_5004_50042601_32_dialog_content = "Encontré <color=#FFB400>algo interesante</color>, ¡ven a verlo!",
  ui_story_5004_50042601_33_dialog_content = "¿Qué es?",
  ui_story_5004_50042601_34_dialog_content = "¿Se siente esto como una <color=#FFB400>creación de Celestita</color>?",
  ui_story_5004_50042601_35_dialog_content = "Sé que lo reconocerías, ¿no?",
  ui_story_5004_50042601_36_dialog_content = "Esta es una creación Celestita y estamos en un lugar que se asemeja al interior de un Colossus... ¿Eso significa que estamos en un Colossus?",
  ui_story_5004_50042601_37_dialog_content = "¿Cómo puedo saberlo? Soy un simple músico y presentador, ¿no?",
  ui_story_5004_50042601_38_dialog_content = "Descendiente... a quien espero...",
  ui_story_5004_50042601_39_dialog_content = "(Ahí está de nuevo).",
  ui_story_5004_50042601_40_dialog_content = "¿Qué tal si usas tus habilidades psíquicas, PlayerName?",
  ui_story_5004_50042601_41_dialog_content = "Tengo un mal presentimiento sobre esto, PlayerName.",
  ui_story_5004_50042601_42_dialog_content = "Estamos atrapados. ¿Qué más podemos hacer?",
  ui_story_5004_50042601_43_dialog_content = "De acuerdo, ten cuidado.",
  ui_story_5004_50042601_44_dialog_content = "El descendiente... a quien espero...",
  ui_story_5004_50042601_45_dialog_content = "Si quieres aprovechar el <color=#FFB400>Movimiento</color>... debes...",
  ui_story_5004_50042601_46_dialog_content = "No convocarlo...",
  ui_story_5004_50042601_47_dialog_content = "No dejes... destruir la tierra...",
  ui_story_5004_50042601_48_dialog_content = "¡Oye, la puerta está abierta!",
  ui_story_5004_50042701_49_dialog_content = "Gracias por encontrar el mecanismo. Me cansé de patear esa estúpida puerta.",
  ui_story_5004_50042701_50_dialog_content = "¿Qué sacaste de la caja, Bonacie?",
  ui_story_5004_50042701_51_dialog_content = "¿Es eso algún tipo de movimiento en tu mano?",
  ui_story_5004_50042701_52_dialog_content = "¿Lo reconoces, PlayerName? Esta es una parte del Movimiento Divino que he estado buscando.",
  ui_story_5004_50042701_53_dialog_content = "(Así que la voz que escuché se refería a esto).",
  ui_story_5004_50042701_54_dialog_content = "¿Cómo sabes que está aquí? ¿Y de dónde vienen los Eclipsites?",
  ui_story_5004_50042701_55_dialog_content = "Evidentemente, estaban protegiendo al Movimiento.",
  ui_story_5004_50042701_56_dialog_content = "Oh, Celestita. Muy astuto, ¿no?",
  ui_story_5004_50042701_57_dialog_content = "Tienes razón, hice un pequeño trato con los Eclipsites.",
  ui_story_5004_50042701_58_dialog_content = "¿Trataste con los Eclipsites?",
  ui_story_5004_50042701_59_dialog_content = "¿Y qué? No es una asociación y no cometí ninguna mala acción por ellos, ¿no?",
  ui_story_5004_50042701_60_dialog_content = "Me entregan el Movimiento que quiero y me aseguro de que el Soberano del Océano sea un éxito.",
  ui_story_5004_50042701_61_dialog_content = "¿El Soberano del Océano? ¿Es parte de una trama de Eclipsite?",
  ui_story_5004_50042701_62_dialog_content = "Eso no lo sé ni me importa. La voz en mi cabeza y el Movimiento son mucho más importantes, ¿no?",
  ui_story_5004_50042701_63_dialog_content = "¿Eres una especie de músico loco? ¡Oh, espera, lo eres!",
  ui_story_5004_50042701_64_dialog_content = "Ahora que lo tienes, ¿qué vas a hacer? ¿Seguirás colaborando con Eclipsites?",
  ui_story_5004_50042701_65_dialog_content = "Te dije que no era una sociedad, ¿no? ¡Fueron beneficios mutuos! ¡Estaba planeando dártelo, PlayerName!",
  ui_story_5004_50042701_66_dialog_content = "¿Dármelo? ¿Después de todo lo que pasaste?",
  ui_story_5004_50042701_67_dialog_content = "Bueno, es el <color=#FFB400>gran premio</color> del Soberano del Océano, después de todo.",
  ui_story_5004_50042701_68_dialog_content = "Te oculté secretos, así que lo llamaremos par, ¿no? Pero primero tengo que jugarlo antes de dárselo.",
  ui_story_5004_50042701_69_dialog_content = "Eso suena como si estuviera recibiendo el primer bocado del fruto del trabajo de todos.",
  ui_story_5004_50042701_70_dialog_content = "Bueno, todos somos amigos, ¿no? Mira esto...",
  ui_story_5004_50042701_71_dialog_content = "¿Otro partido idéntico?",
  ui_story_5004_50042701_72_dialog_content = "Por supuesto. Necesitas unir los dos para formar un todo. Siempre es así, ¿no?",
  ui_story_5004_50042701_73_dialog_content = "Oh...",
  ui_story_5004_50042701_74_dialog_content = "¿Eso es todo? ¿Un destello?",
  ui_story_5004_50042701_75_dialog_content = "¿Qué está pasando?",
  ui_story_5004_50042701_76_dialog_content = "Puedo sentir algún tipo de energía en él, pero está retenida.",
  ui_story_5004_50042701_77_dialog_content = "(¿No funciona? Supongo que debería probar lo que <color=#FFB400>dijo esa rata</color>...)",
  ui_story_5004_50042701_78_dialog_content = "Pruébelo, PlayerName. Haz algo, usa tus habilidades psíquicas tal vez, ¿no?",
  ui_story_5004_50042701_79_option_content = "Para nada.",
  ui_story_5004_50042701_80_dialog_content = "¡No quiero tocar nada de un trato con los Eclipsites!",
  ui_story_5004_50042701_81_dialog_content = "Bien, bien, ¡te juro que nunca volveré a hacer un trato con Eclipsites!",
  ui_story_5004_50042701_82_option_content = "Si me lo dan...",
  ui_story_5004_50042701_83_dialog_content = "¡Aún no!",
  ui_story_5004_50042701_84_dialog_content = "¡Mi instinto me dice que esto es algo peligroso!",
  ui_story_5004_50042701_85_dialog_content = "¿Qué tan peligroso puede ser? Tenemos a todos aquí, ¿no? ¡Vamos por favor!",
  ui_story_5004_50042701_86_option_content = "Tú... Bien, lo intentaré.",
  ui_story_5004_50042701_87_dialog_content = "Escuché una voz advirtiéndome que no rompiera ningún sello.",
  ui_story_5004_50042701_88_dialog_content = "Debes haber escuchado mal, ¿no? ¿Vamos por favor?",
  ui_story_5004_50042701_89_dialog_content = "¿Juras no volver a hacer un trato con Eclipsites nunca más?",
  ui_story_5004_50042701_90_dialog_content = "Bien, bien, lo juro, ¡nunca más!",
  ui_story_5004_50042701_91_dialog_content = "...",
  ui_story_5004_50042701_92_option_content = "Activar la telepatía",
  ui_story_5004_50042701_93_dialog_content = "¿Funcionó?",
  ui_story_5004_50042701_94_dialog_content = "Maravilloso.",
  ui_story_5004_50042701_95_dialog_content = "Gracias, PlayerName...",
  ui_story_5004_50042701_96_dialog_content = "¡¿Qué estás haciendo, Bonacie?!",
  ui_story_5004_50042701_97_dialog_content = "¡Oh, qué maravilloso! Siento su llamada ahora que el sello se ha ido...",
  ui_story_5004_50042701_98_dialog_content = "Lo siento, PlayerName.",
  ui_story_5004_50042701_99_dialog_content = "¡Mi propósito de estar aquí, el propósito de mi existencia, es únicamente tocar la Melodía Divina!",
  ui_story_5004_50042701_100_dialog_content = "¿Qué es esta energía siniestra que siento?",
  ui_story_5004_50042701_101_dialog_content = "¡Bonacie!",
  ui_story_5004_50042701_102_dialog_content = "¡Jajaja!",
  ui_story_5004_50042701_103_dialog_content = "¡Qué hermoso ritmo! Más allá de la perfección, ¿no?",
  ui_story_5004_50042701_104_dialog_content = "No... Soy impotente...",
  ui_story_5004_50042701_105_dialog_content = "¡No escuches la música!",
  ui_story_5004_50042701_106_dialog_content = "¡Basta, Bonacie!",
  ui_story_5004_50042701_107_dialog_content = "Recoger el Movimiento del Vacío es el mayor honor que me otorgó la voz.",
  ui_story_5004_50042701_108_dialog_content = "Es indignante pedirme que pare, ¿no?",
  ui_story_5004_50042701_112_dialog_content = "¿La energía proviene de Bonacie? ¡No, está saliendo del Movimiento antes que ella!",
  ui_story_5004_50042701_113_dialog_content = "¡Oye, mira hacia allá!",
  ui_story_5004_50042701_114_dialog_content = "¿Es un castillo que se eleva del mar?",
  ui_story_5004_50042701_115_dialog_content = "El castillo... Pero, ¿cómo puede ser esto...",
  ui_story_5004_50042701_116_dialog_content = "Escúchalo, PlayerName, ritmo estremecedor, ¿no?",
  ui_story_5004_50042701_117_dialog_content = "Ustedes, los Celestitas... por supuesto que su raza se guardaría esta hermosa música para ustedes, ¿no? ¡No hay razón para compartirlo con el mundo mundano!",
  ui_story_5004_50042701_118_dialog_content = "Bien hecho, ¿no? ¡Estoy empezando a apreciarte más, Celestitas!",
  ui_story_5004_50042701_119_dialog_content = "Esta es la voz de La Verdad, el sonido de la divinidad.",
  ui_story_5004_50042701_120_dialog_content = "¡Están resonando en mi mente, PlayerName!",
  ui_story_5004_50042701_121_dialog_content = "Sal de ahí, Beryl. ¡PlayerName! ¡Algo brilla sobre Bonacie!",
  ui_story_5004_50042701_122_dialog_content = "¡Es un meteorito y se dirige hacia nosotros!",
  ui_story_5004_50042701_123_dialog_content = "¿De dónde vino ese meteorito?",
  ui_story_5004_50042701_124_dialog_content = "¡Cuidado, se estrella hacia aquí!",
  ui_story_5004_50042701_125_dialog_content = "¡Dominio de cristal!",
  ui_story_5004_50042701_126_dialog_content = "¡Uh!",
  ui_story_5004_50042701_127_dialog_content = "¿Estás bien?",
  ui_story_5004_50042701_128_dialog_content = "Sí, acaba de ser derribado por la ola, eso es todo. Afortunadamente, tenemos Beryl...",
  ui_story_5004_50042701_129_dialog_content = "¡Se acerca otro meteorito más grande!",
  ui_story_5004_50042701_130_dialog_content = "Le daré todo lo que tengo.",
  ui_story_5004_50042701_131_dialog_content = "(¡No, un meteorito de ese tamaño es más de lo que podemos manejar!)",
  ui_story_5004_50042701_132_dialog_content = "Es este el final...",
  ui_story_5004_50042701_133_dialog_content = "No te rindas tan pronto, PlayerName.",
  ui_story_5004_50042701_134_dialog_content = "¡Esa voz!",
  ui_story_5004_50042701_135_dialog_content = "¡Sí, es tu leal amigo mecánico y su amigo Brock!",
  ui_story_5004_50042701_136_dialog_content = "¡Siéntese y disfrute del poder del Rediesel Steel MkV Cero, PlayerName!",
  ui_story_5004_50042701_137_dialog_content = "¡Ohhhhh!",
  ui_story_5004_50042701_138_dialog_content = "¡Deja de gritar! ¡Estás actuando cien veces más loco de lo habitual!",
  ui_story_5004_50042701_139_dialog_content = "Tira hacia arriba. ¡Seguirá funcionando aún mejor!",
  ui_story_5004_50042701_140_dialog_content = "¿Tirar qué? ¡Olvídalo, tiro de cada uno de ellos!",
  ui_story_5004_50042701_141_dialog_content = "¡Eso es! ¡Ilumina mi vida!",
  ui_story_5004_50042701_142_dialog_content = "Oye, ¿qué significa que la luz esté parpadeando?",
  ui_story_5004_50042701_143_dialog_content = "¡Es la advertencia de sobrecarga!",
  ui_story_5004_50042701_144_dialog_content = "Entonces, ¿qué va a pasar?",
  ui_story_5004_50042701_145_dialog_content = "¡Explotará en 30 segundos!",
  ui_story_5004_50042701_146_dialog_content = "Bueno, Rediesel Acero MkV, ¡arde conmigo hasta el final!",
  ui_story_5004_50042701_147_dialog_content = "¡Derriba el meteorito de su trayectoria!",
  ui_story_5004_50042701_148_dialog_content = "¡No tienes que rechazarlo!",
  ui_story_5004_50042701_149_dialog_content = "¡Fleur!",
  ui_story_5004_50042701_150_dialog_content = "¡Entendido!",
  ui_story_5004_50042701_151_dialog_content = "Maldito meteorito...\n¡Lárgate <size=45>de aquí!</size>",
  ui_story_5004_50042701_152_dialog_content = "(¡Las chispas del propulsor son cegadoras!)",
  ui_story_5004_50042701_153_dialog_content = "¡Éxito, PlayerName! ¡El meteorito está fuera de curso!",
  ui_story_5004_50042701_154_dialog_content = "¿Seguro de que no hay problema? ¡Por lo que sé, el robot está a punto de sobrecargarse y desmoronarse!",
  ui_story_5004_50042701_157_dialog_content = "¡Deja de jugar con tu pulgar, PlayerName! ¡Aléjate de la playa!",
  ui_story_5004_50042701_158_dialog_content = "¡¡Vienen las olas!!",
  ui_story_5004_50042701_159_dialog_content = "¡Tengo las rodillas de goma, gracias a Bonacie!",
  ui_story_5004_50042701_160_dialog_content = "¡Toma mi mano, PlayerName!",
  ui_story_5004_50042701_161_dialog_content = "Hipocresía... ¡Es muy tarde!",
  ui_story_5004_50042701_162_dialog_content = "¿Estás bien, PlayerName?",
  ui_story_5004_50042701_163_dialog_content = "¿Es este el que tiene la tecnología Celestita del que hablaste?",
  ui_story_5004_50042701_164_dialog_content = "Si. Está integrado con la tecnología Celestita, ¡y es el robot más poderoso!",
  ui_story_5004_50042701_165_dialog_content = "Lamentablemente, sin embargo, las partes con tecnología Celestita sufrieron daños severos al derribar el meteorito.",
  ui_story_5004_50042701_166_dialog_content = "Te refieres a los propulsores inconcebibles, ¿verdad?",
  ui_story_5004_50042701_167_dialog_content = "Ya sea que sea Illumina o Lumopolis, ¡todos le deben a Brock uno grande hoy!",
  ui_story_5004_50042701_168_dialog_content = "Recuerda votar por mí en las próximas elecciones para el jefe de Rediesel Wrench, ¡me escuchas!",
  ui_story_5004_50042701_169_dialog_content = "Brock no cambia... Oye, ¿dónde está Bonacie?",
  ui_story_5004_50042701_170_dialog_content = "¡Que agradable! ¡Me siento bien!",
  ui_story_5004_50042701_171_dialog_content = "Wow, ¿de dónde vienes?",
  ui_story_5004_50042701_172_dialog_content = "Estuve cerca, incluso los seguí cuando golpeó la gran ola, simplemente no se dieron cuenta, ¿no?",
  ui_story_5004_50042701_173_dialog_content = "Aquí tienes, el Movimiento.",
  ui_story_5004_50042701_174_dialog_content = "Eso fue fácil... Espera, ¿qué tienes ahora bajo la manga?",
  ui_story_5004_50042701_175_dialog_content = "Nada, ya que mi objetivo era jugarlo y ya está.",
  ui_story_5004_50042701_176_dialog_content = "Por esa vez estará grabado para siempre en mi alma, así que no es necesario que me lo quede.",
  ui_story_5004_50042701_177_dialog_content = "Sin mencionar que es propiedad de Celestita, por lo que es lo correcto para que la conserve.",
  ui_story_5004_50042701_178_dialog_content = "No te preocupes, no volveré a jugarlo, así que perdóname, ¿no?",
  ui_story_5004_50042701_179_dialog_content = "(¿Y crees que te estás saliendo del anzuelo así?)",
  ui_story_5004_50042701_180_dialog_content = "Esta cosa peligrosa debe guardarse en un lugar seguro.",
  ui_story_5004_50042701_181_dialog_content = "Dejarlo solo atrae a alguien más a explotarlo.",
  ui_story_5004_50042701_182_dialog_content = "Estás en lo correcto. Lo aceptaré, ¡pero esto no significa que te salgas de la cárcel!",
  ui_story_5004_50042701_183_dialog_content = "¡Elaborarás tu trato con los Eclipsites!",
  ui_story_5004_50042801_E1_dialog_content = "¡Así que eso es todo, lo juro!",
  ui_story_5004_50042801_E2_dialog_content = "¿Entonces los ayudaste con el Soberano del Océano solo para tener en tus manos el Movimiento?",
  ui_story_5004_50042801_E3_dialog_content = "¡Eso es correcto! ¡Absolutamente correcto!",
  ui_story_5004_50042801_E4_dialog_content = "Okay...",
  ui_story_5004_50042801_E5_dialog_content = "Por fin estás despierto, mi señor...",
  ui_story_5004_50042801_E6_dialog_content = "¿Qué es eso? ¿Deseas conocer a los guerreros que te despertaron?",
  ui_story_5004_50042801_E7_dialog_content = "Esperen, ¿escuchan eso? Entra y sale de mis oídos.",
  ui_story_5004_50042801_E8_dialog_content = "Okey, okey. Je, creo que ellos también se mueren por conocerte...",
  ui_story_5004_50042801_E9_dialog_content = "Pero aún no estás en plena forma, así que permíteme ayudarte.",
  ui_story_5004_50042801_E10_dialog_content = "¿Escuchar qué? Mi mente todavía está llena de esa melodía... ¡Pero siento Darkflow volverse denso!",
  ui_story_5004_50042801_E11_dialog_content = "¿De dónde viene? ¡No lo sentí hace un segundo!",
  ui_story_5004_50042801_E12_dialog_content = "<color=#e8d9bb>\"La música se reproduce, terminando la búsqueda. El Monarca despierta, solo para incinerar las estrellas, otorgando fatalidad y furia a todos.\"</color>",
  ui_story_5004_50042801_E13_dialog_content = "...",
  ui_story_5004_50042801_184_dialog_content = "¡Gahhhhhh!",
  ui_story_5004_50042801_185_dialog_content = "¿Son los Eclipsites que huyeron de la batalla?",
  ui_story_5004_50042801_186_dialog_content = "¡No son...!",
  ui_story_5004_50042802_1_dialog_content = "Poderoso... Mucho más allá de los típicos Eclipsites.",
  ui_story_5004_50042802_2_dialog_content = "¿De dónde salieron? Nunca había visto nada como ellos antes.",
  ui_story_5004_50042802_3_dialog_content = "Por suerte, están derrotados. Ya no pueden hacer el mal.",
  ui_story_5004_50042802_4_dialog_content = "No, pueden ser clones.",
  ui_story_5004_50042802_5_dialog_content = "Sentí que otra fuerza mucho más fuerte los controlaba durante la batalla.",
  ui_story_5004_50042802_6_dialog_content = "Y la fuente de ese poder está en ese castillo.",
  ui_story_5004_50042802_7_dialog_content = "(Estaba tan distraído que casi me olvido por completo de ese castillo súper exótico.)",
  ui_story_5004_50042802_8_dialog_content = "(Pero ahora puedo sentir fácilmente un Darkflow cada vez más aterrador.)",
  ui_story_5004_50042802_9_dialog_content = "Tsk. ¿Esos Eclipsites hicieron eso? Qué complicado...",
  ui_story_5004_50042802_10_dialog_content = "Con razón conseguí el Movimiento tan fácil. ¡Están usando PlayerName y mis poderes para convocar a esa monstruosidad!",
  ui_story_5004_50042802_11_dialog_content = "Veo que Soberano del Océano no es una estafa para hacer dinero. ¡Esa maldita rata tiene todo esto planeado!",
  ui_story_5004_50042802_12_dialog_content = "¡Voy a darles una paliza y tomar el Movimiento la próxima vez!",
  ui_story_5004_50042802_13_dialog_content = "¿Estafa para hacer dinero? ¿Qué necesitan las Eclipsites con dinero?",
  ui_story_5004_50042802_14_dialog_content = "Dijeron que van a exprimir hasta el último centavo de los Aurorians y convertirlos en pobres, por lo que tendrán que trabajar y no podrán permitirse el lujo de defenderse...",
  ui_story_5004_50042802_15_dialog_content = "Mi atención estaba únicamente en el Movimiento y nada más.",
  ui_story_5004_50042802_16_dialog_content = "Deberíamos investigar ese castillo y sus enemigos, PlayerName.",
  ui_story_5004_50042802_17_dialog_content = "Carleen tiene razón. Si no lo hacemos, todo el mundo en la playa puede estar en peligro, y tal vez peor.",
  ui_story_5004_50042802_18_dialog_content = "Estamos aquí, no podemos dejar que los Eclipsites nos asusten.",
  ui_story_5004_50042802_19_dialog_content = "Son solo Eclipsites buenos para recompensas.",
  ui_story_5004_50042802_20_dialog_content = "Sí, me gustaría ir también... Tengo curiosidad por ese castillo...",
  ui_story_5004_50042802_21_dialog_content = "Si Beryl se va, yo también.",
  ui_story_5004_50042802_22_dialog_content = "¿Por qué me miras? ¡Es mi trabajo garantizar la seguridad de la playa como Jefe de Seguridad!",
  ui_story_5004_50042802_23_dialog_content = "¡Rediesel Acero Mark V-Zero transportará a todos!",
  ui_story_5004_50042802_24_dialog_content = "Supongo que contribuiré y arreglaré el robot con piezas preciosas y una fuente de energía de mi escondite.",
  ui_story_5004_50042802_25_dialog_content = "¡A patearles el trasero por atreverse a explotarme!",
  ui_story_5004_50042802_26_dialog_content = "Bien, ¡vamos entonces!",
  ui_story_5004_50042901_1_dialog_content = "¿Aguantaría el MkV, Fleur?",
  ui_story_5004_50042901_2_dialog_content = "¡Eso es Rediesel Steel MkV Cero!",
  ui_story_5004_50042901_3_dialog_content = "¡Adoptó la tecnología a propulsión Colossus y acaba de cargarse con la fuente de energía de la señorita Bonacie!",
  ui_story_5004_50042901_4_dialog_content = "Supongo que está decidida a ajustar cuentas con los Eclipsites que la usaron.",
  ui_story_5004_50042901_5_dialog_content = "Tecnología Colossus, ¿dijiste? ¿Perderá poder como Soroz?",
  ui_story_5004_50042901_6_dialog_content = "¡Ten cuidado, Fleur, no vueles tan alto!",
  ui_story_5004_50042901_7_dialog_content = "¿Ah, por qué?",
  ui_story_5004_50042901_8_dialog_content = "¿¿¿Eh???",
  ui_story_5004_50042901_9_dialog_content = "¿Qué está pasando? ¡Las lecturas vacilan entre los dos extremos!",
  ui_story_5004_50042901_10_dialog_content = "¿Qué pasa, Fleur?",
  ui_story_5004_50042901_11_dialog_content = "Nada. Los instrumentos están mal funcionando...",
  ui_story_5004_50042901_12_dialog_content = "¿Solo los instrumentos?",
  ui_story_5004_50042901_13_dialog_content = "¡Nos estrellamos! ¡Sabía que este trozo de acero no era confiable!",
  ui_story_5004_50042901_14_dialog_content = "¡Mi Rediesel Acero MkV Cero nunca se estrellará!",
  ui_story_5004_50042901_15_dialog_content = "¡Está estrellándose! ¡Rápido, haz algo!",
  ui_story_5004_50042901_16_dialog_content = "¡Planearemos hasta el castillo! ¡Esperen, todos!",
  ui_story_5004_50042901_17_dialog_content = "¡Ni loco! Nos estrellaremos...",
  ui_story_5004_50042901_18_dialog_content = "¡Cálmate, ten fe en la tecnología Rediesel Wrench!",
  ui_story_5004_50042901_19_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5004_50042901_20_dialog_content = "PlayerName.",
  ui_story_5004_50042901_21_dialog_content = "Despierta, PlayerName.",
  ui_story_5004_50042901_22_dialog_content = "Oh, mi cabeza...",
  ui_story_5004_50042901_23_dialog_content = "¿Vice?",
  ui_story_5004_50042901_24_dialog_content = "Finalmente has vuelto en sí. Estabas inconsciente.",
  ui_story_5004_50042901_25_dialog_content = "¿Dónde estamos? ¿Chocamos contra el castillo?",
  ui_story_5004_50042901_26_dialog_content = "No tenemos idea, pero este lugar parece... muy inusual. El Darkflow aquí es sofocante.",
  ui_story_5004_50042901_27_dialog_content = "Y mira todas las imágenes que flotan alrededor. Están animados como si estuvieran vivos.",
  ui_story_5004_50042901_28_dialog_content = "¿Ves ese globo ocular en la imagen?",
  ui_story_5004_50042901_29_dialog_content = "Nos siguió y me está dando escalofríos.",
  ui_story_5004_50042901_30_dialog_content = "Beryl, esa foto de ahí, ¿está haciendo malabares con limones?",
  ui_story_5004_50042901_31_dialog_content = "Aparentemente si...",
  ui_story_5004_50042901_32_dialog_content = "¡Mira hacia allá, PlayerName!",
  ui_story_5004_50042901_33_dialog_content = "¡Eso es Soroz! ¿Cómo llegó está aquí?",
  ui_story_5004_50042901_34_dialog_content = "Tengo que echar un vistazo.",
  ui_story_5004_50042901_35_dialog_content = "Que rayos... ¿Cómo quedó esta losa debajo de mis pies?",
  ui_story_5004_50042901_36_dialog_content = "¿Eres tú, Soroz?",
  ui_story_5004_50042901_37_dialog_content = "Maldición, no puedo acercarme a él sin importar lo rápido que camine.",
  ui_story_5004_50042901_38_dialog_content = "Movamos lento, PlayerName.",
  ui_story_5004_50042901_39_dialog_content = "Es peligroso moverse tan rápido aquí.",
  ui_story_5004_50042901_40_dialog_content = "Está bien. ¿Tienen alguna pista?",
  ui_story_5004_50042901_41_dialog_content = "Déjame pensar... Chocamos contra el castillo y nos desmayamos.",
  ui_story_5004_50042901_42_dialog_content = "Y nos despertamos aquí, definitivamente no está dentro del castillo, probab. en una dimensión de bolsillo.",
  ui_story_5004_50042901_43_dialog_content = "Tsk. Pensé que solo pelearíamos una vez y regresaríamos.",
  ui_story_5004_50042901_44_dialog_content = "Ahora estamos atrapados sin salida.",
  ui_story_5004_50042901_45_dialog_content = "No creo que haya otras partes del Movimiento aquí.",
  ui_story_5004_50042901_46_dialog_content = "...",
  ui_story_5004_50042901_47_dialog_content = "¿Cómo estás, Beryl? Toma, úsame como apoyo.",
  ui_story_5004_50042901_48_dialog_content = "Estoy bien, gracias...",
  ui_story_5004_50042901_49_dialog_content = "Tengo una confesión que hacer...",
  ui_story_5004_50042901_50_dialog_content = "¿El castillo de arena que construí?",
  ui_story_5004_50042901_51_dialog_content = "¡Sí, ese castillo se parecía mucho a éste!",
  ui_story_5004_50042901_52_dialog_content = "¿Tienes algo, Beryl?",
  ui_story_5004_50042901_53_dialog_content = "No estoy seguro... Esta estructura siempre ha estado en mi mente.",
  ui_story_5004_50042901_54_dialog_content = "Así que supongo que la voz en mi cabeza y este lugar están conectados.",
  ui_story_5004_50042901_55_dialog_content = "Cuidado, todos... No es solo el Darkflow aquí... Hay una fuerza que me resulta muy familiar...",
  ui_story_5004_50042901_56_dialog_content = "No te preocupes, Beryl, no dejaremos que nadie te haga daño.",
  ui_story_5004_50042901_57_dialog_content = "Más tarde calcularemos mi factura como guardaespaldas. ¡Incluso te daré un descuento!",
  ui_story_5004_50042901_58_dialog_content = "¿El dinero todo lo que te importa? ¡No estás actuando como un noble, Genev!",
  ui_story_5004_50042901_59_dialog_content = "¡Cállate! ¡Estoy tratando de animarme aquí!",
  ui_story_5004_50042901_60_dialog_content = "Debemos unirnos para derrotar a los Eclipsites. Eso es algo que un fenómeno solitario como tú no entendería.",
  ui_story_5004_50042901_61_dialog_content = "Si, derrotar a los Eclipsites es la razón por la que estamos aquí.",
  ui_story_5004_50042901_62_dialog_content = "Si, estamos atrapados en una extraña ilusión ahora, ¡pero esa no es razón para rendirse!",
  ui_story_5004_50042901_63_dialog_content = "¡Correcto!",
  ui_story_5004_50042901_64_dialog_content = "Intentemos explorar los alrededores... aunque no podamos ver nada.",
  ui_story_5004_50042901_65_dialog_content = "Elijamos una dirección y sigamos con ella.",
  ui_story_5004_50042901_66_dialog_content = "Está bien. Ten cuidado.",
  ui_story_5004_50042901_67_dialog_content = "No puedo distinguir los alrededores.",
  ui_story_5004_50042901_68_dialog_content = "No es solo Soroz, sino las imágenes a su alrededor parecen algo familiares.",
  ui_story_5004_50042901_69_dialog_content = "Esa es la aguja en Lumopolis...",
  ui_story_5004_50042901_70_dialog_content = "¡Esa mujer de la foto...!",
  ui_story_5004_50042901_71_dialog_content = "¡Viles criaturas, cómo se atreven a tratar de sacudirme con la imagen de mi madre!",
  ui_story_5004_50042901_72_dialog_content = "Mantén la calma, Carleen. No caigas en sus trucos.",
  ui_story_5004_50042901_73_dialog_content = "¿Puede este lugar leer mentes?",
  ui_story_5004_50042901_74_dialog_content = "La niña de esa foto...",
  ui_story_5004_50042901_75_dialog_content = "(¿Por qué tengo ganas de tocarlo?)",
  ui_story_5004_50042901_76_option_content = "Toca la imagen",
  ui_story_5004_50042901_77_dialog_content = "¡...!",
  ui_story_5004_50042901_78_dialog_content = "(Qué humo tan intenso, y escucho un llanto familiar... ¿No es esto lo que vi cuando toqué a Beryl?)",
  ui_story_5004_50042901_79_dialog_content = "Lo siento...",
  ui_story_5004_50042901_80_dialog_content = "Lo siento, padre y madre...",
  ui_story_5004_50042901_81_dialog_content = "¿PlayerName, PlayerName?",
  ui_story_5004_50042901_82_dialog_content = "Vice...",
  ui_story_5004_50042901_83_dialog_content = "¿Por qué lloras? ¿Qué sentiste?",
  ui_story_5004_50042901_84_dialog_content = "(¿Un recuerdo de Beryl? ¿Por qué lo vi de la nada?)",
  ui_story_5004_50042901_85_dialog_content = "(¿Cuál es la conexión entre Beryl y esa imagen? Sus padres...)",
  ui_story_5004_50042901_86_dialog_content = "(No, podría ser otro truco de Eclipsite. Debería guardar silencio hasta que sepa más).",
  ui_story_5004_50042901_87_dialog_content = "Estoy bien, solo veo algunas ilusiones... Probablemente un engaño Eclipsite.",
  ui_story_5004_50042901_88_dialog_content = "Diles a que tengan cuidado con las imágenes. Pueden jugarles malas pasadas.",
  ui_story_5004_50042901_89_dialog_content = "¿Qué diablos son estos...? ¿Por qué?",
  ui_story_5004_50042901_90_dialog_content = "¿Por qué te escabulles por ahí?",
  ui_story_5004_50042901_91_dialog_content = "Las dos imágenes a tu lado somos nosotros de niños. ¿Qué están haciendo?",
  ui_story_5004_50042901_92_dialog_content = "¡No te acerques más!",
  ui_story_5004_50042901_93_dialog_content = "¡Hey! ¿Por qué lo quemaste? No tuve la oportunidad de verlo.",
  ui_story_5004_50042901_94_dialog_content = "¡Eso es porque no quiero que lo hagas!",
  ui_story_5004_50042901_95_dialog_content = "¡Gahhhh!",
  ui_story_5004_50042901_96_dialog_content = "¡Cuidado, tenemos Eclipsites!",
  ui_story_5004_50042901_97_dialog_content = "¡Gah! ¡Gah!",
  ui_story_5004_50042901_98_dialog_content = "¡Simplemente salieron de las imágenes! ¡Prepárense para luchar!",
  ui_story_5004_50043001_1_dialog_content = "Los tengo todos. ¿Soy yo o son más duros que los de la playa?",
  ui_story_5004_50043001_2_dialog_content = "Sí, mucho más duro.",
  ui_story_5004_50043001_3_dialog_content = "Y son solo clones. Darkflow no decayó ni un poco.",
  ui_story_5004_50043001_4_dialog_content = "No podemos ni encontrar los verdaderos enemigos. Esto va a ser duro.",
  ui_story_5004_50043001_5_dialog_content = "Esta es la primera vez que me encuentro con... una ilusión tan extraña.",
  ui_story_5004_50043001_6_dialog_content = "Préstame el broche de tu sombrero, Genevieve.",
  ui_story_5004_50043001_7_dialog_content = "¿Por qué? ¡No lo rompas!",
  ui_story_5004_50043001_8_dialog_content = "¡Heeyeah!",
  ui_story_5004_50043001_9_dialog_content = "¿Por qué lo arrojaste?",
  ui_story_5004_50043001_10_dialog_content = "¡Ay! ¿Cómo me golpeó la cara desde arriba?",
  ui_story_5004_50043001_11_dialog_content = "¡Las direcciones están desordenadas!",
  ui_story_5004_50043001_12_dialog_content = "¿Qué tal si lanzas tu capullo lunar, Carleen?",
  ui_story_5004_50043001_13_dialog_content = "Es mejor que dispares una flecha.",
  ui_story_5004_50043001_14_dialog_content = "Correcto...",
  ui_story_5004_50043001_15_dialog_content = "¡Espera! ¿Y si vuelve a golpearme la cara?",
  ui_story_5004_50043001_16_dialog_content = "¡Tranquila, estoy aquí! ¡Haré que un misil siga la flecha!",
  ui_story_5004_50043001_17_dialog_content = "No, ¡déjame en paz y piensa en otra idea!",
  ui_story_5004_50043001_18_dialog_content = "¿Qué tal hablar con esa imagen de la boca de allí?",
  ui_story_5004_50043001_19_dialog_content = "Olvídalo, se mira repugnante.",
  ui_story_5004_50043001_20_dialog_content = "Parece que es de otro mundo.",
  ui_story_5004_50043001_21_dialog_content = "Entonces...",
  ui_story_5004_50043001_22_dialog_content = "¿Qué tal ese?",
  ui_story_5004_50043001_23_dialog_content = "¿La misma niña? Está apuntando a la puerta detrás de ella.",
  ui_story_5004_50043001_24_dialog_content = "¿Quiere que pasemos por eso?",
  ui_story_5004_50043001_25_dialog_content = "¿Qué más podemos hacer? Ella no parece hostil.",
  ui_story_5004_50043001_26_dialog_content = "Pero es tan pequeño. ¿Cómo podemos pasar?",
  ui_story_5004_50043001_27_option_content = "Poner un dedo en",
  ui_story_5004_50043001_28_dialog_content = "<color=#e8d9bb>Clic.</color>",
  ui_story_5004_50043001_29_dialog_content = "Creo que acabo de presionar algo. Oye, ¿qué pasa?",
  ui_story_5004_50043001_30_dialog_content = "¡El suelo se está encogiendo! ¡Nos vamos a caer!",
  ui_story_5004_50043001_31_dialog_content = "¡...!",
  ui_story_5004_50043001_32_dialog_content = "Ella se desmayó. ¿Qué hacemos ahora? No puedo creer que el polvo pueda hacer monstruos tan horribles...",
  ui_story_5004_50043001_33_dialog_content = "Tenemos las muestras. Dejémosla aquí.",
  ui_story_5004_50043001_34_dialog_content = "Tengo curiosidad por ver su reacción cuando se despierta y ve todos estos cadáveres.",
  ui_story_5004_50043001_35_dialog_content = "Es el precio que pagas por la traición.",
  ui_story_5004_50043001_36_dialog_content = "Eres tan despiadado como los Eclipsites.",
  ui_story_5004_50043001_37_dialog_content = "¡Uh!",
  ui_story_5004_50043001_38_dialog_content = "Eso duele...",
  ui_story_5004_50043001_39_dialog_content = "¡Bájate, por favor!",
  ui_story_5004_50043001_40_dialog_content = "No puedo respirar...",
  ui_story_5004_50043001_41_dialog_content = "Casi muero ahí. ¡Apesta tener que estar abajo solo porque lo toqué primero!",
  ui_story_5004_50043001_42_dialog_content = "Gracias por salvarnos a todos, PlayerName.",
  ui_story_5004_50043001_43_dialog_content = "Si este es uno de los juegos de Gronru, deberíamos estar en el Nivel Dos ahora.",
  ui_story_5004_50043001_44_dialog_content = "¿Dices que veremos nuevos antagonistas?",
  ui_story_5004_50043001_45_dialog_content = "¡Bienvenidos, invitados de lejos!",
  ui_story_5004_50043001_46_dialog_content = "¡Aquí viene!",
  ui_story_5004_50043001_47_dialog_content = "Bienvenido a mi castillo y jardín, Sueño Vacío.",
  ui_story_5004_50043001_48_dialog_content = "¿Sueño Vacío? ¿Eres tú el dueño?",
  ui_story_5004_50043001_49_dialog_content = "Puedes pensar en mí como su amante. He vivido aquí con todos estos juguetes durante más de diez años, después de todo.",
  ui_story_5004_50043001_50_dialog_content = "¡Oh! Con juguetes, me refiero a las piezas de bienvenida. No te maltrataron, ¿verdad?",
  ui_story_5004_50043001_51_dialog_content = "¡La voz...!",
  ui_story_5004_50043001_52_dialog_content = "¡Es el de mis sueños!",
  ui_story_5004_50043001_53_dialog_content = "Entonces, ¿las Eclipsites de ajedrez son tus creaciones? ¿Por qué te ves así?",
  ui_story_5004_50043001_54_dialog_content = "Calma. Veo que el Celestita es tan curioso como se rumorea.",
  ui_story_5004_50043001_55_dialog_content = "No hemos tenido visitantes aurorians durante años, así que será mejor que me entretengas y no mueras tan fácilmente.",
  ui_story_5004_50043001_56_dialog_content = "Déjame revisar el diario de mi primer año aquí. Quizás haya una respuesta para ti.",
  ui_story_5004_50043001_57_dialog_content = "Oye, se ha ido... ¿A dónde fue ese primer diario? ¿Lo robaste?",
  ui_story_5004_50043001_58_dialog_content = "¡Oh, no, sin él, no puedo darles a los invitados mi té de la tarde especialmente preparado!",
  ui_story_5004_50043001_59_dialog_content = "¿Quizás debería abrirles el cráneo y ver si mi diario está adentro?",
  ui_story_5004_50043001_60_dialog_content = "No creo que esté pensando con claridad, PlayerName.",
  ui_story_5004_50043001_61_dialog_content = "Oye, detén la farsa. Eres el jefe de esa rata engañosa, ¿no?",
  ui_story_5004_50043001_62_dialog_content = "No hagamos nada todavía. No sabemos lo suficiente sobre este lugar. Intentemos hablar primero.",
  ui_story_5004_50043001_63_option_content = "¿Quién eres?",
  ui_story_5004_50043001_64_dialog_content = "Yo soy... uh... Déjame pensar, ¿qué estaba escrito en el segundo diario...?",
  ui_story_5004_50043001_65_dialog_content = "¡Soy un gran erudito y un verdugo despiadado!",
  ui_story_5004_50043001_66_dialog_content = "¡Guau, soy muy impresionante!",
  ui_story_5004_50043001_67_dialog_content = "(Todavía lo vende...)",
  ui_story_5004_50043001_68_option_content = "¿Qué es Sueño Vacío?",
  ui_story_5004_50043001_69_dialog_content = "¡Ahí estamos ahora! Déjame ver... Es un juego de ajedrez de pura angustia y locura mental.",
  ui_story_5004_50043001_70_dialog_content = "Eso es lo que dice en mi sexto diario.",
  ui_story_5004_50043001_71_dialog_content = "Aquí es también donde duerme el Monarca y donde prometí despertarlo.",
  ui_story_5004_50043001_72_dialog_content = "(Dado el Darkflow, hay un Eclipsite muy fuerte por aquí. ¿Podría ser el Monarca del que está hablando?)",
  ui_story_5004_50043001_73_option_content = "¿Por qué emergería del lecho marino?",
  ui_story_5004_50043001_74_dialog_content = "Buena pregunta.",
  ui_story_5004_50043001_75_dialog_content = "\"Era una ciudad magnífica antes de ser desterrada por los Celestitas malvados\".",
  ui_story_5004_50043001_76_dialog_content = "\"La raza diabólica obtuvo sus justos merecimientos cuando fueron masacrados\".",
  ui_story_5004_50043001_77_dialog_content = "¡Oye, hay mucho en este libro \"Cómo cocinar Celestitas\"!",
  ui_story_5004_50043001_78_dialog_content = "¿Qué bocadillos te gustan, Celestita? ¡Puedo convertirte en lo que quieras!",
  ui_story_5004_50043001_79_dialog_content = "(¿Desterrado por los Celestitas? ¿Aprovechó la obsesión de Bonacie por el Movimiento y diseñó la trama?)",
  ui_story_5004_50043001_80_dialog_content = "Ya tuve suficientes divagaciones, PlayerName.",
  ui_story_5004_50043001_81_option_content = "Espera, espera...",
  ui_story_5004_50043001_82_dialog_content = "Acabo de recibir algunos libros y revistas más. Hablemos un poco más.",
  ui_story_5004_50043001_83_option_content = "Esta loca...",
  ui_story_5004_50043001_84_dialog_content = "Ataquemos antes de que todos nos confundamos con ella, PlayerName.",
  ui_story_5004_50043001_85_dialog_content = "¿Qué? ¡No, por favor no me ataque!",
  ui_story_5004_50043001_86_dialog_content = "Si lo haces, yo... ¡Tendré que matarte!",
  ui_story_5004_50043001_87_dialog_content = "¡Y no puedes morir tan pronto! Tuviste dificultades para llegar aquí, así que ¿por qué no averiguar más sobre este lugar?",
  ui_story_5004_50043001_88_dialog_content = "Vamos, ¿podemos hablar? ¡No me ataques! ¡Te serviré té!",
  ui_story_5004_50043001_89_dialog_content = "Uno, dos, tres, cuatro, cinco... ¡Conseguiré porciones para cinco ahora mismo!",
  ui_story_5004_50043001_90_dialog_content = "Se fue volando... Oye, espera, ¿no tenemos seis personas?",
  ui_story_5004_50043001_91_dialog_content = "¿Dónde está Bonacie?",
  ui_story_5004_50043001_92_dialog_content = "¡Sostenlo justo ahí! ¿Qué hiciste con Bonacie?",
  ui_story_5004_50043001_93_dialog_content = "¡Qué grosero! La envié a un lugar más adecuado para una fiesta de té.",
  ui_story_5004_50043001_94_dialog_content = "Devuélvela. ¡Ahora!",
  ui_story_5004_50043001_95_dialog_content = "¿Eso es una orden? ¡Jaja, qué adorable que mi invitada me dé órdenes!",
  ui_story_5004_50043001_96_dialog_content = "Tú insolente disruptor de mi fiesta del té... No, no quiero matarte. ¡Debo controlarme!",
  ui_story_5004_50043001_97_dialog_content = "Oye, eres de Lumopolis, ¿verdad? Puedo sentirlo.",
  ui_story_5004_50043001_98_dialog_content = "Arrogante, testarudo y desaprobador.",
  ui_story_5004_50043001_99_dialog_content = "De vuelta a ti. Como Capitán de los Guardianes de Lumopolis...",
  ui_story_5004_50043001_100_dialog_content = "¡Todo Eclipsite que amenace la existencia Aurorian se enfrentará a mi ira!",
  ui_story_5004_50043001_101_dialog_content = "Je...",
  ui_story_5004_50043001_102_dialog_content = "Je, je...",
  ui_story_5004_50043001_103_dialog_content = "¡Jajaja!",
  ui_story_5004_50043001_104_dialog_content = "¡Bien dicho, muy bien dicho!",
  ui_story_5004_50043001_105_dialog_content = "No puedo luchar más, querido Capitán, ¡simplemente no puedo!",
  ui_story_5004_50043001_106_dialog_content = "¡Si insistes, jugarás con mis juguetes!",
  ui_story_5004_50043001_107_dialog_content = "¡Gahhhh!",
  ui_story_5004_50043001_108_dialog_content = "¡Cuidado, entran monstruos!",
  ui_story_5004_50043101_1_dialog_content = "Eso fue emocionante, mi capitana.",
  ui_story_5004_50043101_2_dialog_content = "Tomé un par de tazas de té viéndote pelear y eso me hizo sentir mucho mejor.",
  ui_story_5004_50043101_3_dialog_content = "Veo que todos ustedes tienen algunas heridas más y sus cambios son cada vez más lentos.",
  ui_story_5004_50043101_4_dialog_content = "Supongo que los Aurorians no son tan duros, considerando que tuviste dificultades con mis juguetes.",
  ui_story_5004_50043101_5_dialog_content = "Le sugiero que no me agite ni se precipite hacia mí. Deberías hablar conmigo, o al menos ganar algo de tiempo.",
  ui_story_5004_50043101_6_dialog_content = "En todos mis años de llevar un diario, esto es lo más emocionante que sucedió en mucho tiempo.",
  ui_story_5004_50043101_7_dialog_content = "¡Por favor, hazme compañía por un tiempo más!",
  ui_story_5004_50043101_8_dialog_content = "¿Qué es lo que realmente quieres?",
  ui_story_5004_50043101_9_dialog_content = "¿Qué es? Déjame pensar... Estoy cansado de este trabajo, ¿qué tal convertirme en un chef gourmet?",
  ui_story_5004_50043101_10_dialog_content = "Como mi favorito \"Cómo cocinar Celestitas\", debería escribir \"Cómo cocinar aurorians\".",
  ui_story_5004_50043101_11_dialog_content = "Oh, espera, no, me emociono con solo pensarlo, ¡y podría darme la necesidad de matarte de nuevo!",
  ui_story_5004_50043101_12_dialog_content = "No, es aburrido simplemente matarte, y el Monarca debe asistir a la fiesta del té que he planeado durante tanto tiempo...",
  ui_story_5004_50043101_13_dialog_content = "Ese es mi Monarca Desolado, mi nuevo maestro que me otorgó mi poder. Le encantará comer bocadillos hechos con usted.",
  ui_story_5004_50043101_14_dialog_content = "Sí, serás testigo de mi poder y sentirás el miedo y la desesperación...",
  ui_story_5004_50043101_15_dialog_content = "¡Eso te hará aún más sabroso y delicioso!",
  ui_story_5004_50043101_16_dialog_content = "¡No hay poder, solo trucos elegantes!",
  ui_story_5004_50043101_17_dialog_content = "Deja de jactarte, Eclipsite.",
  ui_story_5004_50043101_18_dialog_content = "Tus creaciones son solo baches en el camino.",
  ui_story_5004_50043101_19_dialog_content = "Crear y controlar estos títeres sin sentido te afectará.",
  ui_story_5004_50043101_20_dialog_content = "Apenas encontremos al verdadero tú, ¡se acabó!",
  ui_story_5004_50043101_21_dialog_content = "Es cierto que no tengo un poder tan grande, pero el Monarca sí.",
  ui_story_5004_50043101_22_dialog_content = "\"Algunas personas en Lumopolis codician el gran poder de los Eclipsites\".",
  ui_story_5004_50043101_23_dialog_content = "\"Algunos incluso harían tratos con Eclipsites, incluso intercambiando sus cuerpos y vidas para obtener Darkflow.\"",
  ui_story_5004_50043101_24_dialog_content = "Déjame ver... Este libro tiene más de una década. ¿Lumopolis sigue siendo así?",
  ui_story_5004_50043101_25_dialog_content = "¿Le importaría decirme cómo se siente proteger a esos traidores, querido capitán?",
  ui_story_5004_50043101_26_dialog_content = "Tus palabras no me tientan, hereje.",
  ui_story_5004_50043101_27_dialog_content = "Nada mal. Veo que se necesitan más músculos para ser un capitán.",
  ui_story_5004_50043101_28_dialog_content = "Así que ya sabes el desastre que es Lumopolis.",
  ui_story_5004_50043101_29_dialog_content = "Sí, la llamada ciudad que nunca cae, las altas torres blancas...",
  ui_story_5004_50043101_30_dialog_content = "Los supuestos campeones de la esperanza en realidad son mentirosos nobles...",
  ui_story_5004_50043101_31_dialog_content = "¡Los engañosos charlatanes de dos caras!",
  ui_story_5004_50043101_32_dialog_content = "¡Quién hubiera pensado que farsantes pretenciosos estarían entre las élites gobernantes!",
  ui_story_5004_50043101_33_dialog_content = "¿No es así, eh, eh, eh?",
  ui_story_5004_50043101_34_dialog_content = "¡<color=#FFB400>Beryl Gautier</color>!",
  ui_story_5004_50043101_35_dialog_content = "Me conoces... ¿Quién eres? ¿Cómo me conoces?",
  ui_story_5004_50043101_36_dialog_content = "Gautier, Gautier, Gautier...",
  ui_story_5004_50043101_37_dialog_content = "¡Claro que te reconozco, y también a tu ridícula familia!",
  ui_story_5004_50043101_38_dialog_content = "¡Tu nombre está en cada uno de mis diarios!",
  ui_story_5004_50043101_39_dialog_content = "¿No estás aquí para expiar la sangre que corre por tus venas y los pecados que llevas?",
  ui_story_5004_50043101_40_dialog_content = "Sabían lo potente que es el cristal...",
  ui_story_5004_50043101_41_dialog_content = "Y aun así intentaron engañar a la muerte. ¡Qué absurdo!",
  ui_story_5004_50043101_42_dialog_content = "¡Eso es poder, poder puro, que debería usarse para conquistar y destruir!",
  ui_story_5004_50043101_43_dialog_content = "¡No es un juguete para payasos, especialmente los de Lumopolis!",
  ui_story_5004_50043101_44_dialog_content = "¿Cómo sabes tanto de mi familia...?",
  ui_story_5004_50043101_45_dialog_content = "¿Cómo? Oh, entonces no te acuerdas. ¡Eso es genial! Espera, no, no es genial, ¡qué lástima!",
  ui_story_5004_50043101_46_dialog_content = "Qué lástima, qué lástima... Puede evitarlo si mantiene diarios como yo.",
  ui_story_5004_50043101_47_dialog_content = "Te prepararé una ración extra, hecha con la chica que tienes a tu lado.",
  ui_story_5004_50043101_48_dialog_content = "¡No te atrevas a tocar a Raphaela!",
  ui_story_5004_50043101_49_dialog_content = "Pequeña Beryl...",
  ui_story_5004_50043101_50_dialog_content = "¿Oh? Está bien, está bien, no la tocaré. ¡Je!",
  ui_story_5004_50043101_51_dialog_content = "Y si no lo hago, ¿crees que puedes protegerla como un simple peón?",
  ui_story_5004_50043101_52_dialog_content = "¡Escribiré sinceramente sobre su conmovedora relación con todo detalle!",
  ui_story_5004_50043101_53_dialog_content = "¡Vivirás en mis escritos después de tu muerte!",
  ui_story_5004_50043101_54_dialog_content = "¿Cómo debo llamarlo? ¿\"Inocencia tonta\"? ¿\"Triste canción de un peón\"?",
  ui_story_5004_50043101_55_dialog_content = "¡Todos ustedes Aurorians me hacen reír con su estupidez, tanto que quiero atarlos a cada uno de ustedes e interrogarlos por un libro!",
  ui_story_5004_50043101_56_dialog_content = "¡Ah, claro, y convertirte en bocadillos para acompañar mi té!",
  ui_story_5004_50043101_57_dialog_content = "Leer las historias de su vida mientras saborea su carne y sangre...",
  ui_story_5004_50043101_58_dialog_content = "Toma ese estúpido aurorian, el tema de mi libro \"Músico tonto\", por ejemplo.",
  ui_story_5004_50043101_59_dialog_content = "Ella solo quería tocar música y sin saberlo rompió el sello.",
  ui_story_5004_50043101_60_dialog_content = "Envié Eclipsites al hotel y <color=#FFB400>instalé trampas</color>... Luego sostuve el Soberano del Océano para desviar el Lumina de todos los Aurorians asistentes.",
  ui_story_5004_50043101_61_dialog_content = "¡Ustedes jugaron un papel importante en revivir al Monarca Desolado!",
  ui_story_5004_50043101_62_dialog_content = "Soy un perfecto estratega, táctico, conspirador, jugador de ajedrez... ¡oh sí, y autor!",
  ui_story_5004_50043101_63_dialog_content = "Te olvidaste lunático. ¡Perdiste la cabeza por estar aquí mucho tiempo!",
  ui_story_5004_50043101_64_dialog_content = "¿Qué? Cómo te atreves... ¿Cómo te atreves a decir algo que tenga que registrar?",
  ui_story_5004_50043101_65_dialog_content = "Antes de convertirte en postre, trata de que mis juguetes no te maten, te lo ruego.",
  ui_story_5004_50043101_66_dialog_content = "¡Por favor, sobrevive!",
  ui_story_5004_50043201_1_dialog_content = "Huff, huff...",
  ui_story_5004_50043201_2_dialog_content = "Tu nariz sangra de nuevo, PlayerName. No lo presiones.",
  ui_story_5004_50043201_3_dialog_content = "Estoy bien, solo un poco cansada.",
  ui_story_5004_50043201_4_dialog_content = "(La lucha constante me está pasando factura...)",
  ui_story_5004_50043201_5_dialog_content = "¿Se acabó la pelea? Estoy comenzando el próximo postre.",
  ui_story_5004_50043201_6_dialog_content = "Mis comentarios sobre tu última batalla son...",
  ui_story_5004_50043201_7_dialog_content = "\"Un niño dirigiendo una pelea peleó con la velocidad de una anciana que balancea un bastón\".",
  ui_story_5004_50043201_8_dialog_content = "Honestamente, te vuelves cada vez más lento. Tenía cuatro tazas de té y un bocadillo esperándote.",
  ui_story_5004_50043201_9_dialog_content = "¿Tú... crees que esto es un juego?",
  ui_story_5004_50043201_10_dialog_content = "¿Estás orgulloso de enviar ilusiones y clones a luchar contra nosotros?",
  ui_story_5004_50043201_11_dialog_content = "¡Sal y lucha en persona si tienes agallas!",
  ui_story_5004_50043201_12_dialog_content = "¿Llamarme cuando ni siquiera podías vencer a mis patéticos juguetes?",
  ui_story_5004_50043201_13_dialog_content = "Quiero saber más sobre ti, ya que creo que la comida es más sabrosa cuando está llena de emociones.",
  ui_story_5004_50043201_14_dialog_content = "Además, el Monarca Desolado todavía está reuniendo su poder. Hay tiempo para hablar.",
  ui_story_5004_50043201_15_dialog_content = "¡Oh, encontré el primer diario! Déjame ver lo que escribí...",
  ui_story_5004_50043201_16_dialog_content = "Bwajaja, ¡bravo! ¡Ven y déjame que te lo lea!",
  ui_story_5004_50043201_17_dialog_content = "Ejem, permíteme aclaro mi garganta.",
  ui_story_5004_50043201_18_dialog_content = "¿Por qué tu diminuto cerebro no puede entenderlo, pequeña niña Gautier?",
  ui_story_5004_50043201_19_dialog_content = "¿Quién sabría tanto sobre los cristales y quién podría llamarte en tus sueños?",
  ui_story_5004_50043201_20_dialog_content = "Eres tú... Eres el único Pyrrhus superviviente... que desertó a los Eclipsites... ¡Caroline Pyrrhus!",
  ui_story_5004_50043201_21_dialog_content = "¡Sí, la única!",
  ui_story_5004_50043201_22_dialog_content = "¡Oh no, es vergonzoso escuchar mi antiguo nombre aurorian!",
  ui_story_5004_50043201_23_dialog_content = "Sabía que no debería leerle diarios a la gente.",
  ui_story_5004_50043201_24_dialog_content = "Todavía quiero, ¡así que préstame tus oídos!",
  ui_story_5004_50043201_25_dialog_content = "¿Eras un aurorian?",
  ui_story_5004_50043201_26_dialog_content = "Otra que se sometió y vendió su alma a los Eclipsites.",
  ui_story_5004_50043201_27_dialog_content = "Je, es cierto, casi me olvido de que una vez fui aurorian.",
  ui_story_5004_50043201_28_dialog_content = "Pero el diario está lleno de detalles sobre lo libre y feliz que soy después de convertirme en un Eclipsite.",
  ui_story_5004_50043201_29_dialog_content = "¡Mucho más feliz que en Lumopolis!",
  ui_story_5004_50043201_30_dialog_content = "Ahora al tema. Como dije, a diferencia de mi familia, su familia solo quería usar el cristal como fuente de energía...",
  ui_story_5004_50043201_31_dialog_content = "¡Cuando su brutal y despiadado poder debería aprovecharse como arma!",
  ui_story_5004_50043201_34_dialog_content = "¡Podría haber sido la fuerza para repeler a los Eclipsites de Lumopolis, enviándolos de regreso al abismo!",
  ui_story_5004_50043201_35_dialog_content = "¡Pero, su débil familia le gritó al señor de la ciudad por eso! ¡Estoy empezando a enojarme de nuevo por leer esta parte!",
  ui_story_5004_50043201_36_dialog_content = "Ustedes Pyrrhuses estaban secuestrando aurorians oprimidos y experimentando con ellos con los cristales.",
  ui_story_5004_50043201_37_dialog_content = "¡Nadie sensato toleraría experimentar con los de su propia especie!",
  ui_story_5004_50043201_38_dialog_content = "Admito que me gustaban mucho los experimentos cuando era joven.",
  ui_story_5004_50043201_39_dialog_content = "Pero sin mí, no existiría el Beryl que ves ahora, mi tema más orgulloso...",
  ui_story_5004_50043201_40_dialog_content = "No me digas Beryl...",
  ui_story_5004_50043201_41_dialog_content = "...",
  ui_story_5004_50043201_42_dialog_content = "La revista tiene información muy detallada. Tu comida favorita, deporte favorito...",
  ui_story_5004_50043201_43_dialog_content = "Incluso lo que te gusta sostener cuando duermes.",
  ui_story_5004_50043201_44_dialog_content = "¡Es como si el autor estuviera enamorado de ti!",
  ui_story_5004_50043201_45_dialog_content = "Espera, yo soy el autor, eso me convierte en un voyeur.",
  ui_story_5004_50043201_46_dialog_content = "Aunque no del todo impecable, fue un hito en mi experimentación.",
  ui_story_5004_50043201_47_dialog_content = "Y te puse amor...",
  ui_story_5004_50043201_48_dialog_content = "Los cristales en polvo especiales hechos con Darkflow todavía crecen en tu cuerpo, ¿no es así?",
  ui_story_5004_50043201_49_dialog_content = "Viven dentro de ti, alimentándose de tus emociones y voluntad.",
  ui_story_5004_50043201_50_dialog_content = "Alto...",
  ui_story_5004_50043201_51_dialog_content = "Definitivamente son inestables ... ¡Je, aquí estamos, mi sección favorita!",
  ui_story_5004_50043201_52_dialog_content = "Oh, ese enorme incendio que comenzaste y los gritos de esas innumerables víctimas Aurorians...",
  ui_story_5004_50043201_53_dialog_content = "¡Para!",
  ui_story_5004_50043201_54_dialog_content = "¡No te pongas engreída!",
  ui_story_5004_50043201_55_dialog_content = "Je, el Monarca me está llamando...",
  ui_story_5004_50043201_56_dialog_content = "Regresaré pronto y te convertiré en delicias deliciosas como esos Aurorians tostados.",
  ui_story_5004_50043201_57_dialog_content = "¡No, no, no, no, no!",
  ui_story_5004_50043201_58_dialog_content = "¡Cálmate, Beryl!",
  ui_story_5004_50043201_59_dialog_content = "¡Raphaela, déjame tratar de calmarla con telepatía!",
  ui_story_5004_50043201_60_dialog_content = "Por favor, apúrate. Ella parece estar sufriendo mucho...",
  ui_story_5004_50043201_61_dialog_content = "(Siento una fuerza salvaje recorriendo su cuerpo).",
  ui_story_5004_50043201_62_dialog_content = "(Definitivamente es algo que ningún aurorian poseería, pero tampoco es Darkflow.)",
  ui_story_5004_50043201_63_dialog_content = "(Tal vez sea una fuerza destructiva y maliciosa como dijo Caroline.)",
  ui_story_5004_50043201_64_dialog_content = "(Beryl ha estado luchando por mantenerlo bajo control, solo para que Caroline la provoque...)",
  ui_story_5004_50043201_65_dialog_content = "(Y pierde el control poco a poco.)",
  ui_story_5004_50043201_66_dialog_content = "Pequeña Beryl...",
  ui_story_5004_50043201_67_dialog_content = "Raphaela... Estoy bien ahora... Gracias, PlayerName.",
  ui_story_5004_50043201_68_dialog_content = "Lo siento... No quise ocultarte mi pasado...",
  ui_story_5004_50043201_69_dialog_content = "Pero probablemente sea por los experimentos de Caroline... o tal vez instintivamente me negué a recordar los dolorosos recuerdos...",
  ui_story_5004_50043201_70_dialog_content = "Esa parte del pasado es un gran borrón para mí...",
  ui_story_5004_50043201_71_dialog_content = "Solo recuerdo que los Pyrrhuses me secuestraron cuando era muy joven.",
  ui_story_5004_50043201_72_dialog_content = "Me encerraron en una habitación oscura... me alimentaron con cristales en polvo.",
  ui_story_5004_50043201_73_dialog_content = "Mi cuerpo actuó como si estuviera maldito... No pude escapar de los cristales que me trajeron agonía.",
  ui_story_5004_50043201_74_dialog_content = "No fue hasta más tarde que descubrí... que era un experimento de Pyrrhus para convertir aurorians en armas... a través de los cristales.",
  ui_story_5004_50043201_75_dialog_content = "Está bien, Beryl. Todos tienen su propio pasado.",
  ui_story_5004_50043201_76_dialog_content = "Comparte los momentos felices y olvídate de los desagradables. Nadie te culpa por querer una nueva vida.",
  ui_story_5004_50043201_77_dialog_content = "Estoy bien con eso. Mi pasado no es mucho mejor que el tuyo.",
  ui_story_5004_50043201_78_dialog_content = "Tampoco me importa. No es necesario que se avergüence.",
  ui_story_5004_50043201_79_dialog_content = "Somos amigos, y confío en el presente, ¡sin importar lo que sucedió en el pasado!",
  ui_story_5004_50043201_80_dialog_content = "Sin lugar a dudas, el problema urgente es castigar a Caroline por los pecados que cometió y evitar que sucedan más tragedias.",
  ui_story_5004_50043201_81_dialog_content = "Estoy con ustedes, naturalmente.",
  ui_story_5004_50043201_82_dialog_content = "Gracias a todos...",
  ui_story_5004_50043201_83_dialog_content = "Caroline Pyrrhus... No tiene ningún honor de la que hablar como antigua noble.",
  ui_story_5004_50043201_84_dialog_content = "No solo conspiró con los Eclipsites, sino que también cometió atrocidades contra su propia gente.",
  ui_story_5004_50043201_85_dialog_content = "Luego está el Monarca que ella veneraba. Si él es tan poderoso como ella retrató...",
  ui_story_5004_50043201_86_dialog_content = "Debemos evitar que el Monarca se despierte.",
  ui_story_5004_50043201_87_dialog_content = "Pero, ¿cómo vamos a encontrar su forma real en esta ilusión?",
  ui_story_5004_50043201_88_dialog_content = "Cuando PlayerName me estaba ayudando telepáticamente...",
  ui_story_5004_50043201_89_dialog_content = "Creo que sentí una mancha con muchos cristales...",
  ui_story_5004_50043201_90_dialog_content = "Probablemente ahí es donde se esconden...",
  ui_story_5004_50043201_91_dialog_content = "¡Buen trabajo! ¡Vayamos allí!",
  ui_story_5004_50043201_92_dialog_content = "Sí, y será una batalla agotadora.",
  ui_story_5004_50043201_93_dialog_content = "¡No te preocupes, Beryl, recibiré la venganza de esa bruja por ti!",
  ui_story_5004_50043201_94_dialog_content = "Sí... Luego volvemos a Lumopolis como prometimos.",
  ui_story_5004_50043201_95_dialog_content = "No importa los enemigos que aguarden, ¡no daré marcha atrás!",
  ui_story_5004_50043301_1_dialog_content = "Vaya, no pensé que pudieras encontrar este lugar.",
  ui_story_5004_50043301_2_dialog_content = "¡Ejem! \"Les agradezco que hayan venido al <color=#FFB400>Salón del Trono</color> para arrodillarse ante su nuevo gobernante.\"",
  ui_story_5004_50043301_3_dialog_content = "\"Es mi nueva forma creada a partir de los cristales, con poderes idénticos a los tuyos, Beryl.\"",
  ui_story_5004_50043301_4_dialog_content = "\"La diferencia es que solo eres un prototipo y yo soy el producto final capaz de controlar todo el poder de los cristales.\"",
  ui_story_5004_50043301_5_dialog_content = "\"Y el <color=#FFB400>Monarca Desolado</color> también revivirá a través de los cristales y gobernará una vez más\".",
  ui_story_5004_50043301_6_dialog_content = "Ejem, es el comienzo del elogio que escribí para todos ustedes. ¿Te gusta?",
  ui_story_5004_50043301_7_dialog_content = "<color=#e8d9bb>Caroline agita su mano y los cristales se rompen. Luego, la tormenta de polvo es absorbida por la Monarca.</color>",
  ui_story_5004_50043301_8_dialog_content = "...",
  ui_story_5004_50043301_9_dialog_content = "¿Ves eso? ¡Cuán compatible es el poder del cristal con Eclipsites!",
  ui_story_5004_50043301_10_dialog_content = "¡Pensé que era una bendición de los dioses para los aurorians! ¡Me avergüenza esa idea!",
  ui_story_5004_50043301_11_dialog_content = "¡Obviamente es un regalo para los Eclipsites!",
  ui_story_5004_50043301_12_dialog_content = "Ya es suficiente de tus ladridos.",
  ui_story_5004_50043301_13_dialog_content = "¡Luchemos al aire libre!",
  ui_story_5004_50043301_14_dialog_content = "Finalmente, finalmente... Je... ¡Jaja! ¡Estoy en el punto en el que quiero matarte ahora!",
  ui_story_5004_50043301_15_dialog_content = "¡Date prisa! ¡Más dolor, más desesperación por más sabor!",
  ui_story_5004_50043302_1_dialog_content = "¡Maldita sea, siguen viniendo!",
  ui_story_5004_50043302_2_dialog_content = "Deja de jugar con los peones... ¡Arde bebe, arde!",
  ui_story_5004_50043302_3_dialog_content = "Imposible... Yo...",
  ui_story_5004_50043302_4_dialog_content = "¡Tiro directo a la cabeza! ¡Se desvanece!",
  ui_story_5004_50043302_5_dialog_content = "¿Lo hicimos?",
  ui_story_5004_50043302_6_dialog_content = "...",
  ui_story_5004_50043302_7_dialog_content = "¡Je, te engañé!",
  ui_story_5004_50043302_8_dialog_content = "!",
  ui_story_5004_50043302_9_dialog_content = "¡Smokey!",
  ui_story_5004_50043302_10_dialog_content = "Eso duele... ¡Fuera de mí!",
  ui_story_5004_50043302_11_dialog_content = "No esperaba la emboscada. Gracias por cuidarme.",
  ui_story_5004_50043302_12_dialog_content = "Es una herida profunda. ¡Deja que Raphaela se encargue!",
  ui_story_5004_50043302_13_dialog_content = "(¡Diablos, no está bajando! Y Eclipsites siguen apareciendo por todas partes...)",
  ui_story_5004_50043302_14_dialog_content = "(¡Es imposible, nunca antes había conocido a un Eclipsite convertido tan poderoso!)",
  ui_story_5004_50043302_15_dialog_content = "(¿Podría el Monarca tener algo que ver con eso...?)",
  ui_story_5004_50043302_16_dialog_content = "¡Concéntrate, PlayerName! ¡La marea de la batalla todavía podría cambiar!",
  ui_story_5004_50043302_17_dialog_content = "Busca cualquier abertura.",
  ui_story_5004_50043302_18_dialog_content = "¡Tú, habla más alto para que pueda escribir tus últimas palabras en mi diario!",
  ui_story_5004_50043302_19_dialog_content = "¡Florece!",
  ui_story_5004_50043302_20_dialog_content = "*Tose*... Qué humo más denso. ¿Beryl detonó los cristales de Caroline como defensa?",
  ui_story_5004_50043302_21_dialog_content = "...",
  ui_story_5004_50043302_22_dialog_content = "Nada mal, nada mal.",
  ui_story_5004_50043302_23_dialog_content = "¿Cómo es eso posible...?",
  ui_story_5004_50043302_24_dialog_content = "¿Cómo es que no tiene un rasguño?",
  ui_story_5004_50043302_25_dialog_content = "De ninguna manera...",
  ui_story_5004_50043302_26_dialog_content = "Muy impresionante para un prototipo.",
  ui_story_5004_50043302_27_dialog_content = "Igual, mi pobre Beryl, mi experimento fallido...",
  ui_story_5004_50043302_28_dialog_content = "Tan inútil como siempre.",
  ui_story_5004_50043302_29_dialog_content = "Mataste a tanta gente, mataste a tus padres... ¿A quién crees que puedes salvar ahora?",
  ui_story_5004_50043302_30_dialog_content = "Te lo advertí, serás la muerte de todos los que te rodean antes de caer al abismo.",
  ui_story_5004_50043302_31_dialog_content = "Yo no...",
  ui_story_5004_50043302_32_dialog_content = "¿Padres...?",
  ui_story_5004_50043302_33_dialog_content = "¡Gahhhhhh!",
  ui_story_5004_50043302_34_dialog_content = "¡No me detengan, monstruos!",
  ui_story_5004_50043302_35_dialog_content = "¡Carleen y Vice, cubran a Raphaela!",
  ui_story_5004_50043302_36_dialog_content = "Sé que todavía recuerdas cómo mataste a tus indefensos padres...",
  ui_story_5004_50043302_37_dialog_content = "Acepta tu desaparición. Es la expiación por tus crímenes. Es tu salvación.",
  ui_story_5004_50043302_38_dialog_content = "Lo siento, todos... Lo siento, madre y padre...",
  ui_story_5004_50043302_39_dialog_content = "¡Beryl!",
  ui_story_5004_50043302_40_dialog_content = "No la escuches, Beryl. ¡Ella mató a tus padres!",
  ui_story_5004_50043302_41_dialog_content = "Perdiste el control y provocaste el incendio, ¡y luego te desmayaste de inmediato!",
  ui_story_5004_50043302_42_dialog_content = "¡Te tomó como rehén y asesinó a tus padres y a tu familia!",
  ui_story_5004_50043302_43_dialog_content = "...",
  ui_story_5004_50043302_44_dialog_content = "Es una confesión de miembros de Pyrrhus detenidos, ¡así que es la verdad!",
  ui_story_5004_50043302_45_dialog_content = "¡Entrometido!",
  ui_story_5004_50043302_46_dialog_content = "¡Uh!",
  ui_story_5004_50043302_47_dialog_content = "Je, eso fue un giro inesperado.",
  ui_story_5004_50043302_48_dialog_content = "Pero, pero... ¡Jaja!",
  ui_story_5004_50043302_49_dialog_content = "¡De verdad lo creíste!",
  ui_story_5004_50043302_50_dialog_content = "!",
  ui_story_5004_50043302_51_dialog_content = "Entonces, ¿recuerdas cómo se veían los cadáveres de tus padres cuando volviste?",
  ui_story_5004_50043302_52_dialog_content = "¡Lo organicé específicamente para ti, solo para que pienses que los mataste!",
  ui_story_5004_50043302_53_dialog_content = "¡Tan estúpido, tan estúpido, tan estúpido que te enamores de eso! ¡Y tanto tiempo después!",
  ui_story_5004_50043302_54_dialog_content = "Acaso...",
  ui_story_5004_50043302_55_dialog_content = "¡Me da escalofríos de emoción cada vez que llego a esta parte del diario!",
  ui_story_5004_50043302_56_dialog_content = "¡Debes pensar que mataste a tus padres todo este tiempo!",
  ui_story_5004_50043302_57_dialog_content = "¡Este diario es mi posesión más preciada y quiero compartirlo con ustedes!",
  ui_story_5004_50043302_58_dialog_content = "¡Una gran razón por la que te dejo vivir es para poder escribir la expresión de tu rostro ahora mismo!",
  ui_story_5004_50043302_59_dialog_content = "¿Feliz ahora? Has vivido creyendo que mataste a tus seres queridos durante tanto tiempo.",
  ui_story_5004_50043302_60_dialog_content = "¡Tu expresión cuando finalmente descubriste la verdad fue exquisita!",
  ui_story_5004_50043302_61_dialog_content = "¡Te voy a arrancar la cara para hacer la portada de mi diario!",
  ui_story_5004_50043302_62_dialog_content = "¡Gautier, Gautier! ¡Así debe terminar un traidor de Gautier!",
  ui_story_5004_50043302_63_dialog_content = "¡Cómo te atreves!",
  ui_story_5004_50043302_64_dialog_content = "¡Un prototipo fallido como tú ni siquiera puedes soñar con oponerme al infalible yo y al Monarca que despierta!",
  ui_story_5004_50043302_65_dialog_content = "Por culparme de asesinatos y tratar de lastimar a mis amigos...",
  ui_story_5004_50043302_66_dialog_content = "¡Nunca te perdonaré!",
  ui_story_5004_50043302_67_dialog_content = "¿Es este el poder que Beryl ha estado suprimiendo?",
  ui_story_5004_50043302_68_dialog_content = "Si desatas el poder, ¡podrías convertirte en un monstruo como Caroline!",
  ui_story_5004_50043302_69_dialog_content = "Perdí a mis seres queridos y me sumí en el dolor y la culpa porque era pequeño y débil...",
  ui_story_5004_50043302_70_dialog_content = "¡El culpable está ante mí tratando de dañar a mis seres queridos!",
  ui_story_5004_50043302_71_dialog_content = "¡Caroline Pyrrhus!",
  ui_story_5004_50043302_72_dialog_content = "¡Te arrastraré al infierno conmigo, aun si tengo que perder el control!",
  ui_story_5004_50043302_73_dialog_content = "Un ataque tan salvaje...",
  ui_story_5004_50043302_74_dialog_content = "¡Caroline está atrapada! Espera, aunque los cristales la inmovilizaron, ¡todavía no va a caer!",
  ui_story_5004_50043302_75_dialog_content = "¡Truco de salón! ¡Concédeme más poder, mi señor! ¡Permíteme castigar a los que se atrevieron a desafiarte!",
  ui_story_5004_50043302_76_dialog_content = "...",
  ui_story_5004_50043302_77_dialog_content = "¡Creo que lo tengo! Aunque no estoy seguro de eso.",
  ui_story_5004_50043302_78_dialog_content = "¡La inmortalidad de Caroline está vinculada al Monarca!",
  ui_story_5004_50043302_79_dialog_content = "¡Centra tu ataque en ellos mientras Caroline está atrapada!",
  ui_story_5004_50043402_1_dialog_content = "¡...!",
  ui_story_5004_50043402_2_dialog_content = "Acaso... ¡Te atreves...!",
  ui_story_5004_50043402_3_dialog_content = "¡Te atreves a destruir lo que me tomó años alcanzar!",
  ui_story_5004_50043402_4_dialog_content = "¡Es nuestro turno de contraatacar!",
  ui_story_5004_50043402_5_dialog_content = "¡Pagarás el precio de lastimarme con tu vida!",
  ui_story_5004_50043402_6_dialog_content = "No puede ser... ¡Es imposible para mí perder contra ustedes, debiluchos!",
  ui_story_5004_50043402_7_dialog_content = "Son meras piezas... Imposible... Soy un cristólogo de Lumopolis... ¡Soy la reina aquí!",
  ui_story_5004_50043402_8_dialog_content = "¡Mi señor! ¡Dame más poder! ¿Por qué no te escucho?",
  ui_story_5004_50043402_9_dialog_content = "Debo... continuar... ¡No ha terminado! ¡Mi fiesta de té...!",
  ui_story_5004_50043402_10_dialog_content = "¡Malditos! ¡Únete y tendremos aurorians más sabrosos! ¡Traidores insolentes!",
  ui_story_5004_50043402_11_dialog_content = "Te desterraré para siempre a...",
  ui_story_5004_50043402_12_dialog_content = "No quiero más de tu galimatías. ¡Vete!",
  ui_story_5004_50043402_13_dialog_content = "No dejaré que arruines... la fiesta del té... ¡Arrgh!",
  ui_story_5004_50043402_14_dialog_content = "Resoplan...",
  ui_story_5004_50043402_15_dialog_content = "¿Lo hicimos esta vez?",
  ui_story_5004_50043402_16_dialog_content = "¡Tienes muchos cristales encima, Beryl!",
  ui_story_5004_50043402_17_dialog_content = "Está bien, Raphaela... siempre que tú y todos los demás estén bien...",
  ui_story_5004_50043402_18_dialog_content = "Finalmente... Vengué a mi familia... y te protegí... Maravilloso...",
  ui_story_5004_50043402_19_dialog_content = "¡Despierta, Beryl! ¡No te duermas!",
  ui_story_5004_50043402_20_dialog_content = "¡Debemos llevar a Beryl de regreso a Lumopolis, PlayerName!",
  ui_story_5004_50043402_21_dialog_content = "Pero todavía no podemos encontrar a Bonacie y no sabemos la salida...",
  ui_story_5004_50043402_22_dialog_content = "¡Espera, el suelo se está rompiendo!",
  ui_story_5004_50043402_23_dialog_content = "¡Cuidado!",
  ui_story_5004_50043402_24_dialog_content = "!",
  ui_story_5004_50043402_25_dialog_content = "¿A dónde caeremos en este momento?",
  ui_story_5004_50043402_26_dialog_content = "Te desterraré para siempre a...",
  ui_story_5004_50043402_27_dialog_content = "La fiesta... la fiesta del té... nunca terminará...",
  ui_story_5004_50043402_28_dialog_content = "Je je..."
}
return config
